export type ActiveCombatRoundState = Omit<CombatRoundState, "rounds">;

const activeCombatRoundStateShape = {
  adjustDistanceProposals: z.array(combatAdjustDistanceProposalSchema).default([]),
  breakOffProposals: z.array(combatBreakOffProposalSchema).default([]),
  activeParticipantId: idSchema.optional(),
  combatExperienceDifficulty: z.number().int().positive().optional(),
  commands: z.array(combatRoundCommandSchema).default([]),
  continuedContacts: z.array(continuedContactSchema).default([]),
  disarmAttempts: z.array(combatDisarmAttemptSchema).default([]),
  disarmUnbalancedConditions: z.array(combatDisarmUnbalancedConditionSchema).default([]),
  currentCursor: combatRoundCursorSchema.optional(),
  currentStep: combatRoundStepSchema.default("select_actions"),
  defenseSnapshots: z.array(combatDefenseSnapshotSchema).default([]),
  distanceState: combatDistanceStateSchema.default({ edges: {} }),
  engagements: z.array(combatEngagementSchema).default([]),
  encounterId: idSchema.optional(),
  events: combatStepEventArraySchema.default([]),
  feintProposals: z.array(combatFeintProposalSchema).default([]),
  genericActions: z.array(combatGenericActionSchema).default([]),
  missileReadiness: z.array(combatMissileReadinessSchema).default([]),
  gmBacktrackHold: combatRoundGmBacktrackHoldSchema.optional(),
  offensiveParryContests: z.array(offensiveParryContestSchema).default([]),
  observationAttempts: z.array(combatObservationAttemptSchema).default([]),
  observationRelationships: z.array(combatObservationRelationshipSchema).default([]),
  phaseResolutionCursor: combatRoundPhaseResolutionCursorSchema.optional(),
  phaseResolutionResults: z.array(combatRoundPhaseResolutionResultSchema).default([]),
  phaseResolutionStatuses: combatRoundPhaseResolutionStatusesSchema.default({}),
  participants: z.array(combatRoundParticipantStateSchema).default([]),
  roundEndReview: combatRoundEndReviewSchema.optional(),
  roundNumber: z.number().int().positive().default(1),
  selectedParticipantId: idSchema.optional(),
  selectedStep: combatRoundStepSchema.optional(),
  stepSnapshots: z.array(combatRoundStepSnapshotSchema).default([]),
  unbalancedConditions: z.array(unbalancedCombatConditionSchema).default([]),
};

/**
 * Canonical mutable-round read view. Archived rounds are intentionally not
 * accepted here so active-state consumers cannot acquire history implicitly.
 */
export const activeCombatRoundStateSchema: z.ZodType<
  ActiveCombatRoundState,
  z.ZodTypeDef,
  unknown
> = z.preprocess(
  normalizeCombatRoundAttackResultAuthorityInput,
  z.object(activeCombatRoundStateShape).strict(),
);

export const combatRoundStateSchema: z.ZodType<CombatRoundState, z.ZodTypeDef, unknown> =
  z.preprocess(
    normalizeCombatRoundAttackResultAuthorityInput,
    z.object({
      ...activeCombatRoundStateShape,
      rounds: z.array(completedCombatRoundSchema).default([]),
    }),
  );

export type CombatRoundStepStatus = z.infer<typeof combatRoundStepStatusSchema>;
export type CombatRoundDeclaration = z.infer<typeof combatRoundDeclarationSchema>;
export type CombatRoundPhaseContexts = z.infer<typeof combatRoundPhaseContextsSchema>;
export type CombatRoundInitiativeResult = z.infer<typeof combatRoundInitiativeResultSchema>;
export type CombatRoundInitiatives = z.infer<typeof combatRoundInitiativesSchema>;
export type CombatRoundCombatExperienceRollResult = z.infer<
  typeof combatRoundCombatExperienceResultSchema
>;
export type CombatRoundAttackRollResult = z.infer<typeof combatRoundAttackRollResultSchema>;
export type CombatRoundAttackResults = z.infer<typeof combatRoundAttackResultsSchema>;
export type CombatRoundPhaseResolutionCursor = z.infer<
  typeof combatRoundPhaseResolutionCursorSchema
>;
export type CombatRoundPhaseResolutionResult = z.infer<
  typeof combatRoundPhaseResolutionResultSchema
>;
export type CombatRoundPhaseResolutionParticipantStatus = z.infer<
  typeof combatRoundPhaseResolutionParticipantStatusSchema
>;
export type CombatRoundPhaseResolutionStatuses = z.infer<
  typeof combatRoundPhaseResolutionStatusesSchema
>;
export type CombatRoundParticipantState = z.infer<typeof combatRoundParticipantStateSchema>;
export type CombatRoundStepSnapshot = z.infer<typeof combatRoundStepSnapshotSchema>;

function getCombatRoundObservationDeclaration(
  declaration?: CombatRoundDeclaration,
): { targetParticipantId: string } | undefined {
  const secondaryAction =
    declaration?.secondaryActions?.find((action) => action.action === "observe_opponent") ??
    (declaration?.secondaryActionId === "observe_opponent" &&
    declaration.secondaryActionContext?.action === "observe_opponent"
      ? declaration.secondaryActionContext
      : undefined);

  return declaration?.actionId === "parry" && secondaryAction?.action === "observe_opponent"
    ? { targetParticipantId: secondaryAction.targetParticipantId }
    : undefined;
}

function getCombatRoundAttackResults(state: CombatRoundState): CombatRoundAttackRollResult[] {
  const results = new Map<string, CombatRoundAttackRollResult>();
  for (const participant of state.participants) {
    for (const result of Object.values(participant.attackResultsByOpportunity ?? {})) {
      const key = getCombatRoundCanonicalAttackResultKey({
        result,
        roundNumber: state.roundNumber,
      });
      results.set(key, result);
    }
  }
  return [...results.values()];
}

/**
 * Returns whether an incoming attack remains a hit after the canonical defence
 * lineage has finished. The attack roll's `hit` flag is deliberately only the
 * pre-defence outcome: a successful linked parry negates that hit.
 */
export function combatRoundAttackRemainsHitAfterDefense(input: {
  result: CombatRoundAttackRollResult;
  state: CombatRoundState;
}): boolean {
  if (!input.result.hit) return false;
  const attackResultId = getCombatRoundAttackResultId({
    result: input.result,
    roundNumber: input.state.roundNumber,
  });
  const resolution = input.state.phaseResolutionResults.find(
    (entry) => entry.attackResultId === attackResultId,
  );
  return resolution?.parryResolution.success !== true;
}

function combatRoundObserverWasHitByTarget(input: {
  observerParticipantId: string;
  results: readonly CombatRoundAttackRollResult[];
  state: CombatRoundState;
  targetParticipantId: string;
}): boolean {
  return input.results.some(
    (result) =>
      result.attackerParticipantId === input.targetParticipantId &&
      result.defenderParticipantId === input.observerParticipantId &&
      combatRoundAttackRemainsHitAfterDefense({ result, state: input.state }),
  );
}

export interface PendingCombatObservationAttempt {
  attemptId: string;
  observerParticipantId: string;
  relationshipId: string;
  requiredQualifyingRounds: number;
  targetParticipantId: string;
}

/**
 * Projects threshold-qualified observation work from the current round's immutable
 * declaration and attack-result facts. No progress or dice are mutated here.
 */
export function getPendingCombatObservationAttempts(
  state: CombatRoundState,
): PendingCombatObservationAttempt[] {
  const normalized = combatRoundStateSchema.parse(state);
  const results = getCombatRoundAttackResults(normalized);

  return normalized.participants.flatMap((observer) => {
    const observation = getCombatRoundObservationDeclaration(observer.declaration);
    if (!observation) return [];
    const target = normalized.participants.find(
      (participant) => participant.participantId === observation.targetParticipantId,
    );
    if (!target || target.participantId === observer.participantId) return [];
    if (
      combatRoundObserverWasHitByTarget({
        observerParticipantId: observer.participantId,
        results,
        state: normalized,
        targetParticipantId: target.participantId,
      })
    ) {
      return [];
    }

    const relationshipId = buildCombatObservationRelationshipId({
      observerParticipantId: observer.participantId,
      targetParticipantId: target.participantId,
    });
    const relationship = normalized.observationRelationships.find(
      (entry) => entry.id === relationshipId,
    );
    const completedAttempts = relationship?.completedAttempts ?? 0;
    const requiredQualifyingRounds = getCombatObservationRequiredRounds(completedAttempts);
    const qualifyingRounds = (relationship?.roundsTowardNextAttempt ?? 0) + 1;
    const attemptId = `${relationshipId}:attempt:${completedAttempts + 1}`;
    const alreadyResolved = normalized.observationAttempts.some(
      (attempt) => attempt.id === attemptId && attempt.roundNumber === normalized.roundNumber,
    );
    return qualifyingRounds >= requiredQualifyingRounds && !alreadyResolved
      ? [
          {
            attemptId,
            observerParticipantId: observer.participantId,
            relationshipId,
            requiredQualifyingRounds,
            targetParticipantId: target.participantId,
          },
        ]
      : [];
  });
}

/**
 * Records the observer-owned SU command. The observer's open-ended roll and the
 * hidden target roll resolve together in this one canonical mutation.
 */
export function recordCombatObservationRoll(input: {
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  completedAtRevision: string;
  executionGroupId: string;
  observerBasis: CombatObservationRollBasis;
  observerParticipantId: string;
  observationAttemptId: string;
  relationshipId: string;
  rng?: () => number;
  state: CombatRoundState;
  targetBasis: CombatObservationRollBasis;
  targetParticipantId: string;
}): {
  attempt: CombatObservationAttempt;
  command: CombatRoundCommand;
  state: CombatRoundState;
} {
  const normalized = combatRoundStateSchema.parse(input.state);
  const pending = getPendingCombatObservationAttempts(normalized).find(
    (attempt) =>
      attempt.attemptId === input.observationAttemptId &&
      attempt.relationshipId === input.relationshipId &&
      attempt.observerParticipantId === input.observerParticipantId &&
      attempt.targetParticipantId === input.targetParticipantId,
  );
  if (!pending) {
    throw new RangeError("The Observe Opponent roll is no longer available.");
  }
  const previousRelationship = normalized.observationRelationships.find(
    (relationship) => relationship.id === pending.relationshipId,
  );
  const relationshipBeforeRoll = combatObservationRelationshipSchema.parse({
    ...(previousRelationship ?? {
      id: pending.relationshipId,
      observerParticipantId: pending.observerParticipantId,
      targetParticipantId: pending.targetParticipantId,
    }),
    roundsTowardNextAttempt: (previousRelationship?.roundsTowardNextAttempt ?? 0) + 1,
  });
  const nextRelationship = resolveCombatObservationAttempt({
    completedAt: input.command.createdAt,
    completedAtRevision: input.completedAtRevision,
    observerBasis: input.observerBasis,
    observerParticipantId: input.observerParticipantId,
    previousRelationship: relationshipBeforeRoll,
    rng: input.rng,
    roundNumber: normalized.roundNumber,
    targetBasis: input.targetBasis,
    targetParticipantId: input.targetParticipantId,
  });
  const attempt = nextRelationship.lastAttempt;
  if (!attempt || attempt.id !== pending.attemptId) {
    throw new RangeError("Observe Opponent produced an invalid attempt identity.");
  }
  const relationships = previousRelationship
    ? normalized.observationRelationships.map((relationship) =>
        relationship.id === nextRelationship.id ? nextRelationship : relationship,
      )
    : [...normalized.observationRelationships, nextRelationship];
  const orderedEventsBeforeRoll = [...normalized.events].sort(
    (left, right) => left.sequence - right.sequence || left.id.localeCompare(right.id),
  );
  const participantReviewEvent = orderedEventsBeforeRoll.find(
    (event) =>
      event.type === "participant_su_review" &&
      event.ownerParticipantId === input.observerParticipantId,
  );
  const participantReviewEventPreviousIndex = participantReviewEvent
    ? orderedEventsBeforeRoll.findIndex((event) => event.id === participantReviewEvent.id)
    : undefined;
  const participantReviewEventPreviousStatus = participantReviewEvent?.status;
  let nextState = combatRoundStateSchema.parse({
    ...normalized,
    observationAttempts: [...normalized.observationAttempts, attempt],
    observationRelationships: relationships,
  });
  const beforeCursor = getCombatRoundEndReviewCursor({
    participantId: input.observerParticipantId,
    state: normalized,
  });
  const nextTask = getNextCombatRoundEndTask({ state: nextState });
  const afterCursor = getCombatRoundEndTaskCursor({ state: nextState, task: nextTask });
  const command = combatRoundCommandSchema.parse({
    afterCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      executionGroupId: input.executionGroupId,
      observationAttemptId: attempt.id,
      participantReviewEventId: participantReviewEvent?.id,
      participantReviewEventPreviousIndex,
      participantReviewEventPreviousStatus,
      previousRelationship,
      relationshipId: pending.relationshipId,
      targetParticipantId: pending.targetParticipantId,
    },
    id:
      input.command.commandId ??
      buildCombatRoundCommandId({
        createdAt: input.command.createdAt,
        participantId: input.observerParticipantId,
        state: normalized,
        type: "roll_observation",
      }),
    participantId: input.observerParticipantId,
    roundNumber: normalized.roundNumber,
    step: "SU",
    type: "roll_observation",
  });
  nextState = combatRoundStateSchema.parse({
    ...nextState,
    commands: [...nextState.commands, command],
    currentCursor: afterCursor,
    currentStep: "round_summary",
    selectedParticipantId: afterCursor.participantId,
    selectedStep: "round_summary",
  });
  nextState = appendCombatRoundEventForCommand({
    command,
    draft: {
      actorParticipantId: input.observerParticipantId,
      facts: {
        gmReview: {
          observerTotal: attempt.observerRoll.finalTotal,
          targetCalculation: {
            appliedModifiers: attempt.targetRoll?.appliedModifiers,
            baseValue: attempt.targetRoll?.baseValue,
            effectiveSkillValue: attempt.targetRoll?.effectiveSkillValue,
            finalTotal: attempt.targetRoll?.finalTotal,
            intelligenceValue: attempt.targetRoll?.intelligenceValue,
            intelligenceXp: attempt.targetRoll?.intelligenceXp,
            openEndedD10s: attempt.targetRoll?.openEndedD10s,
            percentageAdjustment: attempt.targetRoll?.percentageAdjustment,
            percentageModifierTotal: attempt.targetRoll?.percentageModifierTotal,
            rollD20: attempt.targetRoll?.rollD20,
            rollTotal: attempt.targetRoll?.rollTotal,
            skillLabel: attempt.targetRoll?.skillLabel,
            skillXp: attempt.targetRoll?.skillXp,
          },
          targetTotal: attempt.targetRoll?.finalTotal,
        },
        involvedOutcome: {
          bestBonusAfter: attempt.bestBonusAfter,
          candidateBonus: attempt.candidateBonus,
          completedAttempts: nextRelationship.completedAttempts,
          difference: attempt.difference,
          observationAttemptId: attempt.id,
          relationshipId: nextRelationship.id,
          requiredQualifyingRounds: getCombatObservationRequiredRounds(
            nextRelationship.completedAttempts,
          ),
          roundsTowardNextAttempt: nextRelationship.roundsTowardNextAttempt,
          targetParticipantId: input.targetParticipantId,
        },
        publicOutcome: {},
        rollerPrivate: {
          appliedModifiers: attempt.observerRoll.appliedModifiers,
          baseValue: attempt.observerRoll.baseValue,
          effectiveSkillValue: attempt.observerRoll.effectiveSkillValue,
          finalTotal: attempt.observerRoll.finalTotal,
          intelligenceValue: attempt.observerRoll.intelligenceValue,
          intelligenceXp: attempt.observerRoll.intelligenceXp,
          openEndedD10s: attempt.observerRoll.openEndedD10s,
          percentageAdjustment: attempt.observerRoll.percentageAdjustment,
          percentageModifierTotal: attempt.observerRoll.percentageModifierTotal,
          rollD20: attempt.observerRoll.rollD20,
          rollTotal: attempt.observerRoll.rollTotal,
          skillLabel: attempt.observerRoll.skillLabel,
          skillXp: attempt.observerRoll.skillXp,
        },
      },
      involvedParticipantIds: [input.observerParticipantId],
      outcomeScope: "gm_only",
      ownerParticipantId: input.observerParticipantId,
      rollerParticipantId: input.observerParticipantId,
      sourceIds: [pending.relationshipId, attempt.id],
      sourceToken: attempt.id,
      status: "recorded",
      step: "round_summary",
      targetParticipantId: input.targetParticipantId,
      type: "observation",
    },
    state: nextState,
  });
  if (participantReviewEvent) {
    const orderedEvents = [...nextState.events].sort(
      (left, right) => left.sequence - right.sequence || left.id.localeCompare(right.id),
    );
    const deferredReview = orderedEvents.find((event) => event.id === participantReviewEvent.id);
    const withoutReview = orderedEvents.filter((event) => event.id !== participantReviewEvent.id);
    nextState = combatRoundStateSchema.parse({
      ...nextState,
      events: deferredReview
        ? [
            ...withoutReview,
            {
              ...deferredReview,
              status: "committed" as const,
            },
          ].map((event, sequence) => ({
            ...event,
            sequence,
          }))
        : orderedEvents,
    });
  }
  return { attempt, command, state: nextState };
}

function appendCombatObservationRoundStatusEvents(input: {
  command: CombatRoundCommand;
  observerParticipantId: string;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const attackResults = getCombatRoundAttackResults(normalized);
  const pendingAttempts = getPendingCombatObservationAttempts(normalized);
  let nextState = normalized;

  for (const observer of normalized.participants) {
    if (observer.participantId !== input.observerParticipantId) continue;
    const declaration = getCombatRoundObservationDeclaration(observer.declaration);
    if (!declaration) continue;
    const target = normalized.participants.find(
      (participant) => participant.participantId === declaration.targetParticipantId,
    );
    if (!target || target.participantId === observer.participantId) continue;

    const relationshipId = buildCombatObservationRelationshipId({
      observerParticipantId: observer.participantId,
      targetParticipantId: target.participantId,
    });
    const relationship = normalized.observationRelationships.find(
      (entry) => entry.id === relationshipId,
    );
    const requiredQualifyingRounds = getCombatObservationRequiredRounds(
      relationship?.completedAttempts ?? 0,
    );
    const wasHit = combatRoundObserverWasHitByTarget({
      observerParticipantId: observer.participantId,
      results: attackResults,
      state: normalized,
      targetParticipantId: target.participantId,
    });
    const pending = pendingAttempts.find((attempt) => attempt.relationshipId === relationshipId);
    const roundsTowardNextAttempt = wasHit
      ? (relationship?.roundsTowardNextAttempt ?? 0)
      : pending
        ? requiredQualifyingRounds
        : (relationship?.roundsTowardNextAttempt ?? 0) + 1;
    const observationStatus = wasHit ? "no_progress" : pending ? "period_complete" : "progress";

    nextState = appendCombatRoundEventForCommand({
      command: input.command,
      draft: {
        actorParticipantId: observer.participantId,
        facts: {
          involvedOutcome: {
            bestBonusAfter: relationship?.bestBonus ?? 0,
            completedAttempts: relationship?.completedAttempts ?? 0,
            observationAttemptId: pending?.attemptId,
            observationNoProgressReason: wasHit ? "observer_hit" : undefined,
            observationStatus,
            relationshipId,
            requiredQualifyingRounds,
            roundsTowardNextAttempt,
            targetParticipantId: target.participantId,
          },
          publicOutcome: {},
        },
        involvedParticipantIds: [observer.participantId],
        outcomeScope: "gm_only",
        ownerParticipantId: observer.participantId,
        sourceIds: [relationshipId, ...(pending ? [pending.attemptId] : [])],
        sourceToken: `${relationshipId}:round:${normalized.roundNumber}:status`,
        status: "recorded",
        step: "round_summary",
        targetParticipantId: target.participantId,
        type: "observation",
      },
      state: nextState,
    });
  }

  return nextState;
}

/** Applies non-threshold observation progress at the immutable round boundary. */
export function resolveCombatObservationRoundBoundary(input: { state: CombatRoundState }): {
  state: CombatRoundState;
  undoFacts: CombatObservationRoundUndoFact[];
} {
  const normalized = combatRoundStateSchema.parse(input.state);
  const results = getCombatRoundAttackResults(normalized);
  const relationships = [...normalized.observationRelationships];
  const undoFacts: CombatObservationRoundUndoFact[] = [];

  for (const observer of normalized.participants) {
    const observation = getCombatRoundObservationDeclaration(observer.declaration);
    if (!observation) continue;
    const target = normalized.participants.find(
      (participant) => participant.participantId === observation.targetParticipantId,
    );
    if (!target || target.participantId === observer.participantId) continue;

    const relationshipId = buildCombatObservationRelationshipId({
      observerParticipantId: observer.participantId,
      targetParticipantId: target.participantId,
    });
    const relationshipIndex = relationships.findIndex((entry) => entry.id === relationshipId);
    const previousRelationship =
      relationshipIndex >= 0 ? relationships[relationshipIndex] : undefined;
    undoFacts.push(
      combatObservationRoundUndoFactSchema.parse({
        previousRelationship,
        relationshipId,
      }),
    );

    const observerWasHitByTarget = combatRoundObserverWasHitByTarget({
      observerParticipantId: observer.participantId,
      results,
      state: normalized,
      targetParticipantId: target.participantId,
    });
    const current =
      previousRelationship ??
      combatObservationRelationshipSchema.parse({
        id: relationshipId,
        observerParticipantId: observer.participantId,
        targetParticipantId: target.participantId,
      });
    let next = current;

    if (!observerWasHitByTarget) {
      const completedThisRound = normalized.observationAttempts.some(
        (attempt) =>
          attempt.roundNumber === normalized.roundNumber &&
          attempt.id.startsWith(`${relationshipId}:attempt:`),
      );
      if (!completedThisRound) {
        const prospectiveProgress = current.roundsTowardNextAttempt + 1;
        if (prospectiveProgress < getCombatObservationRequiredRounds(current.completedAttempts)) {
          next = combatObservationRelationshipSchema.parse({
            ...current,
            roundsTowardNextAttempt: prospectiveProgress,
          });
        }
      }
    }

    if (relationshipIndex >= 0) relationships[relationshipIndex] = next;
    else relationships.push(next);
  }

  return {
    state: combatRoundStateSchema.parse({
      ...normalized,
      observationRelationships: relationships,
    }),
    undoFacts,
  };
}

export function restoreCombatObservationRelationships(input: {
  relationships: readonly CombatObservationRelationship[];
  undoFacts: readonly CombatObservationRoundUndoFact[];
}): CombatObservationRelationship[] {
  const restored = new Map(
    input.relationships.map((relationship) => [relationship.id, relationship]),
  );
  for (const fact of input.undoFacts) {
    const parsed = combatObservationRoundUndoFactSchema.parse(fact);
    if (parsed.previousRelationship) {
      restored.set(parsed.relationshipId, parsed.previousRelationship);
    } else {
      restored.delete(parsed.relationshipId);
    }
  }
  return [...restored.values()];
}

function appendCombatRoundEventForCommand(input: {
  command: CombatRoundCommand;
  draft: CanonicalCombatStepEventDraft;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);

  if (!normalized.encounterId) {
    return normalized;
  }

  return {
    ...normalized,
    events: appendCanonicalCombatStepEventForCommand({
      command: input.command,
      draft: input.draft,
      encounterId: normalized.encounterId,
      events: normalized.events,
    }),
  };
}

export function getCombatRoundNextEventSequence(state: CombatRoundState): number {
  return state.events.reduce((highest, event) => Math.max(highest, event.sequence), -1) + 1;
}

function removeCombatRoundEventsForCommand(input: {
  commandId: string;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);

  return {
    ...normalized,
    events: removeCanonicalCombatStepEventsForCommand({
      commandId: input.commandId,
      events: normalized.events,
    }),
  };
}

export interface CombatRoundInitiativeRank {
  rank: number;
  rankTotal: number;
  tiedCount: number;
}

function getCombatExperienceEffectiveTableTotal(input: {
  difficulty?: number;
  finalTotal: number;
}): {
  difficultyShift: number;
  effectiveTableTotal: number;
} {
  const finalTotal = Math.trunc(input.finalTotal);
  const difficulty = Math.trunc(input.difficulty ?? COMBAT_EXPERIENCE_TABLE_DIFFICULTY);
  const difficultyShift = difficulty - COMBAT_EXPERIENCE_TABLE_DIFFICULTY;

  return {
    difficultyShift,
    effectiveTableTotal: finalTotal - difficultyShift,
  };
}

export function evaluateCombatExperienceResult(
  finalTotal: number,
  input: { difficulty?: number; panicDurationRounds?: number } = {},
): CombatExperienceEvaluation {
  const { difficultyShift, effectiveTableTotal } = getCombatExperienceEffectiveTableTotal({
    difficulty: input.difficulty,
    finalTotal,
  });
  const baseEvaluation = {
    difficultyShift,
    effectiveTableTotal,
  };

  if (effectiveTableTotal <= 5) {
    return combatExperienceEvaluationSchema.parse({
      ...baseEvaluation,
      durationRounds: input.panicDurationRounds ?? 5,
      label: "Panic",
      modifierValue: -4,
      needsEffectRow: true,
      note: "combat exp panic",
      resultBand: "panic",
    });
  }

  if (effectiveTableTotal <= 10) {
    return combatExperienceEvaluationSchema.parse({
      ...baseEvaluation,
      durationRounds: 4,
      label: "Passive",
      modifierValue: -2,
      needsEffectRow: true,
      note: "combat exp passive",
      resultBand: "passive",
    });
  }

  if (effectiveTableTotal <= 15) {
    return combatExperienceEvaluationSchema.parse({
      ...baseEvaluation,
      durationRounds: 2,
      label: "Active",
      modifierValue: -2,
      needsEffectRow: true,
      note: "combat exp active -2",
      resultBand: "active_penalty",
    });
  }

  if (effectiveTableTotal <= 20) {
    return combatExperienceEvaluationSchema.parse({
      ...baseEvaluation,
      durationRounds: 1,
      label: "Active",
      modifierValue: -1,
      needsEffectRow: true,
      note: "combat exp active -1",
      resultBand: "active_penalty",
    });
  }

  return combatExperienceEvaluationSchema.parse({
    ...baseEvaluation,
    durationRounds: 0,
    label: "Active",
    modifierValue: 0,
    needsEffectRow: false,
    note: "combat exp active",
    resultBand: "active",
  });
}

export function evaluatePhaseCombatExperienceResult(
  finalTotal: number,
  input: { difficulty?: number } = {},
): CombatExperienceEvaluation {
  const { difficultyShift, effectiveTableTotal } = getCombatExperienceEffectiveTableTotal({
    difficulty: input.difficulty,
    finalTotal,
  });
  const baseEvaluation = {
    difficultyShift,
    effectiveTableTotal,
  };

  if (effectiveTableTotal <= 5) {
    return combatExperienceEvaluationSchema.parse({
      ...baseEvaluation,
      durationRounds: 0,
      label: "No attack",
      modifierValue: 0,
      needsEffectRow: false,
      note: "combat exp attack cancelled",
      resultBand: "panic",
    });
  }

  if (effectiveTableTotal <= 10) {
    return combatExperienceEvaluationSchema.parse({
      ...baseEvaluation,
      durationRounds: 0,
      label: "Attack continues",
      modifierValue: -4,
      needsEffectRow: false,
      note: "combat exp phase attack OB -4",
      resultBand: "passive",
    });
  }

  if (effectiveTableTotal <= 15) {
    return combatExperienceEvaluationSchema.parse({
      ...baseEvaluation,
      durationRounds: 0,
      label: "Attack continues",
      modifierValue: -3,
      needsEffectRow: false,
      note: "combat exp phase attack OB -3",
      resultBand: "active_penalty",
    });
  }

  if (effectiveTableTotal <= 20) {
    return combatExperienceEvaluationSchema.parse({
      ...baseEvaluation,
      durationRounds: 0,
      label: "Attack continues",
      modifierValue: -2,
      needsEffectRow: false,
      note: "combat exp phase attack OB -2",
      resultBand: "active_penalty",
    });
  }

  return combatExperienceEvaluationSchema.parse({
    ...baseEvaluation,
    durationRounds: 0,
    label: "Attack continues",
    modifierValue: 0,
    needsEffectRow: false,
    note: "combat exp phase attack continues",
    resultBand: "active",
  });
}

function isCombatRoundRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function readCombatRoundNumber(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? Math.trunc(value) : undefined;
}

function normalizeCombatExperienceSkillKey(value: string): string {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function compactCombatExperienceSkillKey(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "");
}

function isCombatExperienceSkillIdentifier(identifier: string): boolean {
  const normalized = normalizeCombatExperienceSkillKey(identifier);
  const compact = compactCombatExperienceSkillKey(identifier);

  return (
    normalized === "combat_experience" ||
    normalized === "combat_experience_skill" ||
    compact === "combatexperience" ||
    compact === "combatexperienceskill"
  );
}

function getCombatExperienceSkillTotalSkillLists(participant: unknown): Array<{
  label: string;
  skills: unknown[];
}> {
  const lists: Array<{ label: string; skills: unknown[] }> = [];
  const addSkills = (label: string, owner: unknown) => {
    if (!isCombatRoundRecord(owner)) {
      return;
    }

    const draftView = isCombatRoundRecord(owner.draftView) ? owner.draftView : undefined;
    const skills = Array.isArray(draftView?.skills)
      ? draftView.skills
      : Array.isArray(owner.skills)
        ? owner.skills
        : [];

    if (skills.length > 0) {
      lists.push({ label, skills });
    }
  };

  if (isCombatRoundRecord(participant)) {
    addSkills("participant.sheetSummary.draftView.skills", participant.sheetSummary);
    addSkills("participant.draftView.skills", participant.draftView);

    if (isCombatRoundRecord(participant.snapshot)) {
      addSkills(
        "participant.snapshot.sheetSummary.draftView.skills",
        participant.snapshot.sheetSummary,
      );
      addSkills("participant.snapshot.draftView.skills", participant.snapshot.draftView);
    }
  }

  addSkills("snapshot.sheetSummary.draftView.skills", participant);

  return lists;
}

export interface ParticipantCombatExperienceSkillTotalLookup {
  matchedIdentifier?: string;
  skillTotal: number;
  source?: string;
  warning?: string;
}

function getCombatExperienceDisplayedSkillTotal(input: {
  label: string;
  skill: Record<string, unknown>;
}): ParticipantCombatExperienceSkillTotalLookup | undefined {
  const displayedTotalFields = [
    "totalSkill",
    "totalSkillLevel",
    "skillLevel",
    "total",
    "displayedTotal",
    "effectiveTotal",
    "effectiveSkillTotal",
  ] as const;
  const statAverageFields = [
    "linkedStatAverage",
    "linkedStatsAverage",
    "statAverage",
    "statsContribution",
    "stats",
    "avgStats",
  ] as const;
  const skillXpFields = ["effectiveSkillNumber", "totalXp", "skillXp", "xp"] as const;

  for (const field of displayedTotalFields) {
    const displayedTotal = readCombatRoundNumber(input.skill[field]);

    if (displayedTotal !== undefined) {
      return {
        skillTotal: displayedTotal,
        source: `${input.label}.${field}`,
      };
    }
  }

  const statAverageEntry = statAverageFields
    .map((field) => ({
      field,
      value: readCombatRoundNumber(input.skill[field]),
    }))
    .find(
      (entry): entry is { field: (typeof statAverageFields)[number]; value: number } =>
        entry.value !== undefined,
    );
  const skillXpEntry = skillXpFields
    .map((field) => ({
      field,
      value: readCombatRoundNumber(input.skill[field]),
    }))
    .find(
      (entry): entry is { field: (typeof skillXpFields)[number]; value: number } =>
        entry.value !== undefined,
    );

  if (statAverageEntry && skillXpEntry) {
    return {
      skillTotal: statAverageEntry.value + skillXpEntry.value,
      source: `${input.label}.${statAverageEntry.field}+${skillXpEntry.field}`,
    };
  }

  if (skillXpEntry) {
    return {
      skillTotal: skillXpEntry.value,
      source: `${input.label}.${skillXpEntry.field}`,
      warning: "Combat Experience displayed total was unavailable; using XP-only fallback.",
    };
  }

  return undefined;
}

export function getParticipantCombatExperienceSkillTotalLookup(
  participant: unknown,
): ParticipantCombatExperienceSkillTotalLookup {
  const skillLists = getCombatExperienceSkillTotalSkillLists(participant);

  if (skillLists.length === 0) {
    return {
      skillTotal: 0,
      warning: "Combat Experience skill data is missing from participant sheet summary.",
    };
  }

  for (const skillList of skillLists) {
    for (const skill of skillList.skills) {
      if (!isCombatRoundRecord(skill)) {
        continue;
      }

      const identifiers = [
        skill.skillId,
        skill.skillKey,
        skill.id,
        skill.name,
        skill.skillName,
      ].filter((entry): entry is string => typeof entry === "string");
      const matchedIdentifier = identifiers.find(isCombatExperienceSkillIdentifier);

      if (!matchedIdentifier) {
        continue;
      }

      const displayedTotal = getCombatExperienceDisplayedSkillTotal({
        label: skillList.label,
        skill,
      });

      if (displayedTotal) {
        return {
          ...displayedTotal,
          matchedIdentifier,
        };
      }

      return {
        matchedIdentifier,
        skillTotal: 0,
        source: skillList.label,
        warning: "Combat Experience skill exists, but no numeric total was available.",
      };
    }
  }

  return {
    skillTotal: 0,
    warning: "Combat Experience skill was not found in participant sheet summary skills.",
  };
}

export function getParticipantCombatExperienceSkillTotal(participant: unknown): number {
  return getParticipantCombatExperienceSkillTotalLookup(participant).skillTotal;
}

export function getCombatExperienceSkillTotalFromSnapshot(snapshot: unknown): number {
  return getParticipantCombatExperienceSkillTotalLookup({ snapshot }).skillTotal;
}

function rollCombatExperiencePanicDuration(randomFn: () => number): number {
  return Math.floor(randomFn() * 6) + 5;
}

export function rollOpenEndedD6(
  input: {
    maxRolls?: number;
    randomFn?: () => number;
  } = {},
): CombatRoundInitiativeResult & { isOpenEnded: boolean } {
  const randomFn = input.randomFn ?? Math.random;
  const maxRolls = input.maxRolls ?? 100;
  const rolls: number[] = [];

  for (let index = 0; index < maxRolls; index += 1) {
    const roll = Math.min(6, Math.max(1, Math.floor(randomFn() * 6) + 1));
    rolls.push(roll);

    if (roll !== 6) {
      break;
    }
  }

  return {
    baseInitiative: 0,
    isOpenEnded: rolls.length > 1,
    modifierAdjustment: 0,
    rolls,
    rollTotal: rolls.reduce((sum, roll) => sum + roll, 0),
    total: rolls.reduce((sum, roll) => sum + roll, 0),
  };
}

export function buildCombatRoundInitiativeResult(input: {
  baseInitiative?: number;
  modifierAdjustment?: number;
  roll: CombatRoundInitiativeResult;
}): CombatRoundInitiativeResult {
  const rollTotal = input.roll.rollTotal ?? input.roll.total;
  const baseInitiative = input.baseInitiative ?? 0;
  const modifierAdjustment = input.modifierAdjustment ?? 0;

  return combatRoundInitiativeResultSchema.parse({
    baseInitiative,
    modifierAdjustment,
    rolls: input.roll.rolls,
    rollTotal,
    total: baseInitiative + modifierAdjustment + rollTotal,
  });
}

function normalizeCombatRoundInitiativeResult(
  initiative: CombatRoundInitiativeResult | number | undefined,
): CombatRoundInitiativeResult | undefined {
  if (initiative === undefined) {
    return undefined;
  }

  return combatRoundInitiativeResultSchema.parse(
    typeof initiative === "number"
      ? { baseInitiative: 0, rolls: [], rollTotal: initiative, total: initiative }
      : {
          ...initiative,
          modifierAdjustment:
            initiative.modifierAdjustment ??
            initiative.total -
              (initiative.baseInitiative ?? 0) -
              (initiative.rollTotal ?? initiative.total - (initiative.baseInitiative ?? 0)),
          rollTotal: initiative.rollTotal ?? initiative.total - (initiative.baseInitiative ?? 0),
        },
  );
}

export function getCombatRoundInitiativeTotal(
  initiative?: CombatRoundInitiativeResult,
): number | undefined {
  return initiative?.total;
}

function buildDefaultStepStatuses(): Record<CombatRoundStep, CombatRoundStepStatus> {
  return Object.fromEntries(COMBAT_ROUND_STEPS.map((step) => [step, "pending"])) as Record<
    CombatRoundStep,
    CombatRoundStepStatus
  >;
}

function mergeStepStatuses(
  existing?: Partial<Record<CombatRoundStep, CombatRoundStepStatus>>,
): Record<CombatRoundStep, CombatRoundStepStatus> {
  return {
    ...buildDefaultStepStatuses(),
    ...existing,
  };
}

export function getCombatRoundCursorStepForStep(step: CombatRoundStep): CombatRoundCursorStep {
  return combatRoundCursorStepSchema.parse(COMBAT_ROUND_STEP_ABBREVIATIONS[step]);
}

export function getCombatRoundStepForCursorStep(step: CombatRoundCursorStep): CombatRoundStep {
  const entry = COMBAT_ROUND_STEPS.find(
    (candidate) => COMBAT_ROUND_STEP_ABBREVIATIONS[candidate] === step,
  );

  if (!entry) {
    throw new RangeError(`Unsupported combat round cursor step: ${step}`);
  }

  return entry;
}

export function isGlobalCombatRoundCursorStep(step: CombatRoundCursorStep): boolean {
  return (
    step === "DE" ||
    step === "M1" ||
    step === "i1" ||
    step === "M2" ||
    step === "i2" ||
    step === "SU"
  );
}

function isGlobalCombatRoundStep(step: CombatRoundStep): boolean {
  return (
    step === "select_actions" ||
    step === "review_action_modifiers" ||
    step === "initiative_phase_1" ||
    step === "review_phase_2_modifiers" ||
    step === "initiative_phase_2" ||
    step === "round_summary"
  );
}

function getCombatRoundGlobalCommandTypeForStep(
  step: CombatRoundStep,
): CombatRoundCommandType | undefined {
  switch (step) {
    case "select_actions":
      return "declare_action";
    case "review_action_modifiers":
      return "review_modifiers_phase1";
    case "initiative_phase_1":
      return "roll_initiative_phase1";
    case "review_phase_2_modifiers":
      return "review_modifiers_phase2";
    case "initiative_phase_2":
      return "roll_initiative_phase2";
    case "round_summary":
      return "complete_round";
    default:
      return undefined;
  }
}

function getNextCombatRoundGlobalParticipantId(input: {
  participantId: string;
  state: CombatRoundState;
}): string {
  const participantIds = input.state.participants.map((participant) => participant.participantId);
  const participantIndex = participantIds.indexOf(input.participantId);

  if (participantIndex < 0 || participantIndex >= participantIds.length - 1) {
    return input.participantId;
  }

  return participantIds[participantIndex + 1] ?? input.participantId;
}

function getDefaultCombatRoundCursor(input: {
  participantId?: string;
  roundNumber: number;
  step: CombatRoundStep;
}): CombatRoundCursor {
  return combatRoundCursorSchema.parse({
    participantId: input.participantId,
    roundNumber: input.roundNumber,
    step: getCombatRoundCursorStepForStep(input.step),
  });
}

function getCombatRoundAttackCursorStepForPhase(phase: CombatRoundPhase): CombatRoundCursorStep {
  return phase === "phase1" ? "A1" : "A2";
}

function getCombatRoundParryCursorStepForPhase(phase: CombatRoundPhase): CombatRoundCursorStep {
  return phase === "phase1" ? "P1" : "P2";
}

function getCombatRoundDamageCursorStepForPhase(phase: CombatRoundPhase): CombatRoundCursorStep {
  return phase === "phase1" ? "D1" : "D2";
}

function getCombatRoundCursorStepForPhaseResolutionSubstep(input: {
  phase: CombatRoundPhase;
  substep: CombatRoundPhaseResolutionSubstep;
}): CombatRoundCursorStep {
  switch (input.substep) {
    case "break_off":
    case "feint":
    case "adjust_distance":
    case "perform_task":
    case "attack":
    case "done":
    case "effects":
      return getCombatRoundAttackCursorStepForPhase(input.phase);
    case "parry":
    case "defense":
      return getCombatRoundParryCursorStepForPhase(input.phase);
    case "damage":
      return getCombatRoundDamageCursorStepForPhase(input.phase);
  }
}

function getCombatRoundPhaseCompletionCursor(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundCursor {
  const participantId =
    input.state.phaseResolutionCursor?.participantId ??
    input.state.currentCursor?.participantId ??
    getCombatRoundPhaseResolutionOrder({ phase: input.phase, state: input.state }).at(-1) ??
    input.state.participants[0]?.participantId;

  return combatRoundCursorSchema.parse({
    participantId,
    roundNumber: input.state.roundNumber,
    step: input.phase === "phase1" ? "A1" : "A2",
  });
}

function moveCombatRoundToPhaseCompletion(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const currentCursor = getCombatRoundPhaseCompletionCursor({
    phase: input.phase,
    state: normalized,
  });
  const selectedStep = getCombatRoundStepForCursorStep(currentCursor.step);

  return {
    ...normalized,
    currentCursor,
    currentStep: selectedStep,
    phaseResolutionCursor: undefined,
    selectedParticipantId: currentCursor.participantId ?? normalized.selectedParticipantId,
    selectedStep,
  };
}

function getCombatRoundPhaseActionOrCompletionCursor(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundCursor {
  const normalized = clearUnsupportedCombatRoundPhaseActionProgress({
    phase: input.phase,
    state: input.state,
  });
  if (!isCombatPhaseActionOpen({ phase: input.phase, state: normalized })) {
    return combatRoundCursorSchema.parse({
      ...(normalized.currentCursor ?? {
        participantId: normalized.participants[0]?.participantId,
        roundNumber: normalized.roundNumber,
      }),
      roundNumber: normalized.roundNumber,
      step: input.phase === "phase1" ? "i1" : "i2",
    });
  }
  const participantId = getNextCombatRoundPhaseActionParticipantId({
    phase: input.phase,
    state: normalized,
  });

  if (!participantId) {
    return getCombatRoundPhaseCompletionCursor(input);
  }

  return combatRoundCursorSchema.parse({
    participantId,
    roundNumber: normalized.roundNumber,
    step: getCombatRoundAttackCursorStepForPhase(input.phase),
  });
}

function getCombatRoundCursorForPhaseResolutionCursor(input: {
  cursor: CombatRoundPhaseResolutionCursor;
  roundNumber?: number;
  state: CombatRoundState;
}): CombatRoundCursor {
  const incomingAttackResult = getCombatRoundDisplayIncomingAttackResultForParticipantPhase({
    participantId: input.cursor.participantId,
    phase: input.cursor.phase,
    state: input.state,
  });
  const step =
    input.cursor.substep === "parry" && !incomingAttackResult
      ? getCombatRoundAttackCursorStepForPhase(input.cursor.phase)
      : getCombatRoundCursorStepForPhaseResolutionSubstep({
          phase: input.cursor.phase,
          substep: input.cursor.substep,
        });

  return combatRoundCursorSchema.parse({
    participantId: input.cursor.participantId,
    roundNumber: input.roundNumber ?? input.state.roundNumber,
    step,
  });
}

export function buildCombatRoundCommandId(input: {
  createdAt: string;
  participantId: string;
  state: CombatRoundState;
  type: CombatRoundCommandType;
}): string {
  return [
    "combat-command",
    input.state.roundNumber,
    input.state.commands.length + 1,
    input.type,
    input.participantId,
    input.createdAt,
  ].join(":");
}

export function recordCombatCriticalBleedTreatmentCommand(input: {
  combatEffectEventId: string;
  createdAt: string;
  createdByUserId: string;
  encounterParticipantId: string;
  nextEffect: CombatEffect;
  partialRate?: { denominator: number; numerator: number };
  previousEffect: CombatEffect;
  scenarioParticipantId: string;
  state: CombatRoundState;
}): { command: CombatRoundCommand; state: CombatRoundState } {
  const normalized = combatRoundStateSchema.parse(input.state);
  const previousEffect = combatEffectSchema.parse(input.previousEffect);
  const nextEffect = combatEffectSchema.parse(input.nextEffect);
  const previousBleed = previousEffect.criticalRuntime;
  const nextBleed = nextEffect.criticalRuntime;

  if (
    previousEffect.id !== nextEffect.id ||
    previousBleed?.kind !== "bleed" ||
    nextBleed?.kind !== "bleed" ||
    previousBleed.criticalKey !== nextBleed.criticalKey ||
    previousBleed.fixtureVersion !== nextBleed.fixtureVersion
  ) {
    throw new RangeError("Critical Bleed treatment must preserve the canonical source identity.");
  }
  if (
    !normalized.participants.some(
      (participant) => participant.participantId === input.encounterParticipantId,
    )
  ) {
    throw new RangeError("The treated participant is not in the active combat round.");
  }

  const beforeCursor =
    normalized.currentCursor ??
    getDefaultCombatRoundCursor({
      participantId: input.encounterParticipantId,
      roundNumber: normalized.roundNumber,
      step: normalized.currentStep,
    });
  const commandId = buildCombatRoundCommandId({
    createdAt: input.createdAt,
    participantId: input.encounterParticipantId,
    state: normalized,
    type: "transition_critical_bleed",
  });
  const command = combatRoundCommandSchema.parse({
    afterCursor: beforeCursor,
    beforeCursor,
    createdAt: input.createdAt,
    createdByUserId: input.createdByUserId,
    facts: {
      actorUserId: input.createdByUserId,
      combatEffectEventId: input.combatEffectEventId,
      effectId: previousEffect.id,
      nextEffect,
      nextState: nextBleed.bleed.controlState,
      partialRate: input.partialRate,
      previousEffect,
      previousState: previousBleed.bleed.controlState,
      scenarioParticipantId: input.scenarioParticipantId,
      targetParticipantId: input.encounterParticipantId,
    },
    id: commandId,
    participantId: input.encounterParticipantId,
    roundNumber: normalized.roundNumber,
    step: beforeCursor.step,
    type: "transition_critical_bleed",
  });
  const rate = getCombatCriticalBleedEffectiveRate(nextBleed.bleed);
  const event = combatStepEventSchema.parse({
    combatEffectEventId: input.combatEffectEventId,
    combatEffectIds: [previousEffect.id],
    commandId,
    completeness: "complete",
    encounterId: normalized.encounterId,
    facts: {
      gmReview: {
        actorUserId: input.createdByUserId,
        effectId: previousEffect.id,
        partialRate: input.partialRate,
        previousState: previousBleed.bleed.controlState,
      },
      involvedOutcome: {
        bleedKind: nextBleed.bleed.kind,
        currentRate: rate,
        nextState: nextBleed.bleed.controlState,
        previousState: previousBleed.bleed.controlState,
      },
      publicOutcome: { status: "committed" },
    },
    id: `${commandId}:event`,
    missingFacts: [],
    occurredAt: input.createdAt,
    ownerParticipantId: input.encounterParticipantId,
    roundNumber: normalized.roundNumber,
    schemaVersion: 1,
    sequence: getCombatRoundNextEventSequence(normalized),
    source: {
      commandType: "transition_critical_bleed",
      kind: "canonical",
      sourceIds: [commandId, previousEffect.id, input.combatEffectEventId],
    },
    status: "committed",
    step: normalized.currentStep,
    targetParticipantId: input.encounterParticipantId,
    type: "effect_review",
    visibility: {
      identityRefs: [{ participantId: input.encounterParticipantId, role: "target" }],
      involvedParticipantIds: [input.encounterParticipantId],
      outcomeScope: "involved",
    },
  });

  return {
    command,
    state: combatRoundStateSchema.parse({
      ...normalized,
      commands: [...normalized.commands, command],
      events: [...normalized.events, event],
    }),
  };
}

export function recordCombatRoundGlobalParticipantCommand(input: {
  commandId?: string;
  createdAt: string;
  createdByUserId?: string;
  facts?: Record<string, unknown>;
  participantId: string;
  state: CombatRoundState;
  step: CombatRoundStep;
  type?: CombatRoundCommandType;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const commandType = input.type ?? getCombatRoundGlobalCommandTypeForStep(input.step);

  if (!commandType || !isGlobalCombatRoundStep(input.step)) {
    return normalized;
  }

  const actorExists = normalized.participants.some(
    (participant) => participant.participantId === input.participantId,
  );

  if (!actorExists) {
    return normalized;
  }

  const beforeCursor = getDefaultCombatRoundCursor({
    participantId: input.participantId,
    roundNumber: normalized.roundNumber,
    step: input.step,
  });
  const afterParticipantId = getNextCombatRoundGlobalParticipantId({
    participantId: input.participantId,
    state: normalized,
  });
  const afterCursor = getDefaultCombatRoundCursor({
    participantId: afterParticipantId,
    roundNumber: normalized.roundNumber,
    step: input.step,
  });
  const command = combatRoundCommandSchema.parse({
    afterCursor,
    beforeCursor,
    createdAt: input.createdAt,
    createdByUserId: input.createdByUserId,
    facts: {
      step: beforeCursor.step,
      ...input.facts,
    },
    id:
      input.commandId ??
      buildCombatRoundCommandId({
        createdAt: input.createdAt,
        participantId: input.participantId,
        state: normalized,
        type: commandType,
      }),
    participantId: input.participantId,
    roundNumber: normalized.roundNumber,
    type: commandType,
  });
  const selectedStep = getCombatRoundStepForCursorStep(command.afterCursor.step);
  const consumesGmBacktrackHold =
    normalized.gmBacktrackHold?.roundNumber === normalized.roundNumber &&
    normalized.gmBacktrackHold.step === input.step &&
    (normalized.gmBacktrackHold.participantId === undefined ||
      normalized.gmBacktrackHold.participantId === input.participantId);

  return {
    ...normalized,
    commands: [...normalized.commands, command],
    currentCursor: command.afterCursor,
    gmBacktrackHold: consumesGmBacktrackHold ? undefined : normalized.gmBacktrackHold,
    selectedParticipantId: command.afterCursor.participantId ?? normalized.selectedParticipantId,
    selectedStep,
  };
}

export function isCombatStartExperienceRollRequired(input: {
  participantId: string;
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);

  if (normalized.roundNumber !== 1) {
    return false;
  }

  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );

  if (!participant) {
    return false;
  }

  return !(
    participant.combatExperience?.trigger === "combat_start" &&
    participant.combatExperience.roundNumber === normalized.roundNumber
  );
}

export function getCombatRoundCombatExperienceDifficulty(state: CombatRoundState): number {
  const normalized = combatRoundStateSchema.parse(state);

  return normalized.combatExperienceDifficulty ?? COMBAT_EXPERIENCE_DEFAULT_DIFFICULTY;
}

export function isCombatRoundCombatExperienceWindowOpen(state: CombatRoundState): boolean {
  const normalized = combatRoundStateSchema.parse(state);

  return normalized.combatExperienceDifficulty !== undefined;
}

export function hasCombatRoundCombatExperienceRoll(state: CombatRoundState): boolean {
  const normalized = combatRoundStateSchema.parse(state);

  return normalized.participants.some(
    (participant) =>
      participant.combatExperience?.trigger === "combat_start" &&
      participant.combatExperience.roundNumber === normalized.roundNumber,
  );
}

export function setCombatRoundCombatExperienceDifficulty(input: {
  difficulty: number;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const difficulty = Math.trunc(input.difficulty);

  if (!Number.isInteger(difficulty) || difficulty <= 0) {
    throw new RangeError("Combat Experience difficulty must be a positive integer.");
  }

  if (normalized.currentStep !== "select_actions") {
    throw new RangeError("Combat Experience difficulty can only be changed during declaration.");
  }

  if (hasCombatRoundCombatExperienceRoll(normalized)) {
    throw new RangeError(
      "Combat Experience difficulty cannot be changed after rolls have been recorded. Clear Combat Experience results first.",
    );
  }

  return combatRoundStateSchema.parse({
    ...normalized,
    combatExperienceDifficulty: difficulty,
  });
}

export function getCombatRoundDistanceEdge(input: {
  participantAId: string;
  participantBId: string;
  state: CombatRoundState;
}): CombatDistanceEdge | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);

  return getDistanceEdgeBetween(
    normalized.distanceState,
    input.participantAId,
    input.participantBId,
  );
}

export function setCombatRoundPairDistance(input: {
  command?: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  distance: CombatDistance | number | string;
  participantAId: string;
  participantBId: string;
  source?: CombatDistanceSource;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participantIds = new Set(
    normalized.participants.map((participant) => participant.participantId),
  );

  if (!participantIds.has(input.participantAId) || !participantIds.has(input.participantBId)) {
    throw new RangeError("Pair distance can only be set for active combat participants.");
  }

  const previousEdge = getDistanceEdgeBetween(
    normalized.distanceState,
    input.participantAId,
    input.participantBId,
  );
  const distance = combatDistanceSchema.parse(
    typeof input.distance === "string" ? Number(input.distance) : input.distance,
  );
  const nextDistanceState = setDistanceBetween({
    distance,
    lastChangedRound: normalized.roundNumber,
    participantAId: input.participantAId,
    participantBId: input.participantBId,
    source: input.source ?? "gm_set",
    state: normalized.distanceState,
  });
  const nextEdge = getDistanceEdgeBetween(
    nextDistanceState,
    input.participantAId,
    input.participantBId,
  );
  const stateWithDistance = combatRoundStateSchema.parse({
    ...normalized,
    distanceState: nextDistanceState,
  });

  if (!input.command) {
    return stateWithDistance;
  }

  const beforeCursor =
    normalized.currentCursor ??
    getDefaultCombatRoundCursor({
      participantId: normalized.selectedParticipantId ?? input.participantAId,
      roundNumber: normalized.roundNumber,
      step: normalized.currentStep,
    });
  const commandType = "set_pair_distance" satisfies CombatRoundCommandType;
  const commandId =
    input.command.commandId ??
    buildCombatRoundCommandId({
      createdAt: input.command.createdAt,
      participantId: input.participantAId,
      state: normalized,
      type: commandType,
    });
  const command = combatRoundCommandSchema.parse({
    afterCursor: beforeCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      newDistance: distance,
      nextEdge,
      pairKey: makeDistancePairKey(input.participantAId, input.participantBId),
      participantAId: input.participantAId,
      participantBId: input.participantBId,
      previousEdge,
      source: input.source ?? "gm_set",
    },
    id: commandId,
    participantId: input.participantAId,
    roundNumber: normalized.roundNumber,
    type: commandType,
  });

  return combatRoundStateSchema.parse({
    ...stateWithDistance,
    commands: [...stateWithDistance.commands, command],
    currentCursor: command.afterCursor,
    currentStep: getCombatRoundStepForCursorStep(command.afterCursor.step),
    selectedParticipantId: command.afterCursor.participantId ?? input.participantAId,
    selectedStep: getCombatRoundStepForCursorStep(command.afterCursor.step),
  });
}

export function getCombatExperienceTriggerForPhase(
  phase: CombatRoundPhase,
): CombatExperienceTrigger {
  return phase === "phase1" ? "phase1_attack" : "phase2_attack";
}

export function getFirstCombatRoundPendingModifierReviewParticipantId(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): string | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const step = input.phase === "phase1" ? "review_action_modifiers" : "review_phase_2_modifiers";
  const completedStatuses = new Set<CombatRoundStepStatus>([
    "complete",
    "gmEdited",
    "locked",
    "skipped",
    "submitted",
  ]);

  return normalized.participants.find(
    (participant) => !completedStatuses.has(participant.stepStatuses[step] ?? "pending"),
  )?.participantId;
}

export function getCombatExperiencePhaseForTrigger(
  trigger: CombatExperienceTrigger,
): CombatRoundPhase | undefined {
  if (trigger === "phase1_attack") {
    return "phase1";
  }

  if (trigger === "phase2_attack") {
    return "phase2";
  }

  return undefined;
}

function getCombatRoundPhaseInitiativeStepForPhase(phase: CombatRoundPhase): CombatRoundStep {
  return phase === "phase1" ? "initiative_phase_1" : "initiative_phase_2";
}

function getCombatRoundPhaseInitiativeCursorStepForPhase(
  phase: CombatRoundPhase,
): CombatRoundCursorStep {
  return phase === "phase1" ? "i1" : "i2";
}

function getCombatRoundCombatExperienceTriggerForStep(
  step: CombatRoundStep,
): CombatExperienceTrigger | undefined {
  if (step === "select_actions") {
    return "combat_start";
  }

  if (step === "phase_1_actions") {
    return "phase1_attack";
  }

  if (step === "phase_2_actions") {
    return "phase2_attack";
  }

  if (step === "initiative_phase_1") {
    return "phase1_attack";
  }

  if (step === "initiative_phase_2") {
    return "phase2_attack";
  }

  return undefined;
}

function participantHasCombatExperienceForTrigger(input: {
  participant: CombatRoundParticipantState;
  roundNumber: number;
  trigger: CombatExperienceTrigger;
}): boolean {
  return (
    input.participant.combatExperience?.trigger === input.trigger &&
    input.participant.combatExperience.roundNumber === input.roundNumber
  );
}

function getCombatRoundParticipantTargetAliases(
  participant: Pick<
    CombatRoundParticipantState,
    "characterId" | "participantId" | "scenarioParticipantId"
  >,
): string[] {
  return [
    participant.participantId,
    participant.scenarioParticipantId,
    participant.characterId,
  ].filter(
    (entry, index, aliases): entry is string =>
      typeof entry === "string" && entry.length > 0 && aliases.indexOf(entry) === index,
  );
}

function combatRoundTargetMatchesParticipant(input: {
  participant: Pick<
    CombatRoundParticipantState,
    "characterId" | "participantId" | "scenarioParticipantId"
  >;
  targetParticipantId?: string;
}): boolean {
  return Boolean(
    input.targetParticipantId &&
    getCombatRoundParticipantTargetAliases(input.participant).includes(input.targetParticipantId),
  );
}

function getCombatRoundParticipantByTargetId(input: {
  state: CombatRoundState;
  targetParticipantId?: string;
}): CombatRoundParticipantState | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);

  if (!input.targetParticipantId) {
    return undefined;
  }

  return normalized.participants.find((participant) =>
    combatRoundTargetMatchesParticipant({
      participant,
      targetParticipantId: input.targetParticipantId,
    }),
  );
}

function getCombatRoundVisibilityValue(input: {
  seenAliases: string[];
  viewerAliases: string[];
  visibility?: CombatRoundVisibility;
}): boolean | undefined {
  for (const viewerAlias of input.viewerAliases) {
    const participantVisibility = input.visibility?.[viewerAlias];

    if (!participantVisibility) {
      continue;
    }

    for (const seenAlias of input.seenAliases) {
      const value = participantVisibility[seenAlias];

      if (value !== undefined) {
        return value;
      }
    }
  }

  return undefined;
}

function isCombatRoundParticipantAwareOfPhaseAttacker(input: {
  attacker: CombatRoundParticipantState;
  participant: CombatRoundParticipantState;
  visibility?: CombatRoundVisibility;
}): boolean {
  const attackerIsVisible = getCombatRoundVisibilityValue({
    seenAliases: getCombatRoundParticipantTargetAliases(input.attacker),
    viewerAliases: getCombatRoundParticipantTargetAliases(input.participant),
    visibility: input.visibility,
  });

  return attackerIsVisible !== false;
}

function combatRoundParticipantHasPendingExecutablePhaseAttack(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);
  const status = getEffectiveCombatRoundPhaseResolutionStatus({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });

  if (!participant) {
    return false;
  }

  if (status.substep === "done") {
    return false;
  }

  if (
    participant.stepStatuses[actionStep] === "skipped" ||
    participant.stepStatuses[actionStep] === "complete"
  ) {
    return false;
  }

  if (
    combatRoundParticipantPhaseActionHasCompletionEvidence({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    })
  ) {
    return false;
  }

  return combatRoundParticipantHasExecutablePhaseAttack({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });
}

function combatRoundPhaseThreatRequiresCombatExperience(
  threat: Pick<CombatRoundPhaseCombatExperienceThreat, "reason">,
): boolean {
  return threat.reason === "close_initiative" || threat.reason === "lower_initiative";
}

export function getCombatRoundPhaseInitiativeChoice(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundPhaseInitiativeChoice | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);

  for (let index = normalized.commands.length - 1; index >= 0; index -= 1) {
    const command = normalized.commands[index];

    if (
      !command ||
      command.roundNumber !== normalized.roundNumber ||
      command.type !== "submit_phase_initiative_choice" ||
      command.participantId !== input.participantId ||
      command.phase !== input.phase
    ) {
      continue;
    }

    const parsed = combatRoundPhaseInitiativeChoiceSchema.safeParse({
      ...command.facts,
      commandId: command.id,
      participantId: command.participantId,
      phase: command.phase,
      roundNumber: command.roundNumber,
      submittedAt: command.createdAt,
      submittedByUserId: command.createdByUserId,
    });

    return parsed.success ? parsed.data : undefined;
  }

  return undefined;
}

function combatRoundPhaseInitiativeChoiceSubmitted(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): boolean {
  return Boolean(getCombatRoundPhaseInitiativeChoice(input));
}

export function getCombatRoundPhaseAttackBackOutOpportunity(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): CombatRoundPhaseAttackBackOutOpportunity | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const trigger = getCombatExperienceTriggerForPhase(input.phase);

  if (!participant) {
    return undefined;
  }

  if (!isCombatRoundPhaseInitiativeComplete({ phase: input.phase, state: normalized })) {
    return undefined;
  }

  if (!isCombatRoundPhaseInitiativeCommitted({ phase: input.phase, state: normalized })) {
    return undefined;
  }

  if (
    participantHasCombatExperienceForTrigger({
      participant,
      roundNumber: normalized.roundNumber,
      trigger,
    })
  ) {
    return undefined;
  }

  if (
    !combatRoundParticipantHasPendingExecutablePhaseAttack({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    })
  ) {
    return undefined;
  }

  const participantInitiative = getCombatRoundInitiativeTotal(participant.initiatives[input.phase]);

  if (participantInitiative === undefined) {
    return undefined;
  }

  const threats = normalized.participants.flatMap((attacker) => {
    if (attacker.participantId === input.participantId) {
      return [];
    }

    if (
      !combatRoundParticipantHasPendingExecutablePhaseAttack({
        participantId: attacker.participantId,
        phase: input.phase,
        state: normalized,
      })
    ) {
      return [];
    }

    const attackerTargetId =
      attacker.declaration?.phaseContexts?.[input.phase]?.targetParticipantId;

    if (
      !combatRoundTargetMatchesParticipant({
        participant,
        targetParticipantId: attackerTargetId,
      })
    ) {
      return [];
    }

    if (
      !isCombatRoundParticipantAwareOfPhaseAttacker({
        attacker,
        participant,
        visibility: input.visibility,
      })
    ) {
      return [];
    }

    const attackerInitiative = getCombatRoundInitiativeTotal(attacker.initiatives[input.phase]);

    if (attackerInitiative === undefined) {
      return [];
    }

    const initiativeDifference = Math.abs(participantInitiative - attackerInitiative);
    const reason =
      initiativeDifference <= 3
        ? ("close_initiative" as const)
        : participantInitiative < attackerInitiative
          ? ("lower_initiative" as const)
          : ("higher_initiative" as const);

    return [
      {
        attackerInitiative,
        attackerParticipantId: attacker.participantId,
        initiativeDifference,
        participantInitiative,
        reason,
      },
    ];
  });

  if (threats.length === 0) {
    return undefined;
  }

  const ceRequired = threats.some(combatRoundPhaseThreatRequiresCombatExperience);

  return {
    ceRequired,
    participantId: input.participantId,
    phase: input.phase,
    reason: "attacked_while_attacking",
    threats,
    trigger,
  };
}

export function getCombatRoundPhaseCombatExperienceRequirement(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): CombatRoundPhaseCombatExperienceRequirement | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);

  if (
    combatRoundPhaseInitiativeChoiceSubmitted({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    })
  ) {
    return undefined;
  }

  const opportunity = getCombatRoundPhaseAttackBackOutOpportunity({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
    visibility: input.visibility,
  });
  const threats = opportunity?.threats.filter(combatRoundPhaseThreatRequiresCombatExperience) ?? [];

  if (!opportunity || threats.length === 0) {
    return undefined;
  }

  return {
    participantId: opportunity.participantId,
    phase: opportunity.phase,
    reason: opportunity.reason,
    threats,
    trigger: opportunity.trigger,
  };
}

export function getCombatRoundPhaseCombatExperienceDetectionReport(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): CombatRoundPhaseCombatExperienceDetectionParticipantReport[] {
  const normalized = combatRoundStateSchema.parse(input.state);

  return normalized.participants.map((participant) => {
    const phaseTargetId =
      participant.declaration?.phaseContexts?.[input.phase]?.targetParticipantId;
    const phaseAttackCapable = combatRoundParticipantHasPhaseAttack({
      participantId: participant.participantId,
      phase: input.phase,
      state: normalized,
    });
    const phaseTargetActiveInEncounter = Boolean(
      getCombatRoundParticipantByTargetId({
        state: normalized,
        targetParticipantId: phaseTargetId,
      }),
    );
    const hasA1A2AlreadyResolved = combatRoundParticipantPhaseActionHasCompletionEvidence({
      participantId: participant.participantId,
      phase: input.phase,
      state: normalized,
    });
    const initiativeTotal = getCombatRoundInitiativeTotal(participant.initiatives[input.phase]);
    const requirement = getCombatRoundPhaseCombatExperienceRequirement({
      participantId: participant.participantId,
      phase: input.phase,
      state: normalized,
      visibility: input.visibility,
    });
    const backOutOpportunity = getCombatRoundPhaseAttackBackOutOpportunity({
      participantId: participant.participantId,
      phase: input.phase,
      state: normalized,
      visibility: input.visibility,
    });
    const detectedIncomingAttackers = normalized.participants
      .filter((attacker) => attacker.participantId !== participant.participantId)
      .map((attacker) => {
        const targetId = attacker.declaration?.phaseContexts?.[input.phase]?.targetParticipantId;

        return {
          actionId: attacker.declaration?.actionId,
          aware: isCombatRoundParticipantAwareOfPhaseAttacker({
            attacker,
            participant,
            visibility: input.visibility,
          }),
          initiativeTotal: getCombatRoundInitiativeTotal(attacker.initiatives[input.phase]),
          participantId: attacker.participantId,
          phaseAttackCapable: combatRoundParticipantHasPhaseAttack({
            participantId: attacker.participantId,
            phase: input.phase,
            state: normalized,
          }),
          targetId,
          targetMatchesParticipant: combatRoundTargetMatchesParticipant({
            participant,
            targetParticipantId: targetId,
          }),
        };
      });
    const actionableIncomingAttackers = detectedIncomingAttackers.filter(
      (attacker) => attacker.phaseAttackCapable && attacker.targetMatchesParticipant,
    );
    let reasonIfNo: string | undefined;

    if (!requirement) {
      if (!phaseAttackCapable) {
        reasonIfNo = "participant has no attack in this phase";
      } else if (!phaseTargetId) {
        reasonIfNo = "participant phase target is missing";
      } else if (!phaseTargetActiveInEncounter) {
        reasonIfNo = "participant phase target is not active in the encounter";
      } else if (hasA1A2AlreadyResolved) {
        reasonIfNo = "participant phase attack is already rolled, skipped, or cancelled";
      } else if (initiativeTotal === undefined) {
        reasonIfNo = "participant initiative is missing";
      } else if (actionableIncomingAttackers.length === 0) {
        reasonIfNo = "no incoming phase attack targets this participant";
      } else if (actionableIncomingAttackers.every((attacker) => !attacker.aware)) {
        reasonIfNo = "incoming phase attacker is not visible or known to this participant";
      } else if (backOutOpportunity) {
        reasonIfNo = "initiative comparison does not require CE; back out remains available";
      } else {
        reasonIfNo = "initiative comparison does not require this participant";
      }
    }

    return {
      actionId: participant.declaration?.actionId,
      detectedIncomingAttackers,
      hasA1A2AlreadyResolved,
      initiativeTotal,
      label: participant.label,
      participantId: participant.participantId,
      phaseAttackCapable,
      phaseTargetActiveInEncounter,
      phaseTargetId,
      backOutAvailable: Boolean(backOutOpportunity),
      reasonIfNo,
      required: Boolean(requirement),
    };
  });
}

export function isCombatRoundPhaseCombatExperienceRollRequired(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): boolean {
  return Boolean(getCombatRoundPhaseCombatExperienceRequirement(input));
}

export function canBackOutCombatRoundPhaseAttack(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);

  return Boolean(
    normalized.currentStep === actionStep &&
    isCombatRoundPhaseInitiativeCommitted({ phase: input.phase, state: normalized }) &&
    getCombatRoundPhaseAttackBackOutOpportunity({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
      visibility: input.visibility,
    }) &&
    !combatRoundPhaseInitiativeChoiceSubmitted({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    }) &&
    !getCombatRoundOutgoingAttackResultForParticipantPhase({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    }),
  );
}

export function getCombatRoundPhaseCombatExperienceRequiredParticipantIds(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): string[] {
  const normalized = combatRoundStateSchema.parse(input.state);

  return getCombatRoundPhaseResolutionOrder({
    phase: input.phase,
    state: normalized,
  }).filter((participantId) =>
    isCombatRoundPhaseCombatExperienceRollRequired({
      participantId,
      phase: input.phase,
      state: normalized,
      visibility: input.visibility,
    }),
  );
}

export interface CombatRoundPhaseInitiativeChoiceStatus {
  ceRequired: boolean;
  choice?: CombatRoundPhaseInitiativeChoice;
  participantId: string;
  phase: CombatRoundPhase;
  threatened: boolean;
  threats: CombatRoundPhaseCombatExperienceThreat[];
  unresolved: boolean;
}

export function getCombatRoundPhaseInitiativeChoiceStatuses(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): CombatRoundPhaseInitiativeChoiceStatus[] {
  const normalized = combatRoundStateSchema.parse(input.state);

  return getCombatRoundPhaseResolutionOrder({
    phase: input.phase,
    state: normalized,
  }).flatMap((participantId) => {
    const opportunity = getCombatRoundPhaseAttackBackOutOpportunity({
      participantId,
      phase: input.phase,
      state: normalized,
      visibility: input.visibility,
    });

    if (!opportunity) {
      return [];
    }

    const choice = getCombatRoundPhaseInitiativeChoice({
      participantId,
      phase: input.phase,
      state: normalized,
    });

    return [
      {
        ceRequired: opportunity.ceRequired,
        choice,
        participantId,
        phase: input.phase,
        threatened: true,
        threats: opportunity.threats,
        unresolved: !choice,
      },
    ];
  });
}

function getFirstUnresolvedCombatRoundPhaseInitiativeChoiceParticipantId(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): string | undefined {
  return getCombatRoundPhaseInitiativeChoiceStatuses(input).find((status) => status.unresolved)
    ?.participantId;
}

export function isCombatRoundPhaseInitiativeResolutionOpen(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);

  return (
    normalized.currentStep === getCombatRoundPhaseInitiativeStepForPhase(input.phase) &&
    isCombatRoundPhaseInitiativeComplete({ phase: input.phase, state: normalized })
  );
}

export function getFirstCombatRoundPhaseCombatExperienceRequiredParticipantId(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): string | undefined {
  return getCombatRoundPhaseCombatExperienceRequiredParticipantIds(input)[0];
}

export function getFirstCombatStartExperienceRequiredParticipantId(
  state: CombatRoundState,
): string | undefined {
  const normalized = combatRoundStateSchema.parse(state);

  return normalized.participants.find((participant) =>
    isCombatStartExperienceRollRequired({
      participantId: participant.participantId,
      state: normalized,
    }),
  )?.participantId;
}

export function getCombatRoundRequiredCombatExperienceTrigger(input: {
  participantId: string;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): CombatExperienceTrigger | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const trigger = getCombatRoundCombatExperienceTriggerForStep(normalized.currentStep);

  if (!trigger) {
    return undefined;
  }

  if (trigger === "combat_start") {
    return isCombatStartExperienceRollRequired({
      participantId: input.participantId,
      state: normalized,
    })
      ? trigger
      : undefined;
  }

  const phase = getCombatExperiencePhaseForTrigger(trigger);

  if (!phase) {
    return undefined;
  }

  return isCombatRoundPhaseCombatExperienceRollRequired({
    participantId: input.participantId,
    phase,
    state: normalized,
    visibility: input.visibility,
  })
    ? trigger
    : undefined;
}

export function isCombatRoundCombatExperienceRollRequired(input: {
  participantId: string;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): boolean {
  return Boolean(getCombatRoundRequiredCombatExperienceTrigger(input));
}

function isCombatRoundDeclarationComplete(participant: CombatRoundParticipantState): boolean {
  const declarationStatus = participant.stepStatuses.select_actions ?? "pending";
  const declarationTargetValidation = participant.declaration
    ? validateCombatDeclarationTargets({
        actingParticipantId: participant.participantId,
        actionId: participant.declaration.actionId,
        movementKind: participant.declaration.movementIntent?.mode,
        phaseContexts: participant.declaration.phaseContexts,
        secondaryActionContext: participant.declaration.secondaryActionContext,
        selectedOpponentId: participant.declaration.combatContext?.selectedOpponentId,
        secondaryActionId: participant.declaration.secondaryActionId,
      })
    : undefined;
  const hasCompleteStatus =
    declarationStatus === "submitted" ||
    declarationStatus === "gmEdited" ||
    declarationStatus === "locked" ||
    declarationStatus === "complete" ||
    declarationStatus === "skipped";

  if (participant.declaration && !declarationTargetValidation?.valid) {
    return false;
  }

  return (
    hasCompleteStatus || Boolean(participant.declaration && declarationTargetValidation?.valid)
  );
}

export function getFirstCombatRoundDeclarationRequiredParticipantId(
  state: CombatRoundState,
): string | undefined {
  const normalized = combatRoundStateSchema.parse(state);

  return normalized.participants.find(
    (participant) => !isCombatRoundDeclarationComplete(participant),
  )?.participantId;
}

function buildCombatExperienceEffectEventId(input: {
  commandId: string;
  participantId: string;
  roundNumber: number;
}): string {
  return [
    "combat-effect-event",
    "combat-experience",
    input.roundNumber,
    input.participantId,
    input.commandId,
  ].join(":");
}

function buildCombatExperienceEffectId(input: {
  commandId: string;
  participantId: string;
  roundNumber: number;
}): string {
  return [
    "combat-effect",
    "combat-experience",
    input.roundNumber,
    input.participantId,
    input.commandId,
  ].join(":");
}

function buildCombatExperiencePhaseModifierId(input: {
  commandId: string;
  participantId: string;
  phase: CombatRoundPhase;
  roundNumber: number;
}): string {
  return [
    "combat-modifier",
    "combat-experience",
    input.roundNumber,
    input.phase,
    input.participantId,
    input.commandId,
  ].join(":");
}

function addCombatRoundPhaseCombatExperienceModifier(input: {
  combatContext?: ScenarioParticipantCombatContext;
  commandId: string;
  participant: CombatRoundParticipantState;
  participantId: string;
  phase: CombatRoundPhase;
  result: CombatRoundCombatExperienceResult;
}): {
  combatContext: ScenarioParticipantCombatContext;
  modifierIds: string[];
} {
  const currentContext = scenarioParticipantCombatContextSchema.parse(input.combatContext ?? {});

  if (input.result.modifierValue >= 0) {
    return {
      combatContext: currentContext,
      modifierIds: [],
    };
  }

  const modifierId = buildCombatExperiencePhaseModifierId({
    commandId: input.commandId,
    participantId: input.participantId,
    phase: input.phase,
    roundNumber: input.result.roundNumber,
  });
  const modifier = scenarioCombatModifierEntrySchema.parse({
    durationRounds: 1,
    generated: true,
    id: modifierId,
    notes: "combat experience attacked while attacking",
    scope: "until",
    sourceActionId: input.participant.declaration?.actionId,
    sourcePhase: input.phase,
    sourceRule: `combat-experience-${input.phase}-attacked-while-attacking`,
    value: input.result.modifierValue,
  } satisfies ScenarioCombatModifierEntry);

  return {
    combatContext: scenarioParticipantCombatContextSchema.parse({
      ...currentContext,
      modifierBuckets: {
        ...currentContext.modifierBuckets,
        situationObSkill: [
          ...currentContext.modifierBuckets.situationObSkill.filter(
            (entry) => entry.id !== modifierId,
          ),
          modifier,
        ],
      },
    }),
    modifierIds: [modifierId],
  };
}

export function removeCombatRoundCombatExperienceCombatContextModifiers(input: {
  combatContext?: ScenarioParticipantCombatContext;
  command: CombatRoundCommand;
}): ScenarioParticipantCombatContext {
  const currentContext = scenarioParticipantCombatContextSchema.parse(input.combatContext ?? {});
  const createdModifierIds = new Set(
    Array.isArray(input.command.facts.createdCombatModifierIds)
      ? input.command.facts.createdCombatModifierIds.filter(
          (entry): entry is string => typeof entry === "string",
        )
      : [],
  );

  if (createdModifierIds.size === 0) {
    return currentContext;
  }

  return scenarioParticipantCombatContextSchema.parse({
    ...currentContext,
    modifierBuckets: Object.fromEntries(
      Object.entries(currentContext.modifierBuckets).map(([bucketKey, entries]) => [
        bucketKey,
        entries.filter((entry) => !createdModifierIds.has(entry.id)),
      ]),
    ),
  });
}

export function restoreCombatRoundBackOutCombatContextModifiers(input: {
  combatContext?: ScenarioParticipantCombatContext;
  command: CombatRoundCommand;
}): ScenarioParticipantCombatContext {
  const currentContext = scenarioParticipantCombatContextSchema.parse(input.combatContext ?? {});
  const softenedModifiers = Array.isArray(input.command.facts.softenedModifiers)
    ? input.command.facts.softenedModifiers
    : [];

  return restoreCombatActionGeneratedBackOutModifiers({
    combatContext: currentContext,
    softenedModifiers,
  });
}

export function rollCombatRoundCombatExperience(input: {
  combatContext?: ScenarioParticipantCombatContext;
  combatEffects?: CombatEffectsState;
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  createdRevision?: string;
  difficulty?: number;
  encounterId?: string;
  opportunityId?: string;
  participantId: string;
  rng?: () => number;
  scenarioId?: string;
  scenarioParticipantId?: string;
  skillTotal?: number;
  skillTotalSource?: string;
  skillTotalWarning?: string;
  state: CombatRoundState;
  trigger?: CombatExperienceTrigger;
  visibility?: CombatRoundVisibility;
}): {
  combatContext: ScenarioParticipantCombatContext;
  combatEffects: CombatEffectsState;
  command: CombatRoundCommand;
  result: CombatRoundCombatExperienceResult;
  state: CombatRoundState;
} {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const trigger =
    input.trigger ??
    getCombatRoundRequiredCombatExperienceTrigger({
      participantId: input.participantId,
      state: normalized,
      visibility: input.visibility,
    }) ??
    "combat_start";
  const phase = getCombatExperiencePhaseForTrigger(trigger);
  const phaseRequirement = phase
    ? getCombatRoundPhaseCombatExperienceRequirement({
        participantId: input.participantId,
        phase,
        state: normalized,
        visibility: input.visibility,
      })
    : undefined;

  if (!participant) {
    throw new RangeError("Combat Experience participant is not in the active round.");
  }

  if (trigger === "combat_start" && normalized.currentStep !== "select_actions") {
    throw new RangeError("Combat Experience can only be rolled during declaration.");
  }

  if (trigger === "combat_start" && !isCombatRoundCombatExperienceWindowOpen(normalized)) {
    throw new RangeError(
      "Combat Experience rolls are not open. Set Combat Experience difficulty first.",
    );
  }

  if (phase) {
    const requiredStep = getCombatRoundPhaseActionStepForPhase(phase);

    if (normalized.currentStep !== requiredStep) {
      throw new RangeError("Combat Experience can only be rolled after initiative is committed.");
    }

    if (!isCombatRoundPhaseInitiativeCommitted({ phase, state: normalized })) {
      throw new RangeError("Phase initiative must be committed before Combat Experience.");
    }

    if (!phaseRequirement) {
      throw new RangeError("Combat Experience is not required for this participant.");
    }

    if (
      combatRoundPhaseInitiativeChoiceSubmitted({
        participantId: input.participantId,
        phase,
        state: normalized,
      })
    ) {
      throw new RangeError("Phase initiative choice already submitted for this participant.");
    }
  }

  if (
    participant.combatExperience?.trigger === trigger &&
    participant.combatExperience.roundNumber === normalized.roundNumber
  ) {
    throw new RangeError("Combat Experience already rolled for this participant.");
  }

  const rng = input.rng ?? Math.random;
  const difficulty = input.difficulty ?? getCombatRoundCombatExperienceDifficulty(normalized);
  const skillTotal = Math.trunc(input.skillTotal ?? 0);
  const noRollRequired = skillTotal >= difficulty;
  const roll = noRollRequired ? undefined : rollOpenEndedD20(rng);
  const finalTotal = noRollRequired ? skillTotal : skillTotal + (roll?.dieResult ?? 0);
  const { difficultyShift, effectiveTableTotal } = getCombatExperienceEffectiveTableTotal({
    difficulty,
    finalTotal,
  });
  const panicDurationRounds =
    !phase && effectiveTableTotal <= 5 ? rollCombatExperiencePanicDuration(rng) : undefined;
  const evaluation = phase
    ? evaluatePhaseCombatExperienceResult(finalTotal, {
        difficulty,
      })
    : evaluateCombatExperienceResult(finalTotal, {
        difficulty,
        panicDurationRounds,
      });
  const result = combatRoundCombatExperienceResultSchema.parse({
    ...evaluation,
    difficulty,
    finalTotal,
    noRollRequired,
    openEndedD10s: roll?.openEndedD10s ?? [],
    rolledAt: input.command.createdAt,
    rolledByUserId: input.command.createdByUserId,
    rollD20: roll?.rollD20,
    rollTotal: roll?.dieResult,
    roundNumber: normalized.roundNumber,
    skillTotal,
    skillTotalSource: input.skillTotalSource,
    skillTotalWarning: input.skillTotalWarning,
    trigger,
  });
  const commandId =
    input.command.commandId ??
    buildCombatRoundCommandId({
      createdAt: input.command.createdAt,
      participantId: input.participantId,
      state: normalized,
      type: "roll_combat_experience",
    });

  const phaseActionStep = phase ? getCombatRoundPhaseActionStepForPhase(phase) : undefined;
  const previousPhaseActionStepStatus = phaseActionStep
    ? participant.stepStatuses[phaseActionStep]
    : undefined;
  const previousPhaseResolutionStatus = phase
    ? normalized.phaseResolutionStatuses[input.participantId]?.[phase]
    : undefined;
  const defaultBeforeCursor = getDefaultCombatRoundCursor({
    participantId: input.participantId,
    roundNumber: normalized.roundNumber,
    step: phase ? getCombatRoundPhaseActionStepForPhase(phase) : "select_actions",
  });
  const beforeCursor =
    phase &&
    normalized.currentCursor?.roundNumber === normalized.roundNumber &&
    normalized.currentCursor.step === getCombatRoundAttackCursorStepForPhase(phase)
      ? normalized.currentCursor
      : defaultBeforeCursor;
  const targetParticipantId = input.scenarioParticipantId ?? input.participantId;
  const createdCombatEffectEventId = result.needsEffectRow
    ? buildCombatExperienceEffectEventId({
        commandId,
        participantId: targetParticipantId,
        roundNumber: normalized.roundNumber,
      })
    : undefined;
  const createdCombatEffectIds = result.needsEffectRow
    ? [
        buildCombatExperienceEffectId({
          commandId,
          participantId: targetParticipantId,
          roundNumber: normalized.roundNumber,
        }),
      ]
    : [];
  const phaseCombatModifier = phase
    ? addCombatRoundPhaseCombatExperienceModifier({
        combatContext: input.combatContext,
        commandId,
        participant,
        participantId: targetParticipantId,
        phase,
        result,
      })
    : {
        combatContext: scenarioParticipantCombatContextSchema.parse(input.combatContext ?? {}),
        modifierIds: [],
      };
  const phaseAttackCancelled = phaseCombatExperienceCancelsAttack(result);
  const stateAfterResult = moveCombatRoundAfterCombatExperienceResult({
    createdAt: input.command.createdAt,
    participantId: input.participantId,
    result,
    state: {
      ...normalized,
      combatExperienceDifficulty: difficulty,
    },
    visibility: input.visibility,
  });
  const afterCursor = stateAfterResult.currentCursor ?? beforeCursor;
  const command = combatRoundCommandSchema.parse({
    afterCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      createdCombatEffectEventId,
      createdCombatEffectIds,
      createdCombatModifierIds: phaseCombatModifier.modifierIds,
      difficulty,
      difficultyShift,
      durationRounds: result.durationRounds,
      effectiveTableTotal,
      evaluatedResult: evaluation,
      finalTotal,
      modifierValue: result.modifierValue,
      noRollRequired,
      opportunityId: input.opportunityId,
      openEndedD10s: roll?.openEndedD10s ?? [],
      phaseAttackCancelled,
      ...(phaseRequirement
        ? {
            phaseCombatExperienceReason: phaseRequirement.reason,
            phaseCombatExperienceThreats: phaseRequirement.threats,
          }
        : {}),
      previousCombatExperience: participant.combatExperience,
      ...(previousPhaseActionStepStatus
        ? {
            previousPhaseActionStepStatus,
          }
        : {}),
      ...(previousPhaseResolutionStatus
        ? {
            previousPhaseResolutionStatus,
          }
        : {}),
      resultBand: result.resultBand,
      resultLabel: result.label,
      rollD20: roll?.rollD20,
      rollTotal: roll?.dieResult,
      phase,
      skillTotalSource: input.skillTotalSource,
      skillTotalWarning: input.skillTotalWarning,
      scenarioParticipantId: targetParticipantId,
      skillTotal,
      success: finalTotal >= difficulty,
      trigger,
    },
    id: commandId,
    participantId: input.participantId,
    phase,
    roundNumber: normalized.roundNumber,
    step: phase ? getCombatRoundAttackCursorStepForPhase(phase) : "DE",
    type: "roll_combat_experience",
  });
  const currentCombatEffects = combatEffectsStateSchema.parse(input.combatEffects);
  const nextCombatEffects =
    result.needsEffectRow && createdCombatEffectEventId && createdCombatEffectIds[0]
      ? combatEffectsStateSchema.parse({
          ...currentCombatEffects,
          effects: [
            ...currentCombatEffects.effects,
            combatEffectSchema.parse({
              canonicalLifecycle: buildCombatExperiencePersistentLifecycle({
                context: {
                  commandId,
                  createdAt: input.command.createdAt,
                  createdRevision: input.createdRevision,
                  createdSequence: getCombatRoundNextEventSequence(normalized),
                  encounterId: input.encounterId,
                  eventId: createdCombatEffectEventId,
                  ownerParticipantId: targetParticipantId,
                  roundNumber: normalized.roundNumber,
                },
                durationRounds: result.durationRounds,
                effectId: createdCombatEffectIds[0],
                modifierValue: result.modifierValue,
                phase,
                status: "active",
              }),
              combatWide: phase === undefined,
              combatModifierBucket: "general",
              createdAt: input.command.createdAt,
              damage: 0,
              description: result.note,
              duration: `${result.durationRounds} ${
                result.durationRounds === 1 ? "round" : "rounds"
              }`,
              effectGroup: "general",
              generalDamage: 0,
              id: createdCombatEffectIds[0],
              modifierValue: result.modifierValue,
              roundNumber: normalized.roundNumber,
              sourceEventId: createdCombatEffectEventId,
              status: "active",
              targetParticipantId,
              type: "general_modifier",
              updatedAt: input.command.createdAt,
            }),
          ],
          events: [
            ...currentCombatEffects.events,
            combatEffectEventSchema.parse({
              createdAt: input.command.createdAt,
              createdByUserId: input.command.createdByUserId,
              description: `Combat Experience: ${result.label}`,
              encounterId: input.encounterId,
              id: createdCombatEffectEventId,
              roundNumber: normalized.roundNumber,
              scenarioId: input.scenarioId,
              sourceActorId: targetParticipantId,
              sourceLabel: "Combat Experience",
              sourceType: "skill_roll",
              targetParticipantId,
            }),
          ],
        })
      : currentCombatEffects;

  return {
    combatContext: phaseCombatModifier.combatContext,
    combatEffects: nextCombatEffects,
    command,
    result,
    state: combatRoundStateSchema.parse({
      ...stateAfterResult,
      commands: [...normalized.commands, command],
      combatExperienceDifficulty: difficulty,
    }),
  };
}

export function removeCombatRoundCombatExperienceEffects(input: {
  combatEffects?: CombatEffectsState;
  command: CombatRoundCommand;
}): CombatEffectsState {
  const currentCombatEffects = combatEffectsStateSchema.parse(input.combatEffects);
  const createdCombatEffectIds = new Set(
    Array.isArray(input.command.facts.createdCombatEffectIds)
      ? input.command.facts.createdCombatEffectIds.filter(
          (entry): entry is string => typeof entry === "string",
        )
      : [],
  );
  const createdCombatEffectEventId =
    typeof input.command.facts.createdCombatEffectEventId === "string"
      ? input.command.facts.createdCombatEffectEventId
      : undefined;

  return combatEffectsStateSchema.parse({
    ...currentCombatEffects,
    effects: currentCombatEffects.effects.filter(
      (effect) => !createdCombatEffectIds.has(effect.id),
    ),
    events: currentCombatEffects.events.filter((event) => event.id !== createdCombatEffectEventId),
  });
}

function getLatestCombatRoundGlobalParticipantCommandIndex(input: {
  commandType: CombatRoundCommandType;
  participantId: string;
  roundNumber: number;
  state: CombatRoundState;
}): number {
  for (let index = input.state.commands.length - 1; index >= 0; index -= 1) {
    const command = input.state.commands[index];

    if (
      command?.roundNumber === input.roundNumber &&
      command.participantId === input.participantId &&
      command.type === input.commandType
    ) {
      return index;
    }
  }

  return -1;
}

function isGlobalCombatRoundCommandType(type: CombatRoundCommandType): boolean {
  return (
    type === "declare_action" ||
    type === "review_modifiers_phase1" ||
    type === "roll_initiative_phase1" ||
    type === "review_modifiers_phase2" ||
    type === "roll_initiative_phase2" ||
    type === "complete_round"
  );
}

function isUndoableCombatRoundCommandType(type: CombatRoundCommandType): boolean {
  return (
    isGlobalCombatRoundCommandType(type) ||
    type === "roll_attack" ||
    type === "progress_missile_readiness" ||
    type === "interrupt_missile_readiness" ||
    type === "commit_defense_review" ||
    type === "roll_parry" ||
    type === "roll_offensive_parry_brawling" ||
    type === "roll_continued_contact_maintenance" ||
    type === "roll_observation" ||
    type === "roll_hit_location" ||
    type === "roll_critical" ||
    type === "decide_double_attack_phase2" ||
    type === "review_feint_feasibility" ||
    type === "roll_feint" ||
    type === "commit_feint_result" ||
    type === "respond_adjust_distance" ||
    type === "review_adjust_distance_roll_adjustment" ||
    type === "roll_adjust_distance" ||
    type === "commit_adjust_distance" ||
    type === "review_break_off" ||
    type === "roll_break_off" ||
    type === "commit_break_off" ||
    type === "open_disarm" ||
    type === "roll_disarm" ||
    type === "commit_disarm" ||
    type === "complete_remaining_step" ||
    type === "skip_phase_action" ||
    type === "back_out_phase_attack" ||
    type === "submit_phase_initiative_choice" ||
    type === "commit_phase_initiative_resolution" ||
    type === "roll_combat_experience" ||
    type === "set_pair_distance" ||
    type === "complete_damage_review_phase1" ||
    type === "complete_damage_review_phase2" ||
    type === "resolve_damage" ||
    type === "commit_phase_damage" ||
    type === "transition_critical_bleed" ||
    type === "prepare_round_end_review" ||
    type === "commit_round_end_participant_review" ||
    type === "roll_round_end_health_check" ||
    type === "roll_round_end_distance_control" ||
    type === "commit_round_end_distance_control" ||
    type === "advance_combat_boundary" ||
    type === "review_combat_task" ||
    type === "advance_combat_task" ||
    type === "roll_combat_task" ||
    type === "resolve_combat_task" ||
    type === "interrupt_combat_task" ||
    type === "cancel_combat_task"
  );
}

function getLatestCombatRoundGlobalCommandIndex(input: {
  roundNumber: number;
  state: CombatRoundState;
}): number {
  for (let index = input.state.commands.length - 1; index >= 0; index -= 1) {
    const command = input.state.commands[index];

    if (
      command?.roundNumber === input.roundNumber &&
      isGlobalCombatRoundCommandType(command.type)
    ) {
      return index;
    }
  }

  return -1;
}

function getLatestCombatRoundUndoableCommandIndex(input: {
  roundNumber: number;
  state: CombatRoundState;
}): number {
  for (let index = input.state.commands.length - 1; index >= 0; index -= 1) {
    const command = input.state.commands[index];

    if (
      command?.roundNumber === input.roundNumber &&
      isUndoableCombatRoundCommandType(command.type)
    ) {
      return index;
    }
  }

  return -1;
}

function getStepIndex(step: CombatRoundStep): number {
  return COMBAT_ROUND_STEPS.indexOf(step);
}

function isSameCombatRoundStepSnapshot(
  left: CombatRoundStepSnapshot,
  right: Pick<CombatRoundStepSnapshot, "participantId" | "roundNumber" | "step">,
): boolean {
  return (
    left.roundNumber === right.roundNumber &&
    left.participantId === right.participantId &&
    left.step === right.step
  );
}

function clearSnapshotsFromStep(input: {
  participantId?: string;
  roundNumber: number;
  snapshots: CombatRoundStepSnapshot[];
  step: CombatRoundStep;
}): CombatRoundStepSnapshot[] {
  const clearFromIndex = getStepIndex(input.step);

  return input.snapshots.filter((snapshot) => {
    if (snapshot.roundNumber !== input.roundNumber) {
      return true;
    }

    if (input.participantId && snapshot.participantId !== input.participantId) {
      return true;
    }

    return getStepIndex(snapshot.step) < clearFromIndex;
  });
}

function clearSnapshotsForCombatRoundStep(input: {
  participantId?: string;
  roundNumber: number;
  selectedAttackResult?: CombatRoundAttackRollResult;
  snapshots: CombatRoundStepSnapshot[];
  step: CombatRoundStep;
}): CombatRoundStepSnapshot[] {
  const pairedStepsByStep: Partial<Record<CombatRoundStep, CombatRoundStep[]>> = {
    phase_1_actions: ["phase_1_actions", "review_phase_2_actions", "phase_1_damage"],
    phase_1_damage: ["phase_1_damage"],
    phase_2_actions: ["phase_2_actions", "review_phase_2_damage", "phase_2_damage"],
    phase_2_damage: ["phase_2_damage"],
    review_phase_2_actions: ["review_phase_2_actions"],
    review_phase_2_damage: ["review_phase_2_damage"],
  };
  const pairedSteps = pairedStepsByStep[input.step];

  if (!pairedSteps) {
    return clearSnapshotsFromStep(input);
  }

  if (input.selectedAttackResult) {
    const attackStep = getCombatRoundPhaseActionStepForPhase(input.selectedAttackResult.phase);
    const parryStep = getCombatRoundParryReviewStepForPhase(input.selectedAttackResult.phase);
    const damageStep = getCombatRoundDamageReviewStepForPhase(input.selectedAttackResult.phase);
    const clearedSnapshotKeys = new Set<string>();

    if (input.step === attackStep) {
      clearedSnapshotKeys.add(`${input.selectedAttackResult.attackerParticipantId}:${attackStep}`);
      clearedSnapshotKeys.add(`${input.selectedAttackResult.defenderParticipantId}:${parryStep}`);
      clearedSnapshotKeys.add(`${input.selectedAttackResult.defenderParticipantId}:${damageStep}`);
    } else if (input.step === parryStep) {
      clearedSnapshotKeys.add(`${input.selectedAttackResult.defenderParticipantId}:${parryStep}`);
      clearedSnapshotKeys.add(`${input.selectedAttackResult.defenderParticipantId}:${damageStep}`);
    } else if (input.step === damageStep) {
      clearedSnapshotKeys.add(`${input.selectedAttackResult.defenderParticipantId}:${damageStep}`);
    }

    return input.snapshots.filter(
      (snapshot) =>
        snapshot.roundNumber !== input.roundNumber ||
        !clearedSnapshotKeys.has(`${snapshot.participantId}:${snapshot.step}`),
    );
  }

  if (input.participantId) {
    return input.snapshots.filter((snapshot) => {
      if (snapshot.roundNumber !== input.roundNumber) {
        return true;
      }

      if (snapshot.participantId !== input.participantId) {
        return true;
      }

      if (input.step === "review_phase_2_actions") {
        return snapshot.step !== "review_phase_2_actions" && snapshot.step !== "phase_1_damage";
      }

      if (input.step === "review_phase_2_damage") {
        return snapshot.step !== "review_phase_2_damage" && snapshot.step !== "phase_2_damage";
      }

      return !pairedSteps.includes(snapshot.step);
    });
  }

  return input.snapshots.filter(
    (snapshot) =>
      snapshot.roundNumber !== input.roundNumber || !pairedSteps.includes(snapshot.step),
  );
}

function clearCombatRoundParticipantOutgoingResolutionState(input: {
  participantId: string;
  phase?: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const outgoingResults = normalized.participants
    .filter((participant) => participant.participantId === input.participantId)
    .flatMap((participant) => Object.values(participant.attackResultsByOpportunity ?? {}))
    .filter((result) => !input.phase || result.phase === input.phase);
  const affectedParticipantIds = new Set<string>([input.participantId]);
  const affectedDefenderSteps = new Map<string, Partial<Record<CombatRoundStep, "pending">>>();
  const affectedSnapshotSteps = new Map<string, Set<CombatRoundStep>>();

  for (const result of outgoingResults) {
    affectedParticipantIds.add(result.defenderParticipantId);
    const attackerSteps = affectedSnapshotSteps.get(result.attackerParticipantId) ?? new Set();
    attackerSteps.add(getCombatRoundPhaseActionStepForPhase(result.phase));
    affectedSnapshotSteps.set(result.attackerParticipantId, attackerSteps);

    const defenderSteps = affectedSnapshotSteps.get(result.defenderParticipantId) ?? new Set();
    affectedDefenderSteps.set(result.defenderParticipantId, {
      ...affectedDefenderSteps.get(result.defenderParticipantId),
      ...(result.phase === "phase1"
        ? {
            phase_1_damage: "pending",
            review_phase_2_actions: "pending",
          }
        : {
            phase_2_damage: "pending",
            review_phase_2_damage: "pending",
          }),
    });
    defenderSteps.add(getCombatRoundParryReviewStepForPhase(result.phase));
    defenderSteps.add(getCombatRoundDamageReviewStepForPhase(result.phase));
    affectedSnapshotSteps.set(result.defenderParticipantId, defenderSteps);
  }

  return {
    ...normalized,
    phaseResolutionCursor:
      normalized.phaseResolutionCursor &&
      affectedParticipantIds.has(normalized.phaseResolutionCursor.participantId)
        ? undefined
        : normalized.phaseResolutionCursor,
    phaseResolutionResults: normalized.phaseResolutionResults.filter(
      (result) =>
        result.roundNumber !== normalized.roundNumber ||
        result.attackerParticipantId !== input.participantId ||
        (input.phase !== undefined && result.phase !== input.phase),
    ),
    phaseResolutionStatuses: {
      ...normalized.phaseResolutionStatuses,
      [input.participantId]: input.phase
        ? {
            ...normalized.phaseResolutionStatuses[input.participantId],
            [input.phase]: undefined,
          }
        : {},
    },
    participants: normalized.participants.map((participant) => {
      if (participant.participantId === input.participantId) {
        const attackResultsByOpportunity = Object.fromEntries(
          Object.entries(participant.attackResultsByOpportunity ?? {}).filter(
            ([, result]) => input.phase !== undefined && result.phase !== input.phase,
          ),
        );
        const phaseStepStatuses =
          input.phase === "phase1"
            ? {
                phase_1_actions: "pending" as const,
                phase_1_damage: "pending" as const,
                review_phase_2_actions: "pending" as const,
              }
            : input.phase === "phase2"
              ? {
                  phase_2_actions: "pending" as const,
                  phase_2_damage: "pending" as const,
                  review_phase_2_damage: "pending" as const,
                }
              : {
                  phase_1_actions: "pending" as const,
                  phase_1_damage: "pending" as const,
                  phase_2_actions: "pending" as const,
                  phase_2_damage: "pending" as const,
                  review_phase_2_actions: "pending" as const,
                  review_phase_2_damage: "pending" as const,
                };

        return {
          ...participant,
          attackResultsByOpportunity,
          attackResults: deriveCombatRoundAttackResultsCompatibility({
            attackResultsByOpportunity,
            participantId: participant.participantId,
          }),
          stepStatuses: {
            ...participant.stepStatuses,
            ...phaseStepStatuses,
          },
        };
      }

      const defenderSteps = affectedDefenderSteps.get(participant.participantId);

      return defenderSteps
        ? {
            ...participant,
            stepStatuses: {
              ...participant.stepStatuses,
              ...defenderSteps,
            },
          }
        : participant;
    }),
    stepSnapshots: normalized.stepSnapshots.filter((snapshot) => {
      if (snapshot.roundNumber !== normalized.roundNumber) {
        return true;
      }

      return !affectedSnapshotSteps.get(snapshot.participantId)?.has(snapshot.step);
    }),
  };
}

function participantStateFromEncounterParticipant(input: {
  existing?: CombatRoundParticipantState;
  participant: EncounterParticipant;
}): CombatRoundParticipantState {
  const attackResultsByOpportunity = input.existing?.attackResultsByOpportunity ?? {};
  return {
    attackResults: deriveCombatRoundAttackResultsCompatibility({
      attackResultsByOpportunity,
      participantId: input.participant.id,
    }),
    attackResultsByOpportunity,
    characterId: input.participant.characterId,
    combatExperience: input.existing?.combatExperience,
    declaration: input.existing?.declaration,
    initiatives: input.existing?.initiatives ?? {},
    label: input.participant.label,
    participantId: input.participant.id,
    scenarioParticipantId: input.participant.scenarioParticipantId,
    stepStatuses: mergeStepStatuses(input.existing?.stepStatuses),
  };
}

function getCombatRoundEncounterTargetIds(participants: EncounterParticipant[]): Set<string> {
  const targetIds = new Set<string>();

  participants.forEach((participant) => {
    targetIds.add(participant.id);

    if (participant.scenarioParticipantId) {
      targetIds.add(participant.scenarioParticipantId);
    }

    if (participant.characterId) {
      targetIds.add(participant.characterId);
    }
  });

  return targetIds;
}

function sanitizeCombatRoundContextTargetIds(
  context: z.infer<typeof scenarioParticipantCombatContextSchema> | undefined,
  validTargetIds: Set<string>,
): z.infer<typeof scenarioParticipantCombatContextSchema> | undefined {
  if (!context) {
    return undefined;
  }

  const targetParticipantId =
    context.targetParticipantId && validTargetIds.has(context.targetParticipantId)
      ? context.targetParticipantId
      : undefined;
  const selectedOpponentId =
    context.selectedOpponentId && validTargetIds.has(context.selectedOpponentId)
      ? context.selectedOpponentId
      : undefined;

  return scenarioParticipantCombatContextSchema.parse({
    ...context,
    selectedOpponentId,
    targetParticipantId,
  });
}

function sanitizeCombatRoundDeclarationTargets(input: {
  participant: CombatRoundParticipantState;
  validTargetIds: Set<string>;
}): { participant: CombatRoundParticipantState; repaired: boolean } {
  const storedDeclaration = input.participant.declaration;

  if (!storedDeclaration) {
    return { participant: input.participant, repaired: false };
  }
  const declaration =
    storedDeclaration.actionId === "feint_attack" &&
    storedDeclaration.feint &&
    input.validTargetIds.has(storedDeclaration.feint.targetParticipantId)
      ? synchronizeCombatRoundFeintDeclarationTarget(storedDeclaration)
      : storedDeclaration;
  const feintTargetSynchronized =
    storedDeclaration.phaseContexts?.phase1?.targetParticipantId !==
      declaration.phaseContexts?.phase1?.targetParticipantId ||
    storedDeclaration.phaseContexts?.phase2?.targetParticipantId !==
      declaration.phaseContexts?.phase2?.targetParticipantId ||
    storedDeclaration.attackOpportunities?.find(
      (opportunity) => opportunity.phase === "phase2" && opportunity.origin === "feint_attack",
    )?.targetParticipantId !==
      declaration.attackOpportunities?.find(
        (opportunity) => opportunity.phase === "phase2" && opportunity.origin === "feint_attack",
      )?.targetParticipantId;

  const phase1 = sanitizeCombatRoundContextTargetIds(
    declaration.phaseContexts?.phase1,
    input.validTargetIds,
  );
  const phase2 = sanitizeCombatRoundContextTargetIds(
    declaration.phaseContexts?.phase2,
    input.validTargetIds,
  );
  const combatContext = sanitizeCombatRoundContextTargetIds(
    declaration.combatContext,
    input.validTargetIds,
  );
  const movementIntent = declaration.movementIntent
    ? movementIntentSchema.parse({
        ...declaration.movementIntent,
        distancePreferences: declaration.movementIntent.distancePreferences.filter((preference) =>
          input.validTargetIds.has(preference.targetParticipantId),
        ),
      })
    : undefined;
  const secondaryActionContext =
    declaration.secondaryActionContext?.action === "observe_opponent" &&
    input.validTargetIds.has(declaration.secondaryActionContext.targetParticipantId)
      ? declaration.secondaryActionContext
      : undefined;
  const repaired =
    declaration.phaseContexts?.phase1?.targetParticipantId !== phase1?.targetParticipantId ||
    declaration.phaseContexts?.phase2?.targetParticipantId !== phase2?.targetParticipantId ||
    declaration.combatContext?.targetParticipantId !== combatContext?.targetParticipantId ||
    declaration.combatContext?.selectedOpponentId !== combatContext?.selectedOpponentId ||
    declaration.secondaryActionContext?.targetParticipantId !==
      secondaryActionContext?.targetParticipantId ||
    (declaration.movementIntent?.distancePreferences.length ?? 0) !==
      (movementIntent?.distancePreferences.length ?? 0);

  if (!repaired) {
    return feintTargetSynchronized
      ? {
          participant: { ...input.participant, declaration },
          repaired: false,
        }
      : { participant: input.participant, repaired: false };
  }

  return {
    participant: {
      ...input.participant,
      declaration: combatRoundDeclarationSchema.parse({
        ...declaration,
        combatContext,
        movementIntent,
        secondaryActionContext,
        phaseContexts: {
          phase1,
          phase2,
        },
      }),
      stepStatuses: {
        ...input.participant.stepStatuses,
        select_actions: "pending",
      },
    },
    repaired: true,
  };
}

export function buildCombatRoundAttackRollResult(input: {
  actionId: string;
  attackPhaseDefensivePenalty?: CombatAttackPhaseDefensivePenalty;
  attackIndex?: number;
  attackModeId?: string;
  attackType?: "melee" | "missile" | "thrown";
  attackOpportunityId?: string;
  attackSlot?: "attack_1" | "attack_2";
  attackerParticipantId: string;
  declarationId?: string;
  defenderDb: number;
  defenderParticipantId: string;
  ob: number;
  openEndedD10s?: number[];
  phase: CombatRoundPhase;
  roll?: number;
  rollD20?: number;
  rollTotal?: number;
  rolledAt: string;
  rolledByUserId?: string;
  weaponArmorClass?: CombatArmorModifierClass;
  weaponCriticalCode?: string;
  weaponDamageClass?: string;
  weaponDmb?: number;
  weaponDmbRoll?: {
    diceCount: number;
    diceSides: number;
    flatModifier: number;
    gmStrengthModifier?: number;
    provenance: string;
    rolls: number[];
    total: number;
  };
  weaponDmbFormula?: NonNullable<z.input<typeof WeaponAttackModeSchema>["dmbFormula"]>;
  weaponDmbRaw?: string;
  weaponModeInitiative?: number;
  weaponModeRange?: string;
  weaponModeSourceMetadata?: z.input<typeof ImportedWeaponSourceMetadataSchema>;
  weaponInstanceId?: string;
  weaponName: string;
  weaponSourceId?: string;
  weaponSourceSlot?: CombatAttackSourceSlot;
  weaponTemplateId?: string;
}): CombatRoundAttackRollResult {
  const rollTotal = input.rollTotal ?? input.roll;

  if (rollTotal === undefined) {
    throw new RangeError("Combat attack result requires an open-ended roll total.");
  }

  const toHit = resolveCombatToHit({
    db: input.defenderDb,
    ob: input.ob,
    rollTotal,
  });

  return combatRoundAttackRollResultSchema.parse({
    actionId: input.actionId,
    attackPhaseDefensivePenalty: input.attackPhaseDefensivePenalty,
    attackIndex: input.attackIndex,
    attackModeId: input.attackModeId,
    attackType: input.attackType,
    attackOpportunityId: input.attackOpportunityId,
    attackSlot: input.attackSlot,
    attackerParticipantId: input.attackerParticipantId,
    declarationId: input.declarationId,
    defenderDb: input.defenderDb,
    defenderParryModifier: toHit.parryModifier,
    defenderParticipantId: input.defenderParticipantId,
    grazing: toHit.grazing,
    hit: toHit.hit,
    kind: "attackRoll",
    lookupTotal: toHit.lookupTotal,
    marginOverMissThreshold: toHit.lookupTotal - 10,
    ob: input.ob,
    openEndedD10s: input.openEndedD10s ?? [],
    phase: input.phase,
    roll: input.roll,
    rollD20: input.rollD20 ?? input.roll,
    rollTotal,
    rolledAt: input.rolledAt,
    rolledByUserId: input.rolledByUserId,
    tableResult: toHit.resultLabel,
    weaponArmorClass: input.weaponArmorClass,
    weaponCriticalCode: input.weaponCriticalCode,
    weaponDamageClass: input.weaponDamageClass,
    weaponDmb: input.weaponDmb,
    weaponDmbRoll: input.weaponDmbRoll,
    weaponDmbFormula: input.weaponDmbFormula,
    weaponDmbRaw: input.weaponDmbRaw,
    weaponModeInitiative: input.weaponModeInitiative,
    weaponModeRange: input.weaponModeRange,
    weaponModeSourceMetadata: input.weaponModeSourceMetadata,
    weaponInstanceId: input.weaponInstanceId,
    weaponName: input.weaponName,
    weaponSourceId: input.weaponSourceId,
    weaponSourceSlot: input.weaponSourceSlot,
    weaponTemplateId: input.weaponTemplateId,
  });
}

export function getCombatRoundAttackResultsForParticipantPhase(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): {
  incoming: CombatRoundAttackRollResult[];
  outgoing?: CombatRoundAttackRollResult;
} {
  const normalized = combatRoundStateSchema.parse(input.state);
  const resultsForParticipant = (participant: CombatRoundParticipantState) => {
    return Object.values(participant.attackResultsByOpportunity ?? {})
      .filter((result) => result.phase === input.phase)
      .sort(
        (left, right) =>
          (left.attackIndex ?? Number.MAX_SAFE_INTEGER) -
            (right.attackIndex ?? Number.MAX_SAFE_INTEGER) ||
          left.rolledAt.localeCompare(right.rolledAt),
      );
  };
  const outgoing = normalized.participants.find(
    (participant) => participant.participantId === input.participantId,
  )
    ? resultsForParticipant(
        normalized.participants.find(
          (participant) => participant.participantId === input.participantId,
        )!,
      )[0]
    : undefined;
  const incoming = normalized.participants
    .flatMap(resultsForParticipant)
    .filter((result) => result.defenderParticipantId === input.participantId);

  return { incoming, outgoing };
}

/** Returns canonical persisted attack results in stable presentation order. */
export function getCombatRoundParticipantAttackResults(input: {
  participant: CombatRoundParticipantState;
  roundNumber: number;
}): CombatRoundAttackRollResult[] {
  return Object.values(input.participant.attackResultsByOpportunity ?? {}).sort(
    (left, right) =>
      left.rolledAt.localeCompare(right.rolledAt) ||
      (left.attackIndex ?? Number.MAX_SAFE_INTEGER) -
        (right.attackIndex ?? Number.MAX_SAFE_INTEGER),
  );
}

export function getCombatRoundOutgoingAttackResultForParticipantPhase(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundAttackRollResult | undefined {
  return getCombatRoundAttackResultsForParticipantPhase(input).outgoing;
}

export function getCombatRoundIncomingAttackResultsForParticipantPhase(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundAttackRollResult[] {
  return getCombatRoundAttackResultsForParticipantPhase(input).incoming;
}

export function combatRoundParticipantWasAttackedInPhase(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): boolean {
  return getCombatRoundIncomingAttackResultsForParticipantPhase(input).length > 0;
}

export function getCombatRoundDisplayIncomingAttackResultForParticipantPhase(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundAttackRollResult | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const incoming = getCombatRoundIncomingAttackResultsForParticipantPhase({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });

  return (
    [...incoming].reverse().find((attackResult) => {
      const resolution = getCombatRoundPhaseResolutionResultForAttack({
        attackResult,
        state: normalized,
      });

      return resolution?.parryResolution.status === "pending";
    }) ?? incoming.at(-1)
  );
}

export function getCombatRoundPendingDefenseAttackResult(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundAttackRollResult | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  return [
    ...getCombatRoundIncomingAttackResultsForParticipantPhase({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    }),
  ]
    .reverse()
    .find((attackResult) => {
      const resolution = getCombatRoundPhaseResolutionResultForAttack({
        attackResult,
        state: normalized,
      });
      return !resolution?.defenseSnapshotId;
    });
}

export function getCombatRoundDisplayAttackResultForParticipantPhase(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundAttackRollResult | undefined {
  const results = getCombatRoundAttackResultsForParticipantPhase(input);

  return results.outgoing ?? results.incoming[0];
}

export function getCombatRoundResolutionPhaseForStep(
  step: CombatRoundStep,
): CombatRoundPhase | undefined {
  if (step === "review_phase_2_actions" || step === "phase_1_damage") {
    return "phase1";
  }

  if (step === "review_phase_2_damage" || step === "phase_2_damage") {
    return "phase2";
  }

  return undefined;
}

export function getCombatRoundParryReviewStepForPhase(phase: CombatRoundPhase): CombatRoundStep {
  return phase === "phase1" ? "review_phase_2_actions" : "review_phase_2_damage";
}

export function getCombatRoundDamageReviewStepForPhase(phase: CombatRoundPhase): CombatRoundStep {
  return phase === "phase1" ? "phase_1_damage" : "phase_2_damage";
}

export function getCombatRoundPhaseActionStepForPhase(phase: CombatRoundPhase): CombatRoundStep {
  return phase === "phase1" ? "phase_1_actions" : "phase_2_actions";
}

/**
 * A declaration may be committed before initiative, but the action phase is
 * not open until its canonical initiative commit advances currentStep.
 */
export function isCombatPhaseActionOpen(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  return (
    COMBAT_ROUND_STEPS.indexOf(normalized.currentStep) >=
    COMBAT_ROUND_STEPS.indexOf(getCombatRoundPhaseActionStepForPhase(input.phase))
  );
}

function getCombatRoundAttackPhaseForStep(step: CombatRoundStep): CombatRoundPhase | undefined {
  if (step === "phase_1_actions") {
    return "phase1";
  }

  if (step === "phase_2_actions") {
    return "phase2";
  }

  return undefined;
}

function getCombatRoundPhaseParryStepForPhase(phase: CombatRoundPhase): CombatRoundStep {
  return phase === "phase1" ? "review_phase_2_actions" : "review_phase_2_damage";
}

function buildCombatRoundAttackOpportunityId(input: {
  participantId: string;
  phase: CombatRoundPhase;
  roundNumber: number;
  slot: "attack_1" | "attack_2";
}): string {
  return `round:${input.roundNumber}:participant:${input.participantId}:${input.phase}:${input.slot}`;
}

export function buildCombatRoundDeclarationId(input: {
  participantId: string;
  roundNumber: number;
}): string {
  return `round:${input.roundNumber}:participant:${input.participantId}:declaration`;
}

export function buildCombatAttackWeaponSourceId(input: {
  itemId?: string;
  sourceKind?: "unarmed" | "weapon";
  weaponTemplateId?: string;
}): string | undefined {
  if (input.sourceKind === "weapon" && input.itemId) return `weapon:${input.itemId}`;
  if (input.sourceKind === "unarmed" && input.weaponTemplateId) {
    return `unarmed:${input.weaponTemplateId}`;
  }
  return undefined;
}

export function getCanonicalAttackOpportunityIdentity(input: {
  actionId?: string;
  attackerParticipantId: string;
  opportunity: CombatRoundAttackOpportunity;
  roundNumber: number;
}): CanonicalAttackOpportunityIdentity | undefined {
  const actionId = input.opportunity.actionId ?? input.actionId;
  const attackIndex =
    input.opportunity.attackIndex ??
    (input.opportunity.slot === "attack_1"
      ? 1
      : input.opportunity.slot === "attack_2"
        ? 2
        : undefined);
  const declarationId =
    input.opportunity.declarationId ??
    buildCombatRoundDeclarationId({
      participantId: input.attackerParticipantId,
      roundNumber: input.roundNumber,
    });
  const weaponInstanceId = input.opportunity.weaponInstanceId ?? input.opportunity.itemId;
  const weaponSourceId =
    input.opportunity.weaponSourceId ??
    buildCombatAttackWeaponSourceId({
      itemId: weaponInstanceId,
      sourceKind: input.opportunity.sourceKind,
      weaponTemplateId: input.opportunity.weaponTemplateId,
    });
  const weaponSourceSlot =
    input.opportunity.weaponSourceSlot ??
    (input.opportunity.sourceKind === "unarmed" ? "virtual" : undefined);

  if (
    !actionId ||
    !attackIndex ||
    !input.opportunity.attackModeId ||
    !input.opportunity.targetParticipantId ||
    !weaponSourceId ||
    !weaponSourceSlot ||
    !input.opportunity.weaponTemplateId
  ) {
    return undefined;
  }

  return {
    actionId,
    attackIndex,
    attackModeId: input.opportunity.attackModeId,
    attackerParticipantId: input.attackerParticipantId,
    declarationId,
    defenderParticipantId: input.opportunity.targetParticipantId,
    opportunityId: input.opportunity.id,
    phase: input.opportunity.phase,
    weaponInstanceId,
    weaponSourceId,
    weaponSourceSlot,
    weaponTemplateId: input.opportunity.weaponTemplateId,
  };
}

export function buildCombatRoundDeclaredAttackOpportunities(input: {
  actionId?: string;
  disarmPhase?: CombatRoundPhase;
  participantId: string;
  phaseContexts?: CombatRoundPhaseContexts;
  roundNumber: number;
  secondaryActionId?: string;
  sources?: Partial<
    Record<
      CombatRoundPhase,
      Pick<
        CombatRoundAttackOpportunity,
        | "attackModeId"
        | "attackType"
        | "itemId"
        | "missileProfile"
        | "sourceKind"
        | "weaponInstanceId"
        | "weaponSourceId"
        | "weaponSourceSlot"
        | "weaponTemplateId"
      >
    >
  >;
}): CombatRoundAttackOpportunity[] {
  return getCombatDeclarationAttackPhases({
    actionId: input.actionId,
    disarmPhase: input.disarmPhase,
    secondaryActionId: input.secondaryActionId,
  }).flatMap((phase) => {
    const targetParticipantId = input.phaseContexts?.[phase]?.targetParticipantId;
    const slot = phase === "phase1" ? "attack_1" : "attack_2";
    const source = input.sources?.[phase];
    const weaponInstanceId = source?.weaponInstanceId ?? source?.itemId;
    const weaponSourceId =
      source?.weaponSourceId ??
      buildCombatAttackWeaponSourceId({
        itemId: weaponInstanceId,
        sourceKind: source?.sourceKind,
        weaponTemplateId: source?.weaponTemplateId,
      });
    return [
      combatRoundAttackOpportunitySchema.parse({
        ...source,
        actionId: input.actionId,
        attackIndex: slot === "attack_1" ? 1 : 2,
        declarationId: buildCombatRoundDeclarationId({
          participantId: input.participantId,
          roundNumber: input.roundNumber,
        }),
        id: buildCombatRoundAttackOpportunityId({
          participantId: input.participantId,
          phase,
          roundNumber: input.roundNumber,
          slot,
        }),
        origin:
          input.actionId === "double_attack"
            ? "double_attack"
            : input.actionId === "parry_attack"
              ? "reactive_attack"
              : input.actionId === "feint_attack"
                ? "feint_attack"
                : input.actionId === "adjust_range_attack"
                  ? "adjust_range_attack"
                  : "declared",
        phase,
        slot,
        status: "committed",
        targetParticipantId,
        weaponInstanceId,
        weaponSourceId,
      }),
    ];
  });
}

/**
 * Feint has one opponent for both its opposed action and its phase-2 attack.
 * Keep the declaration field authoritative and derive every phase/opportunity
 * target from it when current state is recorded or materialized.
 */
export function synchronizeCombatRoundFeintDeclarationTarget(
  declaration: CombatRoundDeclaration,
): CombatRoundDeclaration {
  if (declaration.actionId !== "feint_attack" || !declaration.feint) return declaration;
  const targetParticipantId = declaration.feint.targetParticipantId;
  const synchronizeContext = (context?: ScenarioParticipantCombatContext) =>
    scenarioParticipantCombatContextSchema.parse({
      ...(context ?? {}),
      targetParticipantId,
    });
  return combatRoundDeclarationSchema.parse({
    ...declaration,
    attackOpportunities: declaration.attackOpportunities?.map((opportunity) =>
      opportunity.phase === "phase2" && opportunity.origin === "feint_attack"
        ? { ...opportunity, targetParticipantId }
        : opportunity,
    ),
    phaseContexts: {
      phase1: synchronizeContext(declaration.phaseContexts?.phase1),
      phase2: synchronizeContext(declaration.phaseContexts?.phase2),
    },
  });
}

/** Adjust Distance-Attack has one canonical opponent; its A2 target is derived. */
export function synchronizeCombatRoundAdjustDistanceDeclarationTarget(
  declaration: CombatRoundDeclaration,
): CombatRoundDeclaration {
  if (declaration.actionId !== "adjust_range_attack" || !declaration.adjustDistance) {
    return declaration;
  }
  const targetParticipantId = declaration.adjustDistance.targetParticipantId;
  const synchronizeContext = (context?: ScenarioParticipantCombatContext) =>
    scenarioParticipantCombatContextSchema.parse({ ...(context ?? {}), targetParticipantId });
  return combatRoundDeclarationSchema.parse({
    ...declaration,
    attackOpportunities: declaration.attackOpportunities?.map((opportunity) =>
      opportunity.phase === "phase2" ? { ...opportunity, targetParticipantId } : opportunity,
    ),
    phaseContexts: {
      phase1: synchronizeContext(declaration.phaseContexts?.phase1),
      phase2: synchronizeContext(declaration.phaseContexts?.phase2),
    },
  });
}

/** One canonical source for phase attack existence, ordering, and CE candidacy. */
export function getCombatRoundPhaseAttackCandidates(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): Array<CombatRoundAttackOpportunity & { participantId: string }> {
  const normalized = combatRoundStateSchema.parse(input.state);

  return normalized.participants.flatMap((participant) => {
    if (!participant.declaration) {
      return [];
    }
    if (
      !isCombatDeclarationActionAvailable({
        actionId: participant.declaration.actionId,
        kind: "primary",
      })
    ) {
      return [];
    }
    const explicit = (participant.declaration.attackOpportunities ?? []).filter(
      (opportunity) => opportunity.phase === input.phase && opportunity.status === "committed",
    );
    const opportunities =
      (participant.declaration.attackOpportunities?.length ?? 0) > 0
        ? explicit
        : buildCombatRoundDeclaredAttackOpportunities({
            actionId: participant.declaration.actionId,
            participantId: participant.participantId,
            phaseContexts: participant.declaration.phaseContexts,
            roundNumber: normalized.roundNumber,
            secondaryActionId: participant.declaration.secondaryActionId,
          });

    return opportunities
      .filter((opportunity) => opportunity.phase === input.phase)
      .map((opportunity) => ({ ...opportunity, participantId: participant.participantId }));
  });
}

export function combatRoundParticipantHasPhaseAttack(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  return getCombatRoundPhaseAttackCandidates({ phase: input.phase, state: normalized }).some(
    (candidate) => candidate.participantId === input.participantId,
  );
}

export function combatRoundParticipantHasExecutablePhaseAttack(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const candidate = getCombatRoundPhaseAttackCandidates({
    phase: input.phase,
    state: normalized,
  }).find((entry) => entry.participantId === input.participantId);
  const targetParticipantId = candidate?.targetParticipantId;
  const targetParticipant = getCombatRoundParticipantByTargetId({
    state: normalized,
    targetParticipantId,
  });
  const reactiveAttackIsOpen =
    participant?.declaration?.actionId !== "parry_attack" ||
    input.phase !== "phase2" ||
    getCombatRoundIncomingAttackResultsForParticipantPhase({
      participantId: input.participantId,
      phase: "phase1",
      state: normalized,
    }).some(
      (attackResult) =>
        targetParticipant && attackResult.attackerParticipantId === targetParticipant.participantId,
    );
  const pairAllowsOrdinaryMelee =
    !candidate ||
    candidate.weaponSourceSlot === "throwing" ||
    !targetParticipant ||
    isCombatPairEngaged({
      participantAId: input.participantId,
      participantBId: targetParticipant.participantId,
      state: normalized,
    });

  return Boolean(
    combatRoundParticipantHasPhaseAttack({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    }) &&
    reactiveAttackIsOpen &&
    pairAllowsOrdinaryMelee &&
    targetParticipant,
  );
}

export function getCombatRoundFeintProposal(input: {
  attackerParticipantId: string;
  state: CombatRoundState;
}): CombatFeintProposal | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  return normalized.feintProposals.find(
    (proposal) =>
      proposal.roundNumber === normalized.roundNumber &&
      proposal.attackerParticipantId === input.attackerParticipantId,
  );
}

export function getCombatRoundAdjustDistanceProposal(input: {
  attackerParticipantId: string;
  state: CombatRoundState;
}): CombatAdjustDistanceProposal | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  return normalized.adjustDistanceProposals.find(
    (proposal) =>
      proposal.roundNumber === normalized.roundNumber &&
      proposal.attackerParticipantId === input.attackerParticipantId,
  );
}

export function getCombatEngagementBetween(input: {
  participantAId: string;
  participantBId: string;
  state: CombatRoundState;
}): CombatEngagement | undefined {
  const pairKey = makeDistancePairKey(input.participantAId, input.participantBId);
  return combatRoundStateSchema
    .parse(input.state)
    .engagements.find((engagement) => engagement.pairKey === pairKey);
}

/** Missing legacy edges are ordinary engaged pairs until a canonical transition says otherwise. */
export function isCombatPairEngaged(input: {
  participantAId: string;
  participantBId: string;
  state: CombatRoundState;
}): boolean {
  return getCombatEngagementBetween(input)?.status !== "disengaged";
}

export function getCombatRoundBreakOffProposals(input: {
  escapeeParticipantId: string;
  state: CombatRoundState;
}): CombatBreakOffProposal[] {
  const normalized = combatRoundStateSchema.parse(input.state);
  return normalized.breakOffProposals.filter(
    (proposal) =>
      proposal.roundNumber === normalized.roundNumber &&
      proposal.escapeeParticipantId === input.escapeeParticipantId,
  );
}

export function combatRoundParticipantHasExecutablePhaseAction(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): boolean {
  if (input.phase === "phase1") {
    const breakOffProposals = getCombatRoundBreakOffProposals({
      escapeeParticipantId: input.participantId,
      state: input.state,
    });
    if (breakOffProposals.some((proposal) => proposal.status !== "committed")) return true;
    const adjustDistanceProposal = getCombatRoundAdjustDistanceProposal({
      attackerParticipantId: input.participantId,
      state: input.state,
    });
    if (adjustDistanceProposal && adjustDistanceProposal.status !== "committed") return true;
    const proposal = getCombatRoundFeintProposal({
      attackerParticipantId: input.participantId,
      state: input.state,
    });
    if (proposal && proposal.status !== "committed" && proposal.status !== "impossible") {
      return true;
    }

    const participant = input.state.participants.find(
      (entry) => entry.participantId === input.participantId,
    );
    if (participant?.declaration?.actionId === "observe_opponent") {
      return true;
    }
    if (
      getCombatRoundOpenPerformTaskForParticipant({
        participantId: input.participantId,
        state: input.state,
      })
    ) {
      return true;
    }
  }
  return combatRoundParticipantHasExecutablePhaseAttack(input);
}

/**
 * The one canonical Perform Task holding this participant's Phase 1 primary-action opportunity in
 * the current round. Declaration-materialized Perform Task declarations only: the legacy parallel
 * generic-action channel keeps its own route until A1b converges it.
 *
 * A participant can hold more than one live task, because a declaration mints a round-keyed task
 * whenever no live `taskId` carries forward. Selection is therefore explicit rather than by array
 * position: a task the GM has already started outranks one that has not been reviewed, and
 * otherwise the most recently declared task wins. Storage order decides only between two tasks
 * declared at the very same instant. A task that is not selected is left untouched and becomes
 * selectable again once the selected one reaches a terminal status.
 *
 * Perform Task is a normal primary action, so the opportunity belongs to the **participant**, not
 * to the individual task: once a consuming task command has closed this participant's Phase 1
 * resolution for the round, no task of theirs is executable again until the next round clears
 * `phaseResolutionStatuses`. Without that gate a second, never-progressed task would still look
 * open on its own progress alone and would grant a second primary action in one round.
 */
export function getCombatRoundOpenPerformTaskForParticipant(input: {
  participantId: string;
  state: CombatRoundState;
}): CombatGenericAction | undefined {
  if (input.state.phaseResolutionStatuses[input.participantId]?.phase1?.substep === "done") {
    return undefined;
  }
  const open = input.state.genericActions.filter(
    (action) =>
      action.declarationKind === "perform_task" &&
      action.ownerParticipantId === input.participantId &&
      isCombatGenericActionOpportunityOpen({
        action,
        roundNumber: input.state.roundNumber,
      }),
  );
  if (open.length <= 1) return open[0];
  const startedRank = (action: CombatGenericAction): number =>
    action.status === "declared" ? 0 : 1;
  return open.reduce((selected, candidate) => {
    if (startedRank(candidate) !== startedRank(selected)) {
      return startedRank(candidate) > startedRank(selected) ? candidate : selected;
    }
    if (candidate.createdAt !== selected.createdAt) {
      return candidate.createdAt > selected.createdAt ? candidate : selected;
    }
    return candidate;
  });
}

export function getNextCombatRoundPhaseActionParticipantId(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): string | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const currentGroup = getCombatRoundCurrentInitiativeExecutionGroup({
    phase: input.phase,
    state: normalized,
  });
  const order =
    currentGroup?.participantIds ??
    getCombatRoundPhaseResolutionOrder({
      phase: input.phase,
      state: normalized,
    });

  return order.find((participantId) => {
    const status = getEffectiveCombatRoundPhaseResolutionStatus({
      participantId,
      phase: input.phase,
      state: normalized,
    });
    const existingAttackResult = getCombatRoundOutgoingAttackResultForParticipantPhase({
      participantId,
      phase: input.phase,
      state: normalized,
    });

    return (
      status.substep !== "done" &&
      existingAttackResult === undefined &&
      combatRoundParticipantHasExecutablePhaseAction({
        participantId,
        phase: input.phase,
        state: normalized,
      })
    );
  });
}

export function isCombatRoundPhaseResolutionComplete(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);

  return (
    isCombatPhaseActionOpen({ phase: input.phase, state: normalized }) &&
    normalized.phaseResolutionCursor?.phase !== input.phase &&
    getNextCombatRoundPhaseActionParticipantId({
      phase: input.phase,
      state: normalized,
    }) === undefined
  );
}

function combatRoundCommandCancelsPhaseAction(input: {
  command: CombatRoundCommand;
  participantId: string;
  phase: CombatRoundPhase;
}): boolean {
  if (input.command.type === "commit_phase_initiative_resolution") {
    const appliedChoices = Array.isArray(input.command.facts.appliedChoices)
      ? input.command.facts.appliedChoices
      : [];

    return appliedChoices.some(
      (choice) =>
        choice &&
        typeof choice === "object" &&
        "participantId" in choice &&
        "choice" in choice &&
        choice.participantId === input.participantId &&
        input.command.phase === input.phase &&
        (choice.choice === "back_out" || choice.phaseAttackCancelled === true),
    );
  }

  if (input.command.type !== "commit_phase_damage") {
    return false;
  }

  const cancelledActions = input.command.facts.cancelledActions;

  return (
    Array.isArray(cancelledActions) &&
    cancelledActions.some(
      (entry) =>
        typeof entry === "object" &&
        entry !== null &&
        "participantId" in entry &&
        "phase" in entry &&
        entry.participantId === input.participantId &&
        entry.phase === input.phase,
    )
  );
}

function combatRoundParticipantPhaseActionHasCompletionEvidence(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);

  if (participant?.stepStatuses[actionStep] === "skipped") {
    return true;
  }

  if (
    getCombatRoundOutgoingAttackResultForParticipantPhase({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    })
  ) {
    return true;
  }

  if (
    participant?.combatExperience?.roundNumber === normalized.roundNumber &&
    getCombatExperiencePhaseForTrigger(participant.combatExperience.trigger) === input.phase &&
    phaseCombatExperienceCancelsAttack(participant.combatExperience)
  ) {
    return true;
  }

  return normalized.commands.some(
    (command) =>
      command.roundNumber === normalized.roundNumber &&
      command.participantId === input.participantId &&
      ((command.phase === input.phase &&
        (command.type === "roll_attack" ||
          command.type === "skip_phase_action" ||
          command.type === "advance_combat_task" ||
          command.type === "resolve_combat_task" ||
          command.type === "interrupt_combat_task" ||
          command.type === "cancel_combat_task" ||
          command.type === "back_out_phase_attack")) ||
        combatRoundCommandCancelsPhaseAction({
          command,
          participantId: input.participantId,
          phase: input.phase,
        })),
  );
}

function getEffectiveCombatRoundPhaseResolutionStatus(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundPhaseResolutionParticipantStatus {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);
  const status = getCombatRoundPhaseResolutionStatus({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });

  if (
    status.substep !== "done" ||
    !combatRoundParticipantHasExecutablePhaseAttack({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    }) ||
    (participant?.stepStatuses[actionStep] ?? "pending") === "pending" ||
    combatRoundParticipantPhaseActionHasCompletionEvidence({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    })
  ) {
    return status;
  }

  return {
    substep: "pending",
    updatedAt: status.updatedAt,
  };
}

function clearUnsupportedCombatRoundPhaseActionProgress(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);
  let changed = false;
  const phaseResolutionStatuses: CombatRoundPhaseResolutionStatuses = {
    ...normalized.phaseResolutionStatuses,
  };
  const participants = normalized.participants.map((participant) => {
    const executable = combatRoundParticipantHasExecutablePhaseAction({
      participantId: participant.participantId,
      phase: input.phase,
      state: normalized,
    });
    const hasCompletionEvidence = combatRoundParticipantPhaseActionHasCompletionEvidence({
      participantId: participant.participantId,
      phase: input.phase,
      state: normalized,
    });
    const phaseStatus = phaseResolutionStatuses[participant.participantId]?.[input.phase];

    if (
      !executable ||
      hasCompletionEvidence ||
      phaseStatus?.substep !== "done" ||
      participant.stepStatuses[actionStep] === "pending"
    ) {
      return participant;
    }

    changed = true;
    phaseResolutionStatuses[participant.participantId] = {
      ...phaseResolutionStatuses[participant.participantId],
      [input.phase]: undefined,
    };

    return {
      ...participant,
      stepStatuses: {
        ...participant.stepStatuses,
        [actionStep]: "pending",
      },
    };
  });

  return changed
    ? combatRoundStateSchema.parse({
        ...normalized,
        participants,
        phaseResolutionStatuses,
      })
    : normalized;
}

function getCombatRoundInitialPhaseResolutionSubstep(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundPhaseResolutionSubstep {
  if (input.phase === "phase1") {
    if (
      getCombatRoundBreakOffProposals({
        escapeeParticipantId: input.participantId,
        state: input.state,
      }).some((proposal) => proposal.status !== "committed")
    ) {
      return "break_off";
    }
    const adjustDistanceProposal = getCombatRoundAdjustDistanceProposal({
      attackerParticipantId: input.participantId,
      state: input.state,
    });
    if (adjustDistanceProposal && adjustDistanceProposal.status !== "committed") {
      return "adjust_distance";
    }
    const proposal = getCombatRoundFeintProposal({
      attackerParticipantId: input.participantId,
      state: input.state,
    });
    if (proposal && proposal.status !== "committed" && proposal.status !== "impossible") {
      return "feint";
    }
  }
  if (
    input.phase === "phase1" &&
    !combatRoundParticipantHasExecutablePhaseAttack(input) &&
    getCombatRoundOpenPerformTaskForParticipant({
      participantId: input.participantId,
      state: input.state,
    })
  ) {
    return "perform_task";
  }
  return combatRoundParticipantHasExecutablePhaseAction(input) ? "attack" : "done";
}

function getCombatRoundPostAttackResolutionSubstep(
  _attackResult: CombatRoundAttackRollResult,
): CombatRoundPhaseResolutionSubstep {
  return "defense";
}

export function getCombatRoundPhaseResolutionStatus(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundPhaseResolutionParticipantStatus {
  const normalized = combatRoundStateSchema.parse(input.state);

  return (
    normalized.phaseResolutionStatuses[input.participantId]?.[input.phase] ?? {
      substep: "pending",
    }
  );
}

export function getCombatRoundParticipantPhaseStepStatus(input: {
  participantId: string;
  state: CombatRoundState;
  step: CombatRoundStep;
}): CombatRoundStepStatus {
  const normalized = combatRoundStateSchema.parse(input.state);
  const phase =
    getCombatRoundAttackPhaseForStep(input.step) ??
    getCombatRoundResolutionPhaseForStep(input.step);
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const storedStatus = participant?.stepStatuses[input.step] ?? "pending";

  if (!phase) {
    return storedStatus;
  }

  const actionStep = getCombatRoundPhaseActionStepForPhase(phase);
  const parryStep = getCombatRoundPhaseParryStepForPhase(phase);
  const damageStep = getCombatRoundDamageReviewStepForPhase(phase);
  const phaseStatus = getCombatRoundPhaseResolutionStatus({
    participantId: input.participantId,
    phase,
    state: normalized,
  });

  if (input.step === actionStep) {
    const breakOffProposals =
      phase === "phase1"
        ? getCombatRoundBreakOffProposals({
            escapeeParticipantId: input.participantId,
            state: normalized,
          })
        : [];
    if (breakOffProposals.length > 0) {
      return breakOffProposals.every((proposal) => proposal.status === "committed")
        ? "complete"
        : "ready";
    }
    const feintProposal =
      phase === "phase1"
        ? getCombatRoundFeintProposal({
            attackerParticipantId: input.participantId,
            state: normalized,
          })
        : undefined;
    if (feintProposal) {
      if (storedStatus === "skipped") {
        return "skipped";
      }
      if (feintProposal.status === "committed") {
        return "complete";
      }
      if (feintProposal.status === "impossible") {
        return "skipped";
      }
      return "ready";
    }
    const outgoingAttackResult = getCombatRoundOutgoingAttackResultForParticipantPhase({
      participantId: input.participantId,
      phase,
      state: normalized,
    });
    if (outgoingAttackResult) {
      return "gmEdited";
    }
    const hasPhaseAttack = combatRoundParticipantHasPhaseAttack({
      participantId: input.participantId,
      phase,
      state: normalized,
    });

    if (!hasPhaseAttack) {
      if (phase === "phase1" && participant?.declaration?.actionId === "observe_opponent") {
        if (storedStatus === "skipped" || phaseStatus.substep === "done") {
          return "skipped";
        }
        return normalized.phaseResolutionCursor?.participantId === input.participantId &&
          normalized.phaseResolutionCursor.phase === phase
          ? "ready"
          : storedStatus;
      }
      const currentStepIndex = COMBAT_ROUND_STEPS.indexOf(normalized.currentStep);
      const actionStepIndex = COMBAT_ROUND_STEPS.indexOf(actionStep);
      const actionSlotReached =
        currentStepIndex >= 0 && actionStepIndex >= 0 && currentStepIndex >= actionStepIndex;

      return phaseStatus.substep === "done" || actionSlotReached ? "skipped" : storedStatus;
    }

    if (
      !outgoingAttackResult &&
      storedStatus !== "pending" &&
      combatRoundParticipantHasExecutablePhaseAttack({
        participantId: input.participantId,
        phase,
        state: normalized,
      }) &&
      !combatRoundParticipantPhaseActionHasCompletionEvidence({
        participantId: input.participantId,
        phase,
        state: normalized,
      })
    ) {
      return "pending";
    }

    return outgoingAttackResult ? "gmEdited" : storedStatus;
  }

  const incomingAttackResult = getCombatRoundDisplayIncomingAttackResultForParticipantPhase({
    participantId: input.participantId,
    phase,
    state: normalized,
  });

  if (!incomingAttackResult) {
    return storedStatus;
  }

  const resolution =
    getCombatRoundPhaseResolutionResultForAttack({
      attackResult: incomingAttackResult,
      state: normalized,
    }) ??
    buildCombatRoundPhaseResolutionResult({
      attackResult: incomingAttackResult,
      roundNumber: normalized.roundNumber,
      state: normalized,
      updatedAt: incomingAttackResult.rolledAt,
    });

  if (input.step === parryStep) {
    if (resolution.parryResolution.status === "not_applicable") {
      return "skipped";
    }

    return resolution.parryResolution.status === "resolved" ? "complete" : "pending";
  }

  if (input.step === damageStep) {
    if (!incomingAttackResult.hit || resolution.damageRoll.status === "not_required") {
      return "skipped";
    }

    if (resolution.damageProposal.status === "committed") {
      return "complete";
    }

    if (resolution.damageResult) {
      return "ready";
    }

    if (
      storedStatus === "submitted" ||
      storedStatus === "gmEdited" ||
      storedStatus === "complete"
    ) {
      return storedStatus;
    }

    return "pending";
  }

  return storedStatus;
}

function setCombatRoundPhaseResolutionStatus(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  status: CombatRoundPhaseResolutionParticipantStatus;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);

  return {
    ...normalized,
    phaseResolutionStatuses: {
      ...normalized.phaseResolutionStatuses,
      [input.participantId]: {
        ...normalized.phaseResolutionStatuses[input.participantId],
        [input.phase]: combatRoundPhaseResolutionParticipantStatusSchema.parse(input.status),
      },
    },
  };
}

export function getCombatRoundPhaseResolutionOrder(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): string[] {
  const ordered = sortCombatRoundParticipantsByInitiative(input);
  if (input.phase !== "phase1") return ordered.map((participant) => participant.participantId);
  // Source timing: Break Off resolves first in the round, before ordinary melee.
  return [...ordered]
    .sort((left, right) => {
      const leftBreaksOff = left.declaration?.actionId === "break_off_engagement" ? 0 : 1;
      const rightBreaksOff = right.declaration?.actionId === "break_off_engagement" ? 0 : 1;
      return leftBreaksOff - rightBreaksOff;
    })
    .map((participant) => participant.participantId);
}

function moveCombatRoundToPhaseInitiativeResolution(input: {
  participantId?: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const initiativeStep = getCombatRoundPhaseInitiativeStepForPhase(input.phase);
  const participantId =
    input.participantId ??
    getFirstUnresolvedCombatRoundPhaseInitiativeChoiceParticipantId({
      phase: input.phase,
      state: normalized,
    }) ??
    normalized.currentCursor?.participantId ??
    normalized.selectedParticipantId ??
    normalized.participants[0]?.participantId;

  return combatRoundStateSchema.parse({
    ...normalized,
    currentCursor: {
      participantId,
      roundNumber: normalized.roundNumber,
      step: getCombatRoundPhaseInitiativeCursorStepForPhase(input.phase),
    },
    currentStep: initiativeStep,
    phaseResolutionCursor: undefined,
    selectedParticipantId: participantId,
    selectedStep: initiativeStep,
  });
}

function moveCombatRoundAfterCompletedPhaseInitiative(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const initiativeStep = getCombatRoundPhaseInitiativeStepForPhase(input.phase);
  const baseState = combatRoundStateSchema.parse({
    ...normalized,
    currentCursor: getDefaultCombatRoundCursor({
      participantId: normalized.currentCursor?.participantId ?? normalized.selectedParticipantId,
      roundNumber: normalized.roundNumber,
      step: initiativeStep,
    }),
    currentStep: initiativeStep,
    phaseResolutionCursor: undefined,
    selectedStep: initiativeStep,
  });
  const threatenedParticipantId = getCombatRoundPhaseInitiativeChoiceStatuses({
    phase: input.phase,
    state: baseState,
    visibility: input.visibility,
  })[0]?.participantId;

  return moveCombatRoundToPhaseInitiativeResolution({
    participantId: threatenedParticipantId,
    phase: input.phase,
    state: baseState,
  });
}

function phaseCombatExperienceCancelsAttack(result: CombatRoundCombatExperienceResult): boolean {
  return (
    getCombatExperiencePhaseForTrigger(result.trigger) !== undefined &&
    result.noRollRequired !== true &&
    result.effectiveTableTotal !== undefined &&
    result.effectiveTableTotal <= 5
  );
}

function applyPhaseCombatExperienceAttackCancellation(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  updatedAt: string;
}): CombatRoundState {
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);
  const withDoneStatus = setCombatRoundPhaseResolutionStatus({
    participantId: input.participantId,
    phase: input.phase,
    state: input.state,
    status: {
      substep: "done",
      updatedAt: input.updatedAt,
    },
  });

  return setCombatRoundParticipantStepStatus({
    participantId: input.participantId,
    state: withDoneStatus,
    status: "skipped",
    step: actionStep,
  });
}

function moveCombatRoundAfterCombatExperienceResult(input: {
  createdAt: string;
  participantId: string;
  result: CombatRoundCombatExperienceResult;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): CombatRoundState {
  const withParticipantResult = combatRoundStateSchema.parse({
    ...input.state,
    participants: input.state.participants.map((entry) =>
      entry.participantId === input.participantId
        ? {
            ...entry,
            combatExperience: input.result,
          }
        : entry,
    ),
  });
  const phase = getCombatExperiencePhaseForTrigger(input.result.trigger);

  if (!phase) {
    return combatRoundStateSchema.parse({
      ...withParticipantResult,
      currentCursor: getDefaultCombatRoundCursor({
        participantId: input.participantId,
        roundNumber: withParticipantResult.roundNumber,
        step: "select_actions",
      }),
      currentStep: "select_actions",
      selectedParticipantId: input.participantId,
      selectedStep: "select_actions",
    });
  }

  const withPhaseOutcome = phaseCombatExperienceCancelsAttack(input.result)
    ? applyPhaseCombatExperienceAttackCancellation({
        participantId: input.participantId,
        phase,
        state: withParticipantResult,
        updatedAt: input.createdAt,
      })
    : withParticipantResult;
  const nextParticipantId = getFirstCombatRoundPhaseCombatExperienceRequiredParticipantId({
    phase,
    state: withPhaseOutcome,
    visibility: input.visibility,
  });

  if (nextParticipantId) {
    return combatRoundStateSchema.parse({
      ...withPhaseOutcome,
      currentCursor: getDefaultCombatRoundCursor({
        participantId: nextParticipantId,
        roundNumber: withPhaseOutcome.roundNumber,
        step: getCombatRoundPhaseActionStepForPhase(phase),
      }),
      currentStep: getCombatRoundPhaseActionStepForPhase(phase),
      phaseResolutionCursor: undefined,
      selectedParticipantId: nextParticipantId,
      selectedStep: getCombatRoundPhaseActionStepForPhase(phase),
    });
  }

  return initializeCombatRoundPhaseResolutionCursor({
    phase,
    state: withPhaseOutcome,
    updatedAt: input.createdAt,
  });
}

export function initializeCombatRoundPhaseResolutionCursor(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
  updatedAt?: string;
}): CombatRoundState {
  const normalized = clearUnsupportedCombatRoundPhaseActionProgress({
    phase: input.phase,
    state: input.state,
  });
  const participantId = getNextCombatRoundPhaseActionParticipantId({
    phase: input.phase,
    state: normalized,
  });

  if (!participantId) {
    return moveCombatRoundToPhaseCompletion({
      phase: input.phase,
      state: normalized,
    });
  }

  const withOpenedBreakOff = openCombatRoundBreakOffForActionTurn({
    participantId,
    state: normalized,
  });
  const withOpenedFeint = openCombatRoundFeintRollsForActionTurn({
    participantId,
    state: withOpenedBreakOff,
  });
  const withOpenedAction = openCombatRoundAdjustDistanceForActionTurn({
    participantId,
    state: withOpenedFeint,
  });
  const existingStatus = getEffectiveCombatRoundPhaseResolutionStatus({
    participantId,
    phase: input.phase,
    state: withOpenedAction,
  });
  const nextSubstep =
    existingStatus.substep === "pending"
      ? getCombatRoundInitialPhaseResolutionSubstep({
          participantId,
          phase: input.phase,
          state: withOpenedAction,
        })
      : existingStatus.substep;
  const withStatus = setCombatRoundPhaseResolutionStatus({
    participantId,
    phase: input.phase,
    state: withOpenedAction,
    status: {
      substep: nextSubstep,
      updatedAt: input.updatedAt ?? existingStatus.updatedAt,
    },
  });
  const phaseResolutionCursor = {
    participantId,
    phase: input.phase,
    substep: nextSubstep,
  };
  const currentCursor = getCombatRoundCursorForPhaseResolutionCursor({
    cursor: phaseResolutionCursor,
    state: withStatus,
  });
  const selectedStep = getCombatRoundStepForCursorStep(currentCursor.step);

  return {
    ...withStatus,
    currentCursor,
    currentStep: selectedStep,
    phaseResolutionCursor,
    selectedParticipantId: participantId,
    selectedStep,
  };
}

function moveCombatRoundPhaseResolutionCursorToNextParticipant(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
  updatedAt: string;
}): CombatRoundState {
  const normalized = clearUnsupportedCombatRoundPhaseActionProgress({
    phase: input.phase,
    state: input.state,
  });
  const participantId = getNextCombatRoundPhaseActionParticipantId({
    phase: input.phase,
    state: normalized,
  });

  if (!participantId) {
    return moveCombatRoundToPhaseCompletion({
      phase: input.phase,
      state: normalized,
    });
  }

  const withOpenedBreakOff = openCombatRoundBreakOffForActionTurn({
    participantId,
    state: normalized,
  });
  const withOpenedFeint = openCombatRoundFeintRollsForActionTurn({
    participantId,
    state: withOpenedBreakOff,
  });
  const withOpenedAction = openCombatRoundAdjustDistanceForActionTurn({
    participantId,
    state: withOpenedFeint,
  });
  const nextSubstep = getCombatRoundInitialPhaseResolutionSubstep({
    participantId,
    phase: input.phase,
    state: withOpenedAction,
  });
  const withStatus = setCombatRoundPhaseResolutionStatus({
    participantId,
    phase: input.phase,
    state: withOpenedAction,
    status: {
      substep: nextSubstep,
      updatedAt: input.updatedAt,
    },
  });
  const phaseResolutionCursor = {
    participantId,
    phase: input.phase,
    substep: nextSubstep,
  };
  const currentCursor = getCombatRoundCursorForPhaseResolutionCursor({
    cursor: phaseResolutionCursor,
    state: withStatus,
  });
  const selectedStep = getCombatRoundStepForCursorStep(currentCursor.step);

  return {
    ...withStatus,
    currentCursor,
    currentStep: selectedStep,
    phaseResolutionCursor,
    selectedParticipantId: participantId,
    selectedStep,
  };
}

export function recordCombatRoundPhaseResolutionAttackDone(input: {
  attackResult: CombatRoundAttackRollResult;
  state: CombatRoundState;
  updatedAt: string;
}): CombatRoundState {
  const nextSubstep = getCombatRoundPostAttackResolutionSubstep(input.attackResult);
  const withStatus = setCombatRoundPhaseResolutionStatus({
    participantId: input.attackResult.attackerParticipantId,
    phase: input.attackResult.phase,
    state: input.state,
    status: {
      substep: nextSubstep,
      updatedAt: input.updatedAt,
    },
  });
  const cursor = combatRoundCursorSchema.parse({
    participantId: input.attackResult.defenderParticipantId,
    roundNumber: withStatus.roundNumber,
    step: getCombatRoundCursorStepForPhaseResolutionSubstep({
      phase: input.attackResult.phase,
      substep: nextSubstep,
    }),
  });

  return {
    ...withStatus,
    currentCursor: cursor,
    currentStep: getCombatRoundStepForCursorStep(cursor.step),
    phaseResolutionCursor: {
      participantId: input.attackResult.defenderParticipantId,
      phase: input.attackResult.phase,
      substep: nextSubstep,
    },
    selectedParticipantId: input.attackResult.defenderParticipantId,
    selectedStep: getCombatRoundParryReviewStepForPhase(input.attackResult.phase),
  };
}

export function advanceCombatRoundPhaseResolutionSubstepForParticipant(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  updatedAt: string;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const currentStatus = getCombatRoundPhaseResolutionStatus({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });
  const currentSubstep =
    currentStatus.substep === "pending"
      ? getCombatRoundInitialPhaseResolutionSubstep(input)
      : currentStatus.substep;

  if (currentSubstep === "done") {
    return normalized;
  }

  if (currentSubstep === "defense") {
    throw new RangeError("Defense review must be committed for the exact incoming attack first.");
  }

  if (currentSubstep === "effects") {
    return completeCombatRoundPhaseResolutionForParticipant({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
      submittedBy: "gm",
      updatedAt: input.updatedAt,
    });
  }

  const nextSubstep: CombatRoundPhaseResolutionSubstep =
    currentSubstep === "attack" ? "parry" : currentSubstep === "parry" ? "damage" : "effects";
  const withStatus = setCombatRoundPhaseResolutionStatus({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
    status: {
      substep: nextSubstep,
      updatedAt: input.updatedAt,
    },
  });

  return {
    ...withStatus,
    phaseResolutionCursor: {
      participantId: input.participantId,
      phase: input.phase,
      substep: nextSubstep,
    },
    selectedParticipantId: input.participantId,
    selectedStep:
      nextSubstep === "parry"
        ? getCombatRoundParryReviewStepForPhase(input.phase)
        : getCombatRoundDamageReviewStepForPhase(input.phase),
  };
}

export function completeCombatRoundPhaseResolutionForParticipant(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  submittedBy: "gm" | "player";
  updatedAt: string;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  if (
    getCombatRoundPhaseResolutionStatus({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    }).substep === "defense"
  ) {
    throw new RangeError("Defense review must be committed for the exact incoming attack first.");
  }
  const withStatus = setCombatRoundPhaseResolutionStatus({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
    status: {
      substep: "done",
      updatedAt: input.updatedAt,
    },
  });
  const hasPhaseAttack = combatRoundParticipantHasPhaseAttack({
    participantId: input.participantId,
    phase: input.phase,
    state: withStatus,
  });
  const attackResult = getCombatRoundOutgoingAttackResultForParticipantPhase({
    participantId: input.participantId,
    phase: input.phase,
    state: withStatus,
  });
  const withActionStepStatus = hasPhaseAttack
    ? withStatus
    : setCombatRoundParticipantStepStatus({
        participantId: input.participantId,
        state: withStatus,
        status: "skipped",
        step: getCombatRoundPhaseActionStepForPhase(input.phase),
      });
  const reviewParticipantId =
    hasPhaseAttack && attackResult?.hit ? attackResult.defenderParticipantId : input.participantId;
  const reviewStep =
    hasPhaseAttack && attackResult?.hit
      ? getCombatRoundDamageReviewStepForPhase(input.phase)
      : getCombatRoundParryReviewStepForPhase(input.phase);
  const withStepStatus =
    hasPhaseAttack && !attackResult?.hit
      ? withActionStepStatus
      : setCombatRoundParticipantStepStatus({
          participantId: reviewParticipantId,
          state: withActionStepStatus,
          status: input.submittedBy === "gm" ? "gmEdited" : "submitted",
          step: reviewStep,
        });

  return moveCombatRoundPhaseResolutionCursorToNextParticipant({
    phase: input.phase,
    state: withStepStatus,
    updatedAt: input.updatedAt,
  });
}

function getCombatRoundPhaseActionSkipCommandAfterCursor(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundCursor {
  return getCombatRoundPhaseActionOrCompletionCursor(input);
}

function recordCombatRoundPhaseActionSkipCommand(input: {
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const beforeCursor = combatRoundCursorSchema.parse({
    participantId: input.participantId,
    roundNumber: normalized.roundNumber,
    step: getCombatRoundAttackCursorStepForPhase(input.phase),
  });
  const afterCursor = getCombatRoundPhaseActionSkipCommandAfterCursor({
    phase: input.phase,
    state: normalized,
  });
  const commandType = "skip_phase_action" satisfies CombatRoundCommandType;
  const command = combatRoundCommandSchema.parse({
    afterCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      phase: input.phase,
      status: "skipped",
      ...(afterCursor.participantId
        ? {
            nextStepOpened: {
              participantId: afterCursor.participantId,
              step: afterCursor.step,
            },
          }
        : {}),
    },
    id:
      input.command.commandId ??
      buildCombatRoundCommandId({
        createdAt: input.command.createdAt,
        participantId: input.participantId,
        state: normalized,
        type: commandType,
      }),
    participantId: input.participantId,
    phase: input.phase,
    roundNumber: normalized.roundNumber,
    step: beforeCursor.step,
    type: commandType,
  });
  const selectedStep = getCombatRoundStepForCursorStep(command.afterCursor.step);

  return {
    ...normalized,
    commands: [...normalized.commands, command],
    currentCursor: command.afterCursor,
    currentStep: selectedStep,
    selectedParticipantId: command.afterCursor.participantId ?? normalized.selectedParticipantId,
    selectedStep,
  };
}

export function skipCombatRoundCurrentPhaseAction(input: {
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  participantId: string;
  phase: CombatRoundPhase;
  reason?: string;
  state: CombatRoundState;
  submittedBy: "gm" | "player";
  updatedAt: string;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);
  const beforeCursor = combatRoundCursorSchema.parse({
    participantId: input.participantId,
    roundNumber: normalized.roundNumber,
    step: getCombatRoundAttackCursorStepForPhase(input.phase),
  });

  if (
    !combatRoundParticipantHasExecutablePhaseAction({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    })
  ) {
    throw new RangeError("Current phase action cannot be skipped because it is not available.");
  }

  if (
    getCombatRoundOutgoingAttackResultForParticipantPhase({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    })
  ) {
    throw new RangeError("Current phase action cannot be skipped after the attack is rolled.");
  }

  const withDoneStatus = setCombatRoundPhaseResolutionStatus({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
    status: {
      substep: "done",
      updatedAt: input.updatedAt,
    },
  });
  const withSkippedAction = setCombatRoundParticipantStepStatus({
    participantId: input.participantId,
    state: withDoneStatus,
    status: "skipped",
    step: actionStep,
  });
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const canonicalOpportunity = getCombatRoundPhaseAttackCandidates({
    phase: input.phase,
    state: normalized,
  }).find((opportunity) => opportunity.participantId === input.participantId);
  const actualPreviousAttackPhaseDefensivePenalties =
    participant?.declaration?.attackPhaseDefensivePenalties;
  const previousAttackPhaseDefensivePenalties =
    actualPreviousAttackPhaseDefensivePenalties ??
    (canonicalOpportunity
      ? resolveCombatAttackPhaseDefensivePenalties({
          commitment: "committed",
          opportunities: [canonicalOpportunity],
          participantId: input.participantId,
          roundNumber: normalized.roundNumber,
        })
      : []);
  const skippedAttackPhaseDefensivePenalty = canonicalOpportunity
    ? resolveCombatAttackPhaseDefensivePenalty({
        commitment: "committed",
        executionState: "skipped",
        opportunity: canonicalOpportunity,
        participantId: input.participantId,
        reason: "skipped_after_commitment",
        roundNumber: normalized.roundNumber,
      })
    : undefined;
  const nextAttackPhaseDefensivePenalties = skippedAttackPhaseDefensivePenalty
    ? replaceCombatAttackPhaseDefensivePenalty({
        existing: previousAttackPhaseDefensivePenalties,
        next: skippedAttackPhaseDefensivePenalty,
      })
    : previousAttackPhaseDefensivePenalties;
  const withCanonicalSkip = skippedAttackPhaseDefensivePenalty
    ? combatRoundStateSchema.parse({
        ...withSkippedAction,
        participants: withSkippedAction.participants.map((entry) =>
          entry.participantId === input.participantId && entry.declaration
            ? {
                ...entry,
                declaration: {
                  ...entry.declaration,
                  attackPhaseDefensivePenalties: nextAttackPhaseDefensivePenalties,
                  combatContext: applyAttackPhaseDefensivePenaltyModifiers({
                    combatContext: scenarioParticipantCombatContextSchema.parse(
                      entry.declaration.combatContext ?? {},
                    ),
                    penalties: nextAttackPhaseDefensivePenalties,
                  }),
                  phaseContexts: {
                    ...entry.declaration.phaseContexts,
                    [input.phase]: applyAttackPhaseDefensivePenaltyModifiers({
                      combatContext: scenarioParticipantCombatContextSchema.parse(
                        entry.declaration.phaseContexts?.[input.phase] ?? {},
                      ),
                      penalties: nextAttackPhaseDefensivePenalties,
                    }),
                  },
                },
              }
            : entry,
        ),
      })
    : withSkippedAction;
  const commandType = "skip_phase_action" satisfies CombatRoundCommandType;
  const commandId =
    input.command.commandId ??
    buildCombatRoundCommandId({
      createdAt: input.command.createdAt,
      participantId: input.participantId,
      state: normalized,
      type: commandType,
    });
  const commandShell = combatRoundCommandSchema.parse({
    afterCursor: beforeCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      attackPhaseDefensivePenalty: skippedAttackPhaseDefensivePenalty,
      phase: input.phase,
      previousAttackPhaseDefensivePenalties: actualPreviousAttackPhaseDefensivePenalties ?? null,
      previousAttackPhaseDefensiveCombatModifiers:
        participant?.declaration?.combatContext?.modifierBuckets.situationDb.filter(
          isAttackPhaseDefensivePenaltyModifier,
        ) ?? [],
      previousAttackPhaseDefensivePhaseModifiers:
        participant?.declaration?.phaseContexts?.[input.phase]?.modifierBuckets.situationDb.filter(
          isAttackPhaseDefensivePenaltyModifier,
        ) ?? [],
      reason: input.reason?.trim() || "GM skipped action",
      status: "skipped",
    },
    id: commandId,
    participantId: input.participantId,
    phase: input.phase,
    roundNumber: normalized.roundNumber,
    step: beforeCursor.step,
    type: commandType,
  });
  const stateForAfterCursor = combatRoundStateSchema.parse({
    ...withCanonicalSkip,
    commands: [
      ...withCanonicalSkip.commands.filter((command) => command.id !== commandId),
      commandShell,
    ],
  });
  const afterCursor = getCombatRoundPhaseActionSkipCommandAfterCursor({
    phase: input.phase,
    state: stateForAfterCursor,
  });
  const command = combatRoundCommandSchema.parse({
    ...commandShell,
    afterCursor,
    facts: {
      ...commandShell.facts,
      ...(afterCursor.participantId
        ? {
            nextStepOpened: {
              participantId: afterCursor.participantId,
              step: afterCursor.step,
            },
          }
        : {}),
    },
  });
  const selectedStep = getCombatRoundStepForCursorStep(command.afterCursor.step);

  return combatRoundStateSchema.parse({
    ...withCanonicalSkip,
    commands: [
      ...withCanonicalSkip.commands.filter((existingCommand) => existingCommand.id !== commandId),
      command,
    ],
    currentCursor: command.afterCursor,
    currentStep: selectedStep,
    phaseResolutionCursor:
      afterCursor.participantId && afterCursor.step === beforeCursor.step
        ? {
            participantId: afterCursor.participantId,
            phase: input.phase,
            substep: "attack",
          }
        : undefined,
    selectedParticipantId: command.afterCursor.participantId ?? input.participantId,
    selectedStep,
  });
}

function submitCombatRoundPhaseInitiativeChoiceCommand(input: {
  combatContext?: ScenarioParticipantCombatContext;
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  choice: "back_out" | "continue_without_ce";
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): {
  combatContext: ScenarioParticipantCombatContext;
  command: CombatRoundCommand;
  state: CombatRoundState;
} {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);
  const trigger = getCombatExperienceTriggerForPhase(input.phase);
  const backOutOpportunity = getCombatRoundPhaseAttackBackOutOpportunity({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
    visibility: input.visibility,
  });
  const phaseRequirement = getCombatRoundPhaseCombatExperienceRequirement({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
    visibility: input.visibility,
  });

  if (!participant) {
    throw new RangeError("Phase initiative participant is not in the active round.");
  }

  if (
    normalized.currentStep !== actionStep ||
    !isCombatRoundPhaseInitiativeCommitted({ phase: input.phase, state: normalized })
  ) {
    throw new RangeError("Phase attack choices can only be submitted after initiative commit.");
  }

  if (!backOutOpportunity) {
    throw new RangeError("Phase initiative choice is only available while attacked and attacking.");
  }

  if (input.choice === "continue_without_ce" && backOutOpportunity.ceRequired) {
    throw new RangeError("Combat Experience is required before continuing this attack.");
  }

  if (
    combatRoundPhaseInitiativeChoiceSubmitted({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    })
  ) {
    throw new RangeError("Phase initiative choice already submitted for this participant.");
  }

  if (
    getCombatRoundOutgoingAttackResultForParticipantPhase({
      participantId: input.participantId,
      phase: input.phase,
      state: normalized,
    })
  ) {
    throw new RangeError("Back out cannot be chosen after the attack is rolled.");
  }

  const beforeCursor =
    normalized.currentCursor?.roundNumber === normalized.roundNumber &&
    normalized.currentCursor.participantId === input.participantId &&
    normalized.currentCursor.step === getCombatRoundAttackCursorStepForPhase(input.phase)
      ? normalized.currentCursor
      : combatRoundCursorSchema.parse({
          participantId: input.participantId,
          roundNumber: normalized.roundNumber,
          step: getCombatRoundAttackCursorStepForPhase(input.phase),
        });
  const commandType = "submit_phase_initiative_choice" satisfies CombatRoundCommandType;
  const commandId =
    input.command.commandId ??
    buildCombatRoundCommandId({
      createdAt: input.command.createdAt,
      participantId: input.participantId,
      state: normalized,
      type: commandType,
    });
  const currentCombatContext = scenarioParticipantCombatContextSchema.parse(
    input.combatContext ?? {},
  );
  const canonicalOpportunity = getCombatRoundPhaseAttackCandidates({
    phase: input.phase,
    state: normalized,
  }).find((opportunity) => opportunity.participantId === input.participantId);
  const previousAttackPhaseDefensivePenalties =
    participant.declaration?.attackPhaseDefensivePenalties ??
    (canonicalOpportunity
      ? resolveCombatAttackPhaseDefensivePenalties({
          commitment: "committed",
          opportunities: [canonicalOpportunity],
          participantId: input.participantId,
          roundNumber: normalized.roundNumber,
        })
      : []);
  const backedOutPenalty =
    input.choice === "back_out" && canonicalOpportunity
      ? resolveCombatAttackPhaseDefensivePenalty({
          commitment: "committed",
          executionState: "backed_out",
          opportunity: canonicalOpportunity,
          participantId: input.participantId,
          reason: "simultaneous_attack_backout",
          roundNumber: normalized.roundNumber,
          sourceException: "simultaneous_attack_backout",
        })
      : undefined;
  const nextAttackPhaseDefensivePenalties = backedOutPenalty
    ? replaceCombatAttackPhaseDefensivePenalty({
        existing: previousAttackPhaseDefensivePenalties,
        next: backedOutPenalty,
      })
    : previousAttackPhaseDefensivePenalties;
  const softenedModifierResult =
    input.choice === "back_out"
      ? softenCombatActionGeneratedBackOutModifier({
          actionId: participant.declaration?.actionId,
          combatContext: currentCombatContext,
          opportunityId: canonicalOpportunity?.id,
          phase: input.phase,
        })
      : {
          combatContext: currentCombatContext,
          softenedModifiers: [],
          warning: undefined,
        };
  const commandShell = combatRoundCommandSchema.parse({
    afterCursor: beforeCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      ...(participant.declaration?.actionId
        ? {
            attackActionId: participant.declaration.actionId,
          }
        : {}),
      ...(canonicalOpportunity
        ? {
            attackOpportunityId: canonicalOpportunity.id,
            previousAttackOpportunity: canonicalOpportunity,
          }
        : {}),
      ...(backedOutPenalty
        ? {
            attackPhaseDefensivePenalty: backedOutPenalty,
            previousAttackPhaseDefensivePenalty: previousAttackPhaseDefensivePenalties.find(
              (penalty) => penalty.attackOpportunityId === canonicalOpportunity?.id,
            ),
          }
        : {}),
      attackStep: getCombatRoundAttackCursorStepForPhase(input.phase),
      ...(softenedModifierResult.warning
        ? {
            modifierSofteningWarning: softenedModifierResult.warning,
          }
        : {}),
      backOutAvailableReason: backOutOpportunity.reason,
      ceRequired: Boolean(phaseRequirement),
      ceWasRequired: Boolean(phaseRequirement),
      choice: input.choice,
      initiativeComparison: backOutOpportunity.threats,
      phase: input.phase,
      previousPhaseActionStepStatus: participant.stepStatuses[actionStep],
      previousPhaseResolutionStatus:
        normalized.phaseResolutionStatuses[input.participantId]?.[input.phase],
      ...(phaseRequirement
        ? {
            phaseCombatExperienceReason: phaseRequirement.reason,
            phaseCombatExperienceThreats: phaseRequirement.threats,
          }
        : {}),
      reason:
        input.choice === "back_out"
          ? "Backed out while attacked"
          : "Continued attack without Combat Experience",
      skippedAttack: input.choice === "back_out",
      softenedModifierIds: softenedModifierResult.softenedModifiers.map(
        (change) => change.modifierId,
      ),
      softenedModifiers: softenedModifierResult.softenedModifiers,
      source: "phase_initiative_resolution",
      status: input.choice === "back_out" ? "submitted" : "submitted",
      step: beforeCursor.step,
      threatened: true,
      trigger,
    },
    id: commandId,
    participantId: input.participantId,
    phase: input.phase,
    roundNumber: normalized.roundNumber,
    step: beforeCursor.step,
    type: commandType,
  });
  const stateWithCanonicalBackOut =
    input.choice === "back_out" && participant.declaration && canonicalOpportunity
      ? combatRoundStateSchema.parse({
          ...normalized,
          participants: normalized.participants.map((entry) =>
            entry.participantId === input.participantId && entry.declaration
              ? {
                  ...entry,
                  declaration: {
                    ...entry.declaration,
                    attackOpportunities: entry.declaration.attackOpportunities?.map(
                      (opportunity) =>
                        opportunity.id === canonicalOpportunity.id
                          ? {
                              ...opportunity,
                              cancelledAt: input.command.createdAt,
                              cancelledByUserId: input.command.createdByUserId,
                              status: "cancelled" as const,
                            }
                          : opportunity,
                    ),
                    attackPhaseDefensivePenalties: nextAttackPhaseDefensivePenalties,
                    combatContext: applyAttackPhaseDefensivePenaltyModifiers({
                      combatContext: scenarioParticipantCombatContextSchema.parse(
                        entry.declaration.combatContext ?? {},
                      ),
                      penalties: nextAttackPhaseDefensivePenalties,
                    }),
                    phaseContexts: {
                      ...entry.declaration.phaseContexts,
                      [input.phase]: applyAttackPhaseDefensivePenaltyModifiers({
                        combatContext: scenarioParticipantCombatContextSchema.parse(
                          entry.declaration.phaseContexts?.[input.phase] ?? {},
                        ),
                        penalties: nextAttackPhaseDefensivePenalties,
                      }),
                    },
                  },
                }
              : entry,
          ),
        })
      : normalized;
  const stateWithCommandShell = combatRoundStateSchema.parse({
    ...stateWithCanonicalBackOut,
    commands: [
      ...stateWithCanonicalBackOut.commands.filter(
        (existingCommand) => existingCommand.id !== commandId,
      ),
      commandShell,
    ],
  });
  const stateWithOutcome =
    input.choice === "back_out"
      ? applyCommittedPhaseBackOut({
          createdAt: input.command.createdAt,
          participantId: input.participantId,
          phase: input.phase,
          state: stateWithCommandShell,
        })
      : stateWithCommandShell;
  const nextParticipantId = getFirstCombatRoundPhaseCombatExperienceRequiredParticipantId({
    phase: input.phase,
    state: stateWithOutcome,
    visibility: input.visibility,
  });
  const stateAfterChoice = nextParticipantId
    ? combatRoundStateSchema.parse({
        ...stateWithOutcome,
        currentCursor: getDefaultCombatRoundCursor({
          participantId: nextParticipantId,
          roundNumber: stateWithOutcome.roundNumber,
          step: actionStep,
        }),
        currentStep: actionStep,
        phaseResolutionCursor: undefined,
        selectedParticipantId: nextParticipantId,
        selectedStep: actionStep,
      })
    : initializeCombatRoundPhaseResolutionCursor({
        phase: input.phase,
        state: stateWithOutcome,
        updatedAt: input.command.createdAt,
      });
  const afterCursor = stateAfterChoice.currentCursor ?? beforeCursor;
  const command = combatRoundCommandSchema.parse({
    ...commandShell,
    afterCursor,
    facts: {
      ...commandShell.facts,
      ...(afterCursor.participantId
        ? {
            nextStepOpened: {
              participantId: afterCursor.participantId,
              step: afterCursor.step,
            },
          }
        : {}),
    },
  });
  const selectedStep = getCombatRoundStepForCursorStep(command.afterCursor.step);

  return {
    combatContext: softenedModifierResult.combatContext,
    command,
    state: combatRoundStateSchema.parse({
      ...stateAfterChoice,
      commands: [
        ...stateAfterChoice.commands.filter((existingCommand) => existingCommand.id !== commandId),
        command,
      ],
      currentCursor: command.afterCursor,
      currentStep: selectedStep,
      selectedParticipantId: command.afterCursor.participantId ?? input.participantId,
      selectedStep,
    }),
  };
}

export function backOutCombatRoundPhaseAttack(input: {
  combatContext?: ScenarioParticipantCombatContext;
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  updatedAt: string;
  visibility?: CombatRoundVisibility;
}): {
  combatContext: ScenarioParticipantCombatContext;
  command: CombatRoundCommand;
  state: CombatRoundState;
} {
  return submitCombatRoundPhaseInitiativeChoiceCommand({
    combatContext: input.combatContext,
    command: input.command,
    choice: "back_out",
    participantId: input.participantId,
    phase: input.phase,
    state: input.state,
    visibility: input.visibility,
  });
}

export function continueCombatRoundPhaseAttack(input: {
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): {
  command: CombatRoundCommand;
  state: CombatRoundState;
} {
  const submitted = submitCombatRoundPhaseInitiativeChoiceCommand({
    command: input.command,
    choice: "continue_without_ce",
    participantId: input.participantId,
    phase: input.phase,
    state: input.state,
    visibility: input.visibility,
  });

  return {
    command: submitted.command,
    state: submitted.state,
  };
}

export interface CombatRoundPhaseInitiativeCommitParticipantInput {
  combatContext?: ScenarioParticipantCombatContext;
  scenarioParticipantId?: string;
  skillTotal?: number;
  skillTotalSource?: string;
  skillTotalWarning?: string;
}

function applyCommittedPhaseBackOut(input: {
  createdAt: string;
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundState {
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);
  const withDoneStatus = setCombatRoundPhaseResolutionStatus({
    participantId: input.participantId,
    phase: input.phase,
    state: input.state,
    status: {
      substep: "done",
      updatedAt: input.createdAt,
    },
  });

  return setCombatRoundParticipantStepStatus({
    participantId: input.participantId,
    state: withDoneStatus,
    status: "skipped",
    step: actionStep,
  });
}

function phaseResolutionStatusesEqual(
  left: CombatRoundPhaseResolutionParticipantStatus | undefined,
  right: CombatRoundPhaseResolutionParticipantStatus | undefined,
): boolean {
  return left?.substep === right?.substep && left?.updatedAt === right?.updatedAt;
}

function buildCombatRoundInitiativeCommitUndoFacts(input: {
  commandId: string;
  phase: CombatRoundPhase;
  priorState: CombatRoundState;
  stateAfterPhaseOpen: CombatRoundState;
}): CombatRoundInitiativeCommitUndoFacts {
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);
  const priorParticipantsById = new Map(
    input.priorState.participants.map((participant) => [participant.participantId, participant]),
  );
  const priorFeintById = new Map(
    input.priorState.feintProposals.map((proposal, index) => [proposal.id, { index, proposal }]),
  );
  const priorAdjustDistanceById = new Map(
    input.priorState.adjustDistanceProposals.map((proposal, index) => [
      proposal.id,
      { index, proposal },
    ]),
  );

  return combatRoundInitiativeCommitUndoFactsSchema.parse({
    adjustDistanceProposals: input.stateAfterPhaseOpen.adjustDistanceProposals.flatMap(
      (proposal) => {
        const prior = priorAdjustDistanceById.get(proposal.id);
        return prior && prior.proposal.status !== proposal.status
          ? [
              {
                priorIndex: prior.index,
                priorStatus: prior.proposal.status,
                proposalId: proposal.id,
              },
            ]
          : [];
      },
    ),
    commandId: input.commandId,
    feintProposals: input.stateAfterPhaseOpen.feintProposals.flatMap((proposal) => {
      const prior = priorFeintById.get(proposal.id);
      return prior && prior.proposal.status !== proposal.status
        ? [
            {
              priorIndex: prior.index,
              priorStatus: prior.proposal.status,
              proposalId: proposal.id,
            },
          ]
        : [];
    }),
    navigation: {
      currentCursor: input.priorState.currentCursor ?? null,
      currentStep: input.priorState.currentStep,
      phaseResolutionCursor: input.priorState.phaseResolutionCursor ?? null,
      selectedParticipantId: input.priorState.selectedParticipantId ?? null,
      selectedStep: input.priorState.selectedStep ?? null,
    },
    participantActionSteps: input.stateAfterPhaseOpen.participants.flatMap((participant) => {
      const priorStatus = priorParticipantsById.get(participant.participantId)?.stepStatuses[
        actionStep
      ];
      const nextStatus = participant.stepStatuses[actionStep];
      return priorStatus !== nextStatus
        ? [
            {
              participantId: participant.participantId,
              priorActionStepStatus: priorStatus ?? null,
            },
          ]
        : [];
    }),
    phase: input.phase,
    phaseResolutionStatuses: input.stateAfterPhaseOpen.participants.flatMap((participant) => {
      const participantId = participant.participantId;
      const priorStatus = input.priorState.phaseResolutionStatuses[participantId]?.[input.phase];
      const nextStatus =
        input.stateAfterPhaseOpen.phaseResolutionStatuses[participantId]?.[input.phase];
      return phaseResolutionStatusesEqual(priorStatus, nextStatus)
        ? []
        : [
            {
              participantId,
              priorParticipantEntryExisted: Object.hasOwn(
                input.priorState.phaseResolutionStatuses,
                participantId,
              ),
              priorStatus: priorStatus ?? null,
            },
          ];
    }),
    roundNumber: input.priorState.roundNumber,
    version: 1,
  });
}

export function commitCombatRoundPhaseInitiativeResolution(input: {
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
    participantId?: string;
  };
  participants?: Record<string, CombatRoundPhaseInitiativeCommitParticipantInput>;
  /** Complete canonical no-work participants omitted from initiative without fabricating a value. */
  nonParticipatingParticipantIds?: ReadonlySet<string>;
  phase: CombatRoundPhase;
  rng?: () => number;
  state: CombatRoundState;
  visibility?: CombatRoundVisibility;
}): {
  combatContextsByParticipantId: Record<string, ScenarioParticipantCombatContext>;
  command: CombatRoundCommand;
  state: CombatRoundState;
} {
  const normalized = combatRoundStateSchema.parse(input.state);
  const initiativeStep = getCombatRoundPhaseInitiativeStepForPhase(input.phase);

  if (normalized.currentStep !== initiativeStep) {
    throw new RangeError("Phase initiative resolution can only be committed from initiative.");
  }

  const initiativeComplete = normalized.participants.every(
    (participant) =>
      input.nonParticipatingParticipantIds?.has(participant.participantId) ||
      participant.initiatives[input.phase] !== undefined ||
      ["complete", "gmEdited", "locked", "skipped", "submitted"].includes(
        participant.stepStatuses[
          input.phase === "phase1" ? "initiative_phase_1" : "initiative_phase_2"
        ] ?? "pending",
      ),
  );
  if (!initiativeComplete) {
    throw new RangeError("Phase initiative must be complete before resolution can be committed.");
  }

  const commandParticipantId =
    input.command.participantId ??
    normalized.currentCursor?.participantId ??
    normalized.selectedParticipantId ??
    normalized.participants[0]?.participantId;

  if (!commandParticipantId) {
    throw new RangeError("No participant is available for phase initiative resolution.");
  }

  const commandId =
    input.command.commandId ??
    buildCombatRoundCommandId({
      createdAt: input.command.createdAt,
      participantId: commandParticipantId,
      state: normalized,
      type: "commit_phase_initiative_resolution",
    });
  const beforeCursor =
    normalized.currentCursor?.step === getCombatRoundPhaseInitiativeCursorStepForPhase(input.phase)
      ? normalized.currentCursor
      : getDefaultCombatRoundCursor({
          participantId: commandParticipantId,
          roundNumber: normalized.roundNumber,
          step: initiativeStep,
        });
  const difficulty = getCombatRoundCombatExperienceDifficulty(normalized);
  const appliedChoices: Array<Record<string, unknown>> = [];
  const createdCombatModifierIds: string[] = [];
  const softenedModifiers: unknown[] = [];

  const stateAfterPhaseOpen = initializeCombatRoundPhaseResolutionCursor({
    phase: input.phase,
    state: normalized,
    updatedAt: input.command.createdAt,
  });
  const initiativeCommitUndo = buildCombatRoundInitiativeCommitUndoFacts({
    commandId,
    phase: input.phase,
    priorState: normalized,
    stateAfterPhaseOpen,
  });
  const afterCursor = stateAfterPhaseOpen.currentCursor ?? beforeCursor;
  const command = combatRoundCommandSchema.parse({
    afterCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      appliedChoices,
      attackStep: getCombatRoundAttackCursorStepForPhase(input.phase),
      autoResolvedCount: appliedChoices.filter(
        (choice) => choice.choice === "roll_ce_result" && choice.defaultedOnCommit === true,
      ).length,
      createdCombatModifierIds,
      defaultedContinueCount: appliedChoices.filter(
        (choice) => choice.choice === "continue_without_ce" && choice.defaultedOnCommit === true,
      ).length,
      difficulty,
      initiativeCommitUndo,
      phase: input.phase,
      softenedModifiers,
      source: "phase_initiative_resolution_commit",
    },
    id: commandId,
    participantId: commandParticipantId,
    phase: input.phase,
    roundNumber: normalized.roundNumber,
    step: getCombatRoundPhaseInitiativeCursorStepForPhase(input.phase),
    type: "commit_phase_initiative_resolution",
  });
  const stateWithCommit = combatRoundStateSchema.parse({
    ...stateAfterPhaseOpen,
    commands: [...stateAfterPhaseOpen.commands, command],
  });
  const firstCombatExperienceParticipantId =
    getFirstCombatRoundPhaseCombatExperienceRequiredParticipantId({
      phase: input.phase,
      state: stateWithCommit,
      visibility: input.visibility,
    });
  const afterCommitCursor = firstCombatExperienceParticipantId
    ? getDefaultCombatRoundCursor({
        participantId: firstCombatExperienceParticipantId,
        roundNumber: normalized.roundNumber,
        step: getCombatRoundPhaseActionStepForPhase(input.phase),
      })
    : command.afterCursor;
  const committedCommand = combatRoundCommandSchema.parse({
    ...command,
    afterCursor: afterCommitCursor,
  });
  const selectedStep = getCombatRoundStepForCursorStep(afterCommitCursor.step);

  return {
    combatContextsByParticipantId: {},
    command: committedCommand,
    state: combatRoundStateSchema.parse({
      ...stateAfterPhaseOpen,
      commands: [...stateAfterPhaseOpen.commands, committedCommand],
      currentCursor: afterCommitCursor,
      currentStep: selectedStep,
      phaseResolutionCursor: firstCombatExperienceParticipantId
        ? undefined
        : stateAfterPhaseOpen.phaseResolutionCursor,
      selectedParticipantId: afterCommitCursor.participantId ?? commandParticipantId,
      selectedStep,
    }),
  };
}

export function restoreCombatRoundPhaseInitiativeResolutionCombatContextModifiers(input: {
  combatContext?: ScenarioParticipantCombatContext;
  command: CombatRoundCommand;
  participantId: string;
}): ScenarioParticipantCombatContext {
  const currentContext = removeCombatRoundCombatExperienceCombatContextModifiers({
    combatContext: input.combatContext,
    command: input.command,
  });
  const appliedChoices = Array.isArray(input.command.facts.appliedChoices)
    ? input.command.facts.appliedChoices
    : [];
  const participantSoftenedModifiers = appliedChoices
    .filter((choice): choice is Record<string, unknown> =>
      Boolean(
        choice &&
        typeof choice === "object" &&
        choice.participantId === input.participantId &&
        choice.choice === "back_out",
      ),
    )
    .flatMap((choice) => {
      const softenedModifierIds = Array.isArray(choice.softenedModifierIds)
        ? choice.softenedModifierIds.filter((entry): entry is string => typeof entry === "string")
        : [];
      const softenedModifiers = Array.isArray(input.command.facts.softenedModifiers)
        ? input.command.facts.softenedModifiers
        : [];

      return softenedModifiers.filter((change): change is Record<string, unknown> =>
        Boolean(
          change &&
          typeof change === "object" &&
          typeof change.modifierId === "string" &&
          softenedModifierIds.includes(change.modifierId),
        ),
      );
    });

  return restoreCombatActionGeneratedBackOutModifiers({
    combatContext: currentContext,
    softenedModifiers: participantSoftenedModifiers,
  });
}

export function recordCombatRoundNoAttackPhaseReview(input: {
  command?: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  submittedBy: "gm" | "player";
  updatedAt: string;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const hasPhaseAttack = combatRoundParticipantHasPhaseAttack({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });

  if (hasPhaseAttack) {
    throw new RangeError("No-attack phase review cannot complete an attack-capable phase.");
  }

  const completed = completeCombatRoundPhaseResolutionForParticipant({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
    submittedBy: input.submittedBy,
    updatedAt: input.updatedAt,
  });

  return input.command
    ? recordCombatRoundPhaseActionSkipCommand({
        command: input.command,
        participantId: input.participantId,
        phase: input.phase,
        state: completed,
      })
    : completed;
}

export function getCombatRoundAttackResultId(input: {
  result: Pick<
    CombatRoundAttackRollResult,
    "attackOpportunityId" | "attackerParticipantId" | "defenderParticipantId" | "phase"
  >;
  roundNumber: number;
}): string {
  const opportunityId = input.result.attackOpportunityId;
  if (opportunityId) {
    return `${input.roundNumber}:opportunity:${opportunityId}`;
  }
  return [
    input.roundNumber,
    input.result.phase,
    input.result.attackerParticipantId,
    input.result.defenderParticipantId,
  ].join(":");
}

export function getCombatRoundAttackResultById(input: {
  attackResultId: string;
  state: CombatRoundState;
}): CombatRoundAttackRollResult | undefined {
  for (const participant of input.state.participants) {
    const canonicalResult = Object.values(participant.attackResultsByOpportunity ?? {}).find(
      (result) =>
        getCombatRoundAttackResultId({ result, roundNumber: input.state.roundNumber }) ===
        input.attackResultId,
    );
    if (canonicalResult) return canonicalResult;
  }

  return undefined;
}

export interface CombatRoundOffensiveParryAttemptIdentity {
  readonly attackOpportunityId: string;
  readonly attackResultId: string;
  readonly attackerParticipantId: string;
  readonly declaredOpponentParticipantId: string;
  readonly declarationId: string;
  readonly defenderParticipantId: string;
  readonly offensiveParryAttemptId: string;
  readonly parryPurpose: "offensive_parry";
  readonly parrySourceId: string;
  readonly phase: CombatRoundPhase;
}

/**
 * Resolves a proactive Offensive Parry attempt from the exact surviving declaration and attack
 * result. The selected opponent is canonical encounter-participant identity; no alias, cursor, or
 * latest-attacker fallback is accepted here.
 */
export function getCombatRoundOffensiveParryAttemptIdentity(input: {
  attackResult: CombatRoundAttackRollResult;
  state: CombatRoundState;
}): CombatRoundOffensiveParryAttemptIdentity | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const opportunityId = input.attackResult.attackOpportunityId;
  if (!opportunityId) return undefined;
  const storedAttack = getCombatRoundAttackResultForOpportunity({
    opportunityId,
    state: normalized,
  });
  if (
    !storedAttack ||
    getCombatRoundAttackResultId({
      result: storedAttack,
      roundNumber: normalized.roundNumber,
    }) !==
      getCombatRoundAttackResultId({
        result: input.attackResult,
        roundNumber: normalized.roundNumber,
      }) ||
    storedAttack.phase !== input.attackResult.phase
  ) {
    return undefined;
  }
  const defender = normalized.participants.find(
    (participant) => participant.participantId === input.attackResult.defenderParticipantId,
  );
  const declaration = defender?.declaration;
  const declaredOpponentParticipantId = declaration?.combatContext?.selectedOpponentId;
  if (
    declaration?.actionId !== "offensive_parry" ||
    declaration.roundNumber !== normalized.roundNumber ||
    !declaredOpponentParticipantId ||
    declaredOpponentParticipantId !== input.attackResult.attackerParticipantId
  ) {
    return undefined;
  }
  const declarationId =
    declaration.id ??
    buildCombatRoundDeclarationId({
      participantId: input.attackResult.defenderParticipantId,
      roundNumber: normalized.roundNumber,
    });
  const attackResultId = getCombatRoundAttackResultId({
    result: input.attackResult,
    roundNumber: normalized.roundNumber,
  });
  return {
    attackOpportunityId: opportunityId,
    attackResultId,
    attackerParticipantId: input.attackResult.attackerParticipantId,
    declaredOpponentParticipantId,
    declarationId,
    defenderParticipantId: input.attackResult.defenderParticipantId,
    offensiveParryAttemptId: buildOffensiveParryAttemptId({
      attackResultId,
      declarationId,
    }),
    parryPurpose: "offensive_parry",
    parrySourceId:
      declaration.phaseContexts?.[input.attackResult.phase]?.parrySource ??
      declaration.combatContext?.parrySource ??
      "auto",
    phase: input.attackResult.phase,
  };
}

export function getCombatRoundParryDisarmAttemptIdentity(input: {
  attackResult: CombatRoundAttackRollResult;
  state: CombatRoundState;
}):
  | {
      attackResultId: string;
      declaredOpponentParticipantId: string;
      disarmAttemptId: string;
      parryPurpose: "parry_disarm";
      parrySourceId: string;
    }
  | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const defender = normalized.participants.find(
    (participant) => participant.participantId === input.attackResult.defenderParticipantId,
  );
  const declaration = defender?.declaration;
  const disarm = declaration?.disarm;
  if (
    declaration?.actionId !== "parry_disarm" ||
    declaration.roundNumber !== normalized.roundNumber ||
    (disarm &&
      (disarm.method !== "reactive_parry" ||
        disarm.phase !== input.attackResult.phase ||
        disarm.targetParticipantId !== input.attackResult.attackerParticipantId ||
        disarm.targetWeapon.itemId !== input.attackResult.weaponInstanceId))
  ) {
    return undefined;
  }
  const attempt = normalized.disarmAttempts.find(
    (candidate) =>
      candidate.status === "awaiting_contact" &&
      candidate.method === "reactive_parry" &&
      candidate.actingParticipantId === input.attackResult.defenderParticipantId &&
      candidate.resistingParticipantId === input.attackResult.attackerParticipantId &&
      candidate.phase === input.attackResult.phase,
  );
  if (!attempt) return undefined;
  return {
    attackResultId: getCombatRoundAttackResultId({
      result: input.attackResult,
      roundNumber: normalized.roundNumber,
    }),
    declaredOpponentParticipantId: input.attackResult.attackerParticipantId,
    disarmAttemptId: attempt.id,
    parryPurpose: "parry_disarm",
    parrySourceId: "declared-disarm-weapon",
  };
}

export function getCombatRoundAttackResultForOpportunity(input: {
  opportunityId: string;
  state: CombatRoundState;
}): CombatRoundAttackRollResult | undefined {
  return input.state.participants
    .flatMap((participant) => Object.values(participant.attackResultsByOpportunity ?? {}))
    .find((result) => result.attackOpportunityId === input.opportunityId);
}

export interface CombatRoundAttackDistanceModifierDetail {
  actualDistance?: number;
  createdCombatModifierIds: string[];
  modifierId?: string;
  nearestPreferredDistance?: number;
  notes?: string;
  preferredDistances: number[];
  value: number;
  warning?: string;
  weaponName?: string;
}

function parseCombatRoundAttackDistanceModifierDetail(
  value: unknown,
): CombatRoundAttackDistanceModifierDetail | undefined {
  if (!value || typeof value !== "object") {
    return undefined;
  }

  const record = value as Record<string, unknown>;
  const preferredDistances = Array.isArray(record.preferredDistances)
    ? record.preferredDistances.filter((entry): entry is number => Number.isInteger(entry))
    : [];
  const createdCombatModifierIds = Array.isArray(record.createdCombatModifierIds)
    ? record.createdCombatModifierIds.filter((entry): entry is string => typeof entry === "string")
    : [];
  const valueNumber =
    typeof record.value === "number" && Number.isInteger(record.value) ? record.value : 0;

  return {
    actualDistance:
      typeof record.actualDistance === "number" && Number.isInteger(record.actualDistance)
        ? record.actualDistance
        : undefined,
    createdCombatModifierIds,
    modifierId: typeof record.modifierId === "string" ? record.modifierId : undefined,
    nearestPreferredDistance:
      typeof record.nearestPreferredDistance === "number" &&
      Number.isInteger(record.nearestPreferredDistance)
        ? record.nearestPreferredDistance
        : undefined,
    notes: typeof record.notes === "string" ? record.notes : undefined,
    preferredDistances,
    value: valueNumber,
    warning: typeof record.warning === "string" ? record.warning : undefined,
    weaponName: typeof record.weaponName === "string" ? record.weaponName : undefined,
  };
}

export function getCombatRoundAttackDistanceModifierDetail(input: {
  result: CombatRoundAttackRollResult;
  state: CombatRoundState;
}): CombatRoundAttackDistanceModifierDetail | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const attackResultId = getCombatRoundAttackResultId({
    result: input.result,
    roundNumber: normalized.roundNumber,
  });
  const command = [...normalized.commands]
    .reverse()
    .find(
      (entry) =>
        entry.type === "roll_attack" &&
        entry.roundNumber === normalized.roundNumber &&
        entry.facts.attackResultId === attackResultId,
    );

  return parseCombatRoundAttackDistanceModifierDetail(command?.facts.distanceModifier);
}

export function buildCombatRoundPhaseResolutionResult(input: {
  attackResult: CombatRoundAttackRollResult;
  roundNumber: number;
  state?: CombatRoundState;
  updatedAt: string;
}): CombatRoundPhaseResolutionResult {
  const attackResultId = getCombatRoundAttackResultId({
    result: input.attackResult,
    roundNumber: input.roundNumber,
  });

  const offensiveParryAttempt = input.state
    ? getCombatRoundOffensiveParryAttemptIdentity({
        attackResult: input.attackResult,
        state: input.state,
      })
    : undefined;
  const parryDisarmAttempt = input.state
    ? getCombatRoundParryDisarmAttemptIdentity({
        attackResult: input.attackResult,
        state: input.state,
      })
    : undefined;
  const parryRequired =
    input.attackResult.attackType !== "missile" &&
    (input.attackResult.hit || Boolean(offensiveParryAttempt) || Boolean(parryDisarmAttempt));

  return combatRoundPhaseResolutionResultSchema.parse({
    attackResultId,
    attackerParticipantId: input.attackResult.attackerParticipantId,
    damageProposal: {
      proposedEffects: [],
      status: "not_ready",
    },
    damageRoll: input.attackResult.hit
      ? {
          notes: "Awaiting parry resolution.",
          status: "pending",
        }
      : {
          status: "not_required",
        },
    defenderParticipantId: input.attackResult.defenderParticipantId,
    parryResolution: parryRequired
      ? {
          attackOpportunityId: offensiveParryAttempt?.attackOpportunityId,
          attackResultId: offensiveParryAttempt?.attackResultId,
          declaredOpponentParticipantId: offensiveParryAttempt?.declaredOpponentParticipantId,
          disarmAttemptId: parryDisarmAttempt?.disarmAttemptId,
          offensiveParryAttemptId: offensiveParryAttempt?.offensiveParryAttemptId,
          offensiveParryDeclarationId: offensiveParryAttempt?.declarationId,
          parrySourceId: offensiveParryAttempt?.parrySourceId ?? parryDisarmAttempt?.parrySourceId,
          purpose:
            offensiveParryAttempt?.parryPurpose ??
            parryDisarmAttempt?.parryPurpose ??
            "ordinary_defense",
          status: "pending",
        }
      : {
          resultLabel:
            input.attackResult.attackType === "missile" && input.attackResult.hit
              ? "Ordinary missile Parry not selected"
              : "Attack missed",
          status: "not_applicable",
        },
    phase: input.attackResult.phase,
    roundNumber: input.roundNumber,
    updatedAt: input.updatedAt,
  });
}

export function getCombatRoundPhaseResolutionResultForAttack(input: {
  attackResult: CombatRoundAttackRollResult;
  state: CombatRoundState;
}): CombatRoundPhaseResolutionResult | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const attackResultId = getCombatRoundAttackResultId({
    result: input.attackResult,
    roundNumber: normalized.roundNumber,
  });

  return normalized.phaseResolutionResults.find(
    (resolution) => resolution.attackResultId === attackResultId,
  );
}

export type ReactiveAttackPhase2InitiativeModifierCategory =
  | "no_hit_no_parry_needed"
  | "no_hit_parry_margin_6_plus"
  | "no_hit_parry_margin_0_to_5"
  | "hit"
  | "critical_hit";

export interface ReactiveAttackPhase2InitiativeModifier {
  attackResultId: string;
  category: ReactiveAttackPhase2InitiativeModifierCategory;
  parryMargin?: number;
  reason: string;
  value: number;
}

function getReactiveAttackPhase2InitiativeModifierForIncomingAttack(input: {
  attackResult: CombatRoundAttackRollResult;
  state: CombatRoundState;
}): ReactiveAttackPhase2InitiativeModifier {
  const normalized = combatRoundStateSchema.parse(input.state);
  const attackResultId = getCombatRoundAttackResultId({
    result: input.attackResult,
    roundNumber: normalized.roundNumber,
  });
  const resolution = getCombatRoundPhaseResolutionResultForAttack({
    attackResult: input.attackResult,
    state: normalized,
  });
  const effectiveDamage = resolution?.damageResult
    ? getCombatRoundEffectiveDamageResult(resolution.damageResult)
    : undefined;

  if (!input.attackResult.hit) {
    return {
      attackResultId,
      category: "no_hit_no_parry_needed",
      reason: "phase 1 attack missed; no parry needed",
      value: 6,
    };
  }

  if (effectiveDamage?.effectiveCriticalGrade) {
    return {
      attackResultId,
      category: "critical_hit",
      reason: `critical ${effectiveDamage.effectiveCriticalGrade.toUpperCase()} received in phase 1`,
      value: -6,
    };
  }

  const parryResolution = resolution?.parryResolution;

  if (parryResolution?.success) {
    const targetNumber = parryResolution.targetNumber ?? 21;
    const parryTotal = parryResolution.total ?? targetNumber;
    const parryMargin = parryTotal - targetNumber;

    return parryMargin >= 6
      ? {
          attackResultId,
          category: "no_hit_parry_margin_6_plus",
          parryMargin,
          reason: `phase 1 parry succeeded by ${parryMargin}`,
          value: 6,
        }
      : {
          attackResultId,
          category: "no_hit_parry_margin_0_to_5",
          parryMargin,
          reason: `phase 1 parry succeeded by ${parryMargin}`,
          value: 0,
        };
  }

  return {
    attackResultId,
    category: "hit",
    reason: "phase 1 attack hit",
    value: -3,
  };
}

export function getReactiveAttackPhase2InitiativeModifier(input: {
  participantId: string;
  state: CombatRoundState;
}): ReactiveAttackPhase2InitiativeModifier | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );

  if (participant?.declaration?.actionId !== "parry_attack") {
    return undefined;
  }

  const targetParticipant = getCombatRoundParticipantByTargetId({
    state: normalized,
    targetParticipantId: participant.declaration.phaseContexts?.phase2?.targetParticipantId,
  });

  if (!targetParticipant) {
    return undefined;
  }

  const incomingAttacks = getCombatRoundIncomingAttackResultsForParticipantPhase({
    participantId: input.participantId,
    phase: "phase1",
    state: normalized,
  }).filter(
    (attackResult) => attackResult.attackerParticipantId === targetParticipant.participantId,
  );

  if (incomingAttacks.length === 0) {
    return undefined;
  }

  return incomingAttacks
    .map((attackResult) =>
      getReactiveAttackPhase2InitiativeModifierForIncomingAttack({
        attackResult,
        state: normalized,
      }),
    )
    .sort((left, right) => left.value - right.value)[0];
}

export function buildReactiveAttackPhase2InitiativeModifierEntry(input: {
  actionId?: string;
  participantId: string;
  state: CombatRoundState;
}): ScenarioCombatModifierEntry | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const modifier = getReactiveAttackPhase2InitiativeModifier(input);

  if (modifier) {
    return buildReactiveAttackPhase2GeneratedInitiativeModifier({
      reason: modifier.reason,
      value: modifier.value,
    });
  }

  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const actionId = input.actionId ?? participant?.declaration?.actionId;

  if (actionId !== "parry_attack") {
    return undefined;
  }

  const phase2ReviewReached =
    COMBAT_ROUND_STEPS.indexOf(normalized.currentStep) >=
    COMBAT_ROUND_STEPS.indexOf("review_phase_2_modifiers");

  return buildReactiveAttackPhase2GeneratedInitiativeModifier({
    reason: phase2ReviewReached
      ? "no phase 1 attack received; no phase 2 attack opens"
      : "phase 2 initiative pending phase 1 incoming result",
    value: phase2ReviewReached ? 0 : 6,
  });
}

function refreshCombatRoundReactiveAttackPhase2InitiativeModifiers(
  state: CombatRoundState,
): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(state);

  return combatRoundStateSchema.parse({
    ...normalized,
    participants: normalized.participants.map((participant) => {
      const declaration = participant.declaration;

      if (!declaration) {
        return participant;
      }

      const combatContext = scenarioParticipantCombatContextSchema.parse(
        declaration.combatContext ?? {},
      );
      const nextReactiveModifier =
        declaration.actionId === "parry_attack"
          ? buildReactiveAttackPhase2InitiativeModifierEntry({
              participantId: participant.participantId,
              state: normalized,
            })
          : undefined;
      const nextSituationInitiative = [
        ...combatContext.modifierBuckets.situationInitiative.filter(
          (entry) => !isReactiveAttackGeneratedInitiativeModifier(entry),
        ),
        ...(nextReactiveModifier ? [nextReactiveModifier] : []),
      ];

      return {
        ...participant,
        declaration: {
          ...declaration,
          combatContext: {
            ...combatContext,
            modifierBuckets: {
              ...combatContext.modifierBuckets,
              situationInitiative: nextSituationInitiative,
            },
          },
        },
      };
    }),
  });
}

export function getCombatRoundDisplayPhaseResolutionResultForParticipantPhase(input: {
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  updatedAt?: string;
}): CombatRoundPhaseResolutionResult | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const attackResult = getCombatRoundDisplayAttackResultForParticipantPhase({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });

  if (!attackResult) {
    return undefined;
  }

  return (
    getCombatRoundPhaseResolutionResultForAttack({
      attackResult,
      state: normalized,
    }) ??
    buildCombatRoundPhaseResolutionResult({
      attackResult,
      roundNumber: normalized.roundNumber,
      state: normalized,
      updatedAt: input.updatedAt ?? attackResult.rolledAt,
    })
  );
}

function upsertCombatRoundPhaseResolutionResults(input: {
  results: CombatRoundPhaseResolutionResult[];
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const nextResults = input.results.map((result) =>
    combatRoundPhaseResolutionResultSchema.parse(result),
  );

  return {
    ...normalized,
    phaseResolutionResults: [
      ...normalized.phaseResolutionResults.filter(
        (existing) =>
          !nextResults.some((result) => result.attackResultId === existing.attackResultId),
      ),
      ...nextResults,
    ],
  };
}

export function ensureCombatRoundPhaseResolutionResultsForPhase(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
  updatedAt: string;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const results = normalized.participants
    .flatMap((participant) =>
      Object.values(participant.attackResultsByOpportunity ?? {}).filter(
        (result) => result.phase === input.phase,
      ),
    )
    .map((attackResult) => {
      const existing = getCombatRoundPhaseResolutionResultForAttack({
        attackResult,
        state: normalized,
      });

      return (
        existing ??
        buildCombatRoundPhaseResolutionResult({
          attackResult,
          roundNumber: normalized.roundNumber,
          state: normalized,
          updatedAt: input.updatedAt,
        })
      );
    });

  return refreshCombatRoundReactiveAttackPhase2InitiativeModifiers(
    upsertCombatRoundPhaseResolutionResults({
      results,
      state: normalized,
    }),
  );
}

export function recordCombatRoundParryResolution(input: {
  attackResult: CombatRoundAttackRollResult;
  parryResolution: CombatRoundParryResolutionInput;
  state: CombatRoundState;
  updatedAt: string;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const parryResolution = combatRoundParryResolutionSchema.parse(input.parryResolution);
  const existing =
    getCombatRoundPhaseResolutionResultForAttack({
      attackResult: input.attackResult,
      state: normalized,
    }) ??
    buildCombatRoundPhaseResolutionResult({
      attackResult: input.attackResult,
      roundNumber: normalized.roundNumber,
      state: normalized,
      updatedAt: input.updatedAt,
    });
  if (existing.parryResolution.status === "resolved") {
    throw new RangeError("The parry for this attack has already been resolved.");
  }
  const nextResult = combatRoundPhaseResolutionResultSchema.parse({
    ...existing,
    criticalRoll: {
      status: "not_required",
    },
    damageProposal: {
      committedCombatEffectIds: [],
      proposedEffects: [],
      status: "not_ready",
    },
    damageRoll:
      input.attackResult.hit && parryResolution.success !== true
        ? {
            notes: "Parry resolved unsuccessfully. Damage roll is pending.",
            status: "pending",
          }
        : {
            notes: input.attackResult.hit
              ? "Parry resolved successfully. Damage is not required."
              : undefined,
            status: "not_required",
          },
    damageResult: undefined,
    hitLocationRoll:
      input.attackResult.hit && parryResolution.success !== true
        ? existing.hitLocationRoll
        : {
            status: "pending",
          },
    parryResolution,
    updatedAt: input.updatedAt,
  });

  return refreshCombatRoundReactiveAttackPhase2InitiativeModifiers(
    upsertCombatRoundPhaseResolutionResults({
      results: [nextResult],
      state: normalized,
    }),
  );
}

function getCombatRoundParryCommandAfterCursor(input: {
  attackResult: CombatRoundAttackRollResult;
  parryResolution: CombatRoundParryResolution;
  state: CombatRoundState;
}): CombatRoundCursor {
  if (input.parryResolution.success === true) {
    const attackResultId = getCombatRoundAttackResultId({
      result: input.attackResult,
      roundNumber: input.state.roundNumber,
    });
    const offensiveParryContest = input.state.offensiveParryContests.find(
      (contest) =>
        contest.attackResultId === attackResultId &&
        contest.opportunityId === input.attackResult.attackOpportunityId &&
        contest.status === "awaiting_rolls",
    );
    if (offensiveParryContest) {
      return combatRoundCursorSchema.parse({
        participantId: offensiveParryContest.controllerParticipantId,
        roundNumber: input.state.roundNumber,
        step: getCombatRoundParryCursorStepForPhase(input.attackResult.phase),
      });
    }
    return getCombatRoundPhaseActionOrCompletionCursor({
      phase: input.attackResult.phase,
      state: input.state,
    });
  }

  if (!input.attackResult.hit) {
    return getCombatRoundPhaseActionOrCompletionCursor({
      phase: input.attackResult.phase,
      state: input.state,
    });
  }

  return combatRoundCursorSchema.parse({
    participantId: input.attackResult.defenderParticipantId,
    roundNumber: input.state.roundNumber,
    step: getCombatRoundDamageCursorStepForPhase(input.attackResult.phase),
  });
}

function recordCombatRoundParryCommand(input: {
  attackResult: CombatRoundAttackRollResult;
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  parryResolution: CombatRoundParryResolution;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const beforeCursor = combatRoundCursorSchema.parse({
    participantId: input.attackResult.defenderParticipantId,
    roundNumber: normalized.roundNumber,
    step: getCombatRoundParryCursorStepForPhase(input.attackResult.phase),
  });
  const afterCursor = getCombatRoundParryCommandAfterCursor({
    attackResult: input.attackResult,
    parryResolution: input.parryResolution,
    state: normalized,
  });
  const commandType = "roll_parry" satisfies CombatRoundCommandType;
  const command = combatRoundCommandSchema.parse({
    afterCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      attackResultId: getCombatRoundAttackResultId({
        result: input.attackResult,
        roundNumber: normalized.roundNumber,
      }),
      attackerParticipantId: input.attackResult.attackerParticipantId,
      defenderParticipantId: input.attackResult.defenderParticipantId,
      success: input.parryResolution.success === true,
      ...(afterCursor.participantId
        ? {
            nextStepOpened: {
              participantId: afterCursor.participantId,
              step: afterCursor.step,
            },
          }
        : {}),
    },
    id:
      input.command.commandId ??
      buildCombatRoundCommandId({
        createdAt: input.command.createdAt,
        participantId: input.attackResult.defenderParticipantId,
        state: normalized,
        type: commandType,
      }),
    participantId: input.attackResult.defenderParticipantId,
    phase: input.attackResult.phase,
    roundNumber: normalized.roundNumber,
    step: beforeCursor.step,
    type: commandType,
  });
  const selectedStep = getCombatRoundStepForCursorStep(command.afterCursor.step);

  const stateWithCommand = {
    ...normalized,
    commands: [...normalized.commands, command],
    currentCursor: command.afterCursor,
    currentStep: selectedStep,
    selectedParticipantId: command.afterCursor.participantId ?? normalized.selectedParticipantId,
    selectedStep,
  };

  const attackResultId = getCombatRoundAttackResultId({
    result: input.attackResult,
    roundNumber: normalized.roundNumber,
  });

  return appendCombatRoundEventForCommand({
    command,
    draft: {
      actorParticipantId: input.attackResult.defenderParticipantId,
      attackResultId,
      attackerParticipantId: input.attackResult.attackerParticipantId,
      defenderParticipantId: input.attackResult.defenderParticipantId,
      facts: {
        involvedOutcome: {
          attackHit: input.attackResult.hit,
          brawlingContestOpened: input.state.offensiveParryContests.some(
            (contest) =>
              contest.attackResultId === attackResultId &&
              contest.parryResultId === `${attackResultId}:parry` &&
              contest.status !== "cancelled",
          ),
          declaredOpponentParticipantId: input.parryResolution.declaredOpponentParticipantId,
          offensiveParryAttemptId: input.parryResolution.offensiveParryAttemptId,
          parryPurpose: input.parryResolution.purpose,
          resultLabel: input.parryResolution.resultLabel,
          status: input.parryResolution.status,
          success: input.parryResolution.success,
        },
        publicOutcome: {
          attackHit: input.attackResult.hit,
          brawlingContestOpened: input.state.offensiveParryContests.some(
            (contest) =>
              contest.attackResultId === attackResultId &&
              contest.parryResultId === `${attackResultId}:parry` &&
              contest.status !== "cancelled",
          ),
          parryPurpose: input.parryResolution.purpose,
          status: input.parryResolution.status,
          success: input.parryResolution.success,
        },
        rollerPrivate: {
          combinedParryScore: input.parryResolution.combinedParryScore,
          modifierAdjustment: input.parryResolution.modifierAdjustment,
          modifierBreakdown: input.parryResolution.modifierBreakdown,
          openEndedD10s: input.parryResolution.openEndedD10s,
          rollD20: input.parryResolution.rollD20,
          rollTotal: input.parryResolution.rollTotal,
          total: input.parryResolution.total,
        },
      },
      ownerParticipantId: input.attackResult.defenderParticipantId,
      parryResultId: `${attackResultId}:parry`,
      phase: input.attackResult.phase,
      rollerParticipantId: input.attackResult.defenderParticipantId,
      sourceIds: [attackResultId, `${attackResultId}:parry`],
      status: input.parryResolution.status === "not_applicable" ? "not_applicable" : "recorded",
      step: getCombatStepEventPhaseStep({ kind: "parry", phase: input.attackResult.phase }),
      targetParticipantId: input.attackResult.attackerParticipantId,
      type: "parry",
    },
    state: stateWithCommand,
  });
}

export function recordCombatRoundParryResult(input: {
  attackResult: CombatRoundAttackRollResult;
  command?: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  parryResolution: CombatRoundParryResolutionInput;
  state: CombatRoundState;
  submittedBy: "gm" | "player";
  updatedAt: string;
}): CombatRoundState {
  const phase = input.attackResult.phase;
  const parryResolution = combatRoundParryResolutionSchema.parse(input.parryResolution);
  const withParry = recordCombatRoundParryResolution({
    attackResult: input.attackResult,
    parryResolution,
    state: input.state,
    updatedAt: input.updatedAt,
  });
  const withOffensiveParryContest =
    parryResolution.success === true
      ? openOffensiveParryContestAfterSuccessfulParry({
          attackResult: input.attackResult,
          parryResolution,
          state: withParry,
        })
      : withParry;
  const offensiveParryContest = withOffensiveParryContest.offensiveParryContests.find(
    (contest) =>
      contest.opportunityId === input.attackResult.attackOpportunityId &&
      contest.attackResultId ===
        getCombatRoundAttackResultId({
          result: input.attackResult,
          roundNumber: withOffensiveParryContest.roundNumber,
        }) &&
      contest.status === "awaiting_rolls",
  );
  const nextRoundState: CombatRoundState = offensiveParryContest
    ? combatRoundStateSchema.parse({
        ...withOffensiveParryContest,
        currentCursor: {
          participantId: offensiveParryContest.controllerParticipantId,
          roundNumber: withOffensiveParryContest.roundNumber,
          step: (phase === "phase1" ? "P1" : "P2") as CombatRoundCursorStep,
        },
        currentStep: phase === "phase1" ? "phase_1_actions" : "phase_2_actions",
        phaseResolutionCursor: {
          participantId: offensiveParryContest.controllerParticipantId,
          phase,
          substep: "parry" as const,
        },
        selectedParticipantId: offensiveParryContest.controllerParticipantId,
        selectedStep: getCombatRoundParryReviewStepForPhase(phase),
      })
    : parryResolution.success === true
      ? completeCombatRoundPhaseResolutionForParticipant({
          participantId: input.attackResult.attackerParticipantId,
          phase,
          state: withOffensiveParryContest,
          submittedBy: input.submittedBy,
          updatedAt: input.updatedAt,
        })
      : !input.attackResult.hit
        ? completeCombatRoundPhaseResolutionForParticipant({
            participantId: input.attackResult.attackerParticipantId,
            phase,
            state: withOffensiveParryContest,
            submittedBy: input.submittedBy,
            updatedAt: input.updatedAt,
          })
        : advanceCombatRoundPhaseResolutionSubstepForParticipant({
            participantId: input.attackResult.attackerParticipantId,
            phase,
            state: withOffensiveParryContest,
            updatedAt: input.updatedAt,
          });
  const defenderOwnedNextRoundState: CombatRoundState =
    parryResolution.success === true || !input.attackResult.hit
      ? nextRoundState
      : combatRoundStateSchema.parse({
          ...nextRoundState,
          phaseResolutionCursor: {
            participantId: input.attackResult.defenderParticipantId,
            phase,
            substep: "damage" as const,
          },
          selectedParticipantId: input.attackResult.defenderParticipantId,
          selectedStep: getCombatRoundDamageReviewStepForPhase(phase),
        });

  return input.command
    ? recordCombatRoundParryCommand({
        attackResult: input.attackResult,
        command: input.command,
        parryResolution,
        state: defenderOwnedNextRoundState,
      })
    : defenderOwnedNextRoundState;
}

function getOffensiveParryDeclarationId(input: {
  participantId: string;
  roundNumber: number;
}): string {
  return `round:${input.roundNumber}:participant:${input.participantId}:declaration`;
}

function openOffensiveParryContestAfterSuccessfulParry(input: {
  attackResult: CombatRoundAttackRollResult;
  parryResolution: CombatRoundParryResolution;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  if (
    input.parryResolution.status !== "resolved" ||
    input.parryResolution.success !== true ||
    input.parryResolution.purpose !== "offensive_parry" ||
    !input.attackResult.attackOpportunityId
  ) {
    return normalized;
  }
  const attempt = getCombatRoundOffensiveParryAttemptIdentity({
    attackResult: input.attackResult,
    state: normalized,
  });
  if (
    !attempt ||
    input.parryResolution.attackOpportunityId !== attempt.attackOpportunityId ||
    input.parryResolution.attackResultId !== attempt.attackResultId ||
    input.parryResolution.declaredOpponentParticipantId !== attempt.declaredOpponentParticipantId ||
    input.parryResolution.offensiveParryAttemptId !== attempt.offensiveParryAttemptId ||
    input.parryResolution.offensiveParryDeclarationId !== attempt.declarationId ||
    input.parryResolution.parrySourceId !== attempt.parrySourceId
  ) {
    return normalized;
  }

  const attackResultId = getCombatRoundAttackResultId({
    result: input.attackResult,
    roundNumber: normalized.roundNumber,
  });
  const parryResultId = `${attackResultId}:parry`;
  if (
    normalized.continuedContacts.some(
      (contact) =>
        contact.sourceAttackResultId === attackResultId &&
        contact.sourceOpportunityId === input.attackResult.attackOpportunityId &&
        contact.sourceParryResultId === parryResultId,
    )
  ) {
    return normalized;
  }
  const contestId = buildOffensiveParryContestId({ parryResultId });
  if (normalized.offensiveParryContests.some((contest) => contest.id === contestId)) {
    return normalized;
  }
  const targetNumber = input.parryResolution.targetNumber;
  const total = input.parryResolution.total;
  if (targetNumber === undefined || total === undefined || total < targetNumber) {
    throw new RangeError("A successful Offensive Parry requires its canonical parry margin.");
  }
  const quality = resolveOffensiveParryQualityModifier(total - targetNumber);
  return combatRoundStateSchema.parse({
    ...normalized,
    offensiveParryContests: [
      ...normalized.offensiveParryContests,
      offensiveParryContestSchema.parse({
        affectedParticipantId: input.attackResult.attackerParticipantId,
        attackResultId,
        brawlingContestResultId: buildOffensiveParryContestResultId({ contestId }),
        controllerParticipantId: input.attackResult.defenderParticipantId,
        declarationId: attempt.declarationId,
        declaredOpponentParticipantId: attempt.declaredOpponentParticipantId,
        id: contestId,
        offensiveParryAttemptId: attempt.offensiveParryAttemptId,
        opportunityId: input.attackResult.attackOpportunityId,
        parryQualityModifier: quality.modifier,
        parryQualityTableRow: quality.tableRow,
        parryResultId,
        phase: input.attackResult.phase,
        roundNumber: normalized.roundNumber,
        status: "awaiting_rolls",
      }),
    ],
  });
}

export function getOffensiveParryContest(input: { contestId: string; state: CombatRoundState }) {
  return combatRoundStateSchema
    .parse(input.state)
    .offensiveParryContests.find((contest) => contest.id === input.contestId);
}

export function recordCombatRoundOffensiveParryBrawlingRoll(input: {
  attackResultId: string;
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
    createdRevision?: string;
  };
  contestId: string;
  declarationId: string;
  executionGroupId: string;
  opportunityId: string;
  opponentParticipantId: string;
  parryResultId: string;
  phase: CombatRoundPhase;
  roll: OffensiveParryBrawlingRoll;
  rollerParticipantId: string;
  skillContestCalculation?: z.infer<typeof combatSkillContestCalculationSchema>;
  state: CombatRoundState;
  submittedBy: "gm" | "player";
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const contest = normalized.offensiveParryContests.find((entry) => entry.id === input.contestId);
  if (!contest || contest.status !== "awaiting_rolls") {
    throw new RangeError("The Offensive Parry Brawling contest is not awaiting rolls.");
  }
  if (
    contest.attackResultId !== input.attackResultId ||
    contest.declarationId !== input.declarationId ||
    contest.opportunityId !== input.opportunityId ||
    contest.parryResultId !== input.parryResultId ||
    contest.phase !== input.phase
  ) {
    throw new RangeError("The Offensive Parry contest identity does not match the current task.");
  }
  const isController = input.rollerParticipantId === contest.controllerParticipantId;
  const isResponder = input.rollerParticipantId === contest.affectedParticipantId;
  if (!isController && !isResponder) {
    throw new RangeError("Only a participant in the Offensive Parry contest may roll.");
  }
  const expectedOpponentId = isController
    ? contest.affectedParticipantId
    : contest.controllerParticipantId;
  if (input.opponentParticipantId !== expectedOpponentId) {
    throw new RangeError("The Offensive Parry opponent identity does not match the current task.");
  }
  if ((isController && contest.initiatorRoll) || (isResponder && contest.responderRoll)) {
    throw new RangeError("This participant has already rolled for the Offensive Parry contest.");
  }
  const roll = offensiveParryBrawlingRollSchema.parse(input.roll);
  if (
    roll.participantId !== input.rollerParticipantId ||
    roll.rollPurpose !== "offensive_parry_brawling"
  ) {
    throw new RangeError("The Brawling roll does not match the authorized participant or purpose.");
  }
  const withRoll = offensiveParryContestSchema.parse({
    ...contest,
    initiatorRoll: isController ? roll : contest.initiatorRoll,
    initiatorRollRecorded: isController || contest.initiatorRollRecorded,
    responderRoll: isResponder ? roll : contest.responderRoll,
    responderRollRecorded: isResponder || contest.responderRollRecorded,
  });
  const resolved =
    withRoll.initiatorRoll && withRoll.responderRoll
      ? offensiveParryContestSchema.parse({
          ...withRoll,
          status: "resolved",
          winnerParticipantId: resolveOffensiveParryContestWinner({
            controllerParticipantId: withRoll.controllerParticipantId,
            controllerTotal: withRoll.initiatorRoll.finalTotal,
            responderParticipantId: withRoll.affectedParticipantId,
            responderTotal: withRoll.responderRoll.finalTotal,
          }),
        })
      : withRoll;
  const controllerWon =
    resolved.status === "resolved" &&
    resolved.winnerParticipantId === resolved.controllerParticipantId;
  const continuedContactId = buildContinuedContactId({ contestId: contest.id });
  const lifecycleSequence = getCombatRoundNextEventSequence(normalized);
  const lifecycleContext = {
    createdAt: input.command.createdAt,
    createdRevision: input.command.createdRevision,
    createdSequence: lifecycleSequence,
    encounterId: normalized.encounterId,
    visibility: { audience: "involved" as const, sourceIdentity: "public" as const },
  };
  const continuedContactLifecycle = projectProcessRestrictionToCanonicalModifierLifecycle({
    context: lifecycleContext,
    duration: {
      conditionId: continuedContactId,
      conditionKind: "contact_ended",
      kind: "until_condition",
      startPhase: contest.phase,
      startRound: contest.roundNumber,
      startSequence: lifecycleSequence,
    },
    effectId: continuedContactId,
    effectKind: "continued_contact",
    opponentParticipantId: contest.affectedParticipantId,
    ownerParticipantId: contest.controllerParticipantId,
    processId: continuedContactId,
    publicLabel: "Continued Contact",
  }).effect;
  const nextContacts = controllerWon
    ? [
        ...normalized.continuedContacts.filter((contact) => contact.id !== continuedContactId),
        continuedContactSchema.parse({
          affectedParticipantId: contest.affectedParticipantId,
          brawlingContestResultId: contest.brawlingContestResultId,
          canonicalLifecycle: continuedContactLifecycle,
          controllerParticipantId: contest.controllerParticipantId,
          establishedPhase: contest.phase,
          establishedRound: contest.roundNumber,
          id: continuedContactId,
          sourceActionId: "offensive_parry",
          sourceAttackResultId: contest.attackResultId,
          sourceDeclarationId: contest.declarationId,
          sourceOpportunityId: contest.opportunityId,
          sourceParryResultId: contest.parryResultId,
          status: "active",
        }),
      ]
    : normalized.continuedContacts;
  const unbalancedConditionId = buildUnbalancedConditionId({ continuedContactId });
  const unbalancedLifecycle = projectProcessRestrictionToCanonicalModifierLifecycle({
    context: lifecycleContext,
    duration: {
      conditionId: continuedContactId,
      conditionKind: "contact_ended",
      kind: "until_condition",
      startPhase: contest.phase,
      startRound: contest.roundNumber,
      startSequence: lifecycleSequence,
    },
    effectId: unbalancedConditionId,
    effectKind: "unbalanced",
    opponentParticipantId: contest.controllerParticipantId,
    ownerParticipantId: contest.affectedParticipantId,
    processId: continuedContactId,
    publicLabel: "Unbalanced",
  }).effect;
  const nextConditions = controllerWon
    ? [
        ...normalized.unbalancedConditions.filter(
          (condition) => condition.id !== unbalancedConditionId,
        ),
        unbalancedCombatConditionSchema.parse({
          affectedParticipantId: contest.affectedParticipantId,
          canonicalLifecycle: unbalancedLifecycle,
          establishedRound: contest.roundNumber,
          id: unbalancedConditionId,
          modifierValue: -2,
          sourceActionId: "offensive_parry",
          sourceContinuedContactId: continuedContactId,
          status: "active",
        }),
      ]
    : normalized.unbalancedConditions;
  const beforeCursor = normalized.currentCursor ?? {
    participantId: input.rollerParticipantId,
    roundNumber: normalized.roundNumber,
    step: (input.phase === "phase1" ? "P1" : "P2") as CombatRoundCursorStep,
  };
  const command = combatRoundCommandSchema.parse({
    afterCursor: beforeCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      attackResultId: contest.attackResultId,
      contestId: contest.id,
      createdContinuedContactId: controllerWon ? continuedContactId : undefined,
      createdUnbalancedConditionId: controllerWon ? unbalancedConditionId : undefined,
      declarationId: contest.declarationId,
      executionGroupId: input.executionGroupId,
      opportunityId: contest.opportunityId,
      opponentParticipantId: input.opponentParticipantId,
      parryResultId: contest.parryResultId,
      previousContest: contest,
      previousCurrentCursor: normalized.currentCursor,
      previousCurrentStep: normalized.currentStep,
      previousPhaseResolutionCursor: normalized.phaseResolutionCursor,
      previousPhaseResolutionStatuses: normalized.phaseResolutionStatuses,
      previousSelectedParticipantId: normalized.selectedParticipantId,
      previousSelectedStep: normalized.selectedStep,
      resolved: resolved.status === "resolved",
      rollId: roll.id,
    },
    id:
      input.command.commandId ??
      buildCombatRoundCommandId({
        createdAt: input.command.createdAt,
        participantId: input.rollerParticipantId,
        state: normalized,
        type: "roll_offensive_parry_brawling",
      }),
    participantId: input.rollerParticipantId,
    phase: input.phase,
    roundNumber: normalized.roundNumber,
    step: input.phase === "phase1" ? "P1" : "P2",
    type: "roll_offensive_parry_brawling",
  });
  let nextState = combatRoundStateSchema.parse({
    ...normalized,
    commands: [...normalized.commands, command],
    continuedContacts: nextContacts,
    offensiveParryContests: normalized.offensiveParryContests.map((entry) =>
      entry.id === resolved.id ? resolved : entry,
    ),
    unbalancedConditions: nextConditions,
  });
  if (resolved.status === "resolved") {
    nextState = completeCombatRoundPhaseResolutionForParticipant({
      participantId: contest.affectedParticipantId,
      phase: contest.phase,
      state: nextState,
      submittedBy: input.submittedBy,
      updatedAt: input.command.createdAt,
    });
  }
  return appendCombatRoundEventForCommand({
    command,
    draft: {
      actorParticipantId: contest.controllerParticipantId,
      attackResultId: contest.attackResultId,
      attackerParticipantId: contest.affectedParticipantId,
      defenderParticipantId: contest.controllerParticipantId,
      facts: {
        gmReview: {
          affectedTotal: resolved.responderRoll?.finalTotal,
          brawlingContestResultId: contest.brawlingContestResultId,
          contactId: controllerWon ? continuedContactId : undefined,
          controllerTotal: resolved.initiatorRoll?.finalTotal,
          parryQualityModifier: contest.parryQualityModifier,
          parryQualityTableRow: contest.parryQualityTableRow,
          unbalancedConditionId: controllerWon ? unbalancedConditionId : undefined,
        },
        involvedOutcome: {
          affectedParticipantId: contest.affectedParticipantId,
          affectedTotal: resolved.responderRoll?.finalTotal,
          attackResultId: contest.attackResultId,
          brawlingContestResultId: contest.brawlingContestResultId,
          contactEstablished: controllerWon,
          contestId: contest.id,
          controllerParticipantId: contest.controllerParticipantId,
          controllerTotal: resolved.initiatorRoll?.finalTotal,
          difference:
            resolved.initiatorRoll && resolved.responderRoll
              ? resolved.initiatorRoll.finalTotal - resolved.responderRoll.finalTotal
              : undefined,
          resolved: resolved.status === "resolved",
          winnerParticipantId: resolved.winnerParticipantId,
        },
        publicOutcome: {
          contactEstablished: controllerWon,
          resolved: resolved.status === "resolved",
          winnerParticipantId: resolved.winnerParticipantId,
        },
        rollerPrivate: {
          brawlingBaseValue: roll.brawlingBaseValue,
          brawlingSkillId: roll.skillId,
          brawlingSkillXp: roll.brawlingSkillXp,
          characteristicAverage: roll.characteristicAverage,
          effectiveSkillValue: roll.effectiveSkillValue,
          finalTotal: roll.finalTotal,
          generalModifier: roll.generalModifier,
          openEndedD10s: roll.openEndedD10s,
          parryQualityModifier: roll.parryQualityModifier,
          percentageAdjustment: roll.percentageAdjustment,
          percentageModifierTotal: roll.percentageModifierTotal,
          pendingModifiers: roll.pendingModifiers,
          rollD20: roll.rollD20,
          rollTotal: roll.rollTotal,
          skillModifier: roll.skillModifier,
          skillContestCalculation: input.skillContestCalculation,
        },
      },
      involvedParticipantIds: [contest.controllerParticipantId, contest.affectedParticipantId],
      opportunityId: contest.opportunityId,
      ownerParticipantId: input.rollerParticipantId,
      parryResultId: contest.parryResultId,
      phase: contest.phase,
      rollerParticipantId: input.rollerParticipantId,
      sourceIds: [
        contest.id,
        contest.brawlingContestResultId,
        contest.attackResultId,
        contest.parryResultId,
      ],
      sourceToken: `${contest.id}:${input.rollerParticipantId}`,
      status: "recorded",
      step: getCombatStepEventPhaseStep({ kind: "parry", phase: contest.phase }),
      targetParticipantId: contest.affectedParticipantId,
      type: "offensive_parry_brawling",
    },
    state: nextState,
  });
}

export function getCombatRoundDamageResultId(input: { attackResultId: string }): string {
  return `${input.attackResultId}:damage`;
}

/** Deterministic projected identity for the hit-location result owned by an attack. */
export function getCombatRoundHitLocationResultId(input: { attackResultId: string }): string {
  return `${input.attackResultId}:hit-location`;
}

/** Deterministic projected identity for the critical result owned by an attack. */
export function getCombatRoundCriticalResultId(input: { attackResultId: string }): string {
  return `${input.attackResultId}:critical`;
}

/** Deterministic projected identity for the mutable GM review of an attack's damage. */
export function getCombatRoundDamageReviewId(input: { attackResultId: string }): string {
  return `${input.attackResultId}:damage-review`;
}

function rollCombatDamageDie(input: { rng: () => number; sides: number }): number {
  if (!Number.isInteger(input.sides) || input.sides < 1) {
    throw new RangeError("Combat damage die must have at least one side.");
  }

  return Math.min(input.sides, Math.floor(input.rng() * input.sides) + 1);
}

function rollClosedCombatD20(rng: () => number): number {
  return Math.min(20, Math.floor(rng() * 20) + 1);
}

function rollClosedCombatD8(rng: () => number): number {
  return Math.min(8, Math.floor(rng() * 8) + 1);
}

function buildCombatRoundHitLocationRollResult(input: {
  attackResult: CombatRoundAttackRollResult;
  hitLocationRolls?: number[];
  rng?: () => number;
  rolledAt: string;
  rolledByParticipantId: string;
  rolledByUserId?: string;
  roundNumber: number;
  targetLocation?: CombatRoundDamageResult["targetLocation"];
}): CombatRoundHitLocationRollResult {
  const rng = input.rng ?? Math.random;
  const targetedLocation = Boolean(input.targetLocation && input.targetLocation !== "none");
  const rollA = input.hitLocationRolls?.[0] ?? rollClosedCombatD20(rng);
  const rollB = targetedLocation
    ? (input.hitLocationRolls?.[1] ?? rollClosedCombatD20(rng))
    : undefined;
  const hitLocationSelection = resolveHitLocationSelection({
    rollA,
    rollB,
    targetLocation: input.targetLocation,
  });

  return combatRoundHitLocationRollResultSchema.parse({
    attackResultId: getCombatRoundAttackResultId({
      result: input.attackResult,
      roundNumber: input.roundNumber,
    }),
    attackerParticipantId: input.attackResult.attackerParticipantId,
    defenderParticipantId: input.attackResult.defenderParticipantId,
    hitLocationRolls: hitLocationSelection.hitLocationRolls,
    rolledAt: input.rolledAt,
    rolledByParticipantId: input.rolledByParticipantId,
    rolledByUserId: input.rolledByUserId,
    selectedHitLocation: hitLocationSelection.selectedHitLocation,
    selectedHitLocationRoll: hitLocationSelection.selectedHitLocationRoll,
    selectionReason: hitLocationSelection.hitLocationSelectionReason,
    status: "rolled",
    targetLocation: hitLocationSelection.targetLocation,
  });
}

function getHitLocationSelectionFromRoll(
  locationRoll: CombatRoundHitLocationRollResult,
): HitLocationSelection {
  if (
    locationRoll.status !== "rolled" ||
    !locationRoll.selectedHitLocation ||
    !locationRoll.selectedHitLocationRoll ||
    !locationRoll.selectionReason
  ) {
    throw new RangeError("Hit location roll required before resolving damage.");
  }

  return {
    hitLocationRolls: locationRoll.hitLocationRolls,
    hitLocationSelectionReason: locationRoll.selectionReason,
    selectedHitLocation: locationRoll.selectedHitLocation,
    selectedHitLocationRoll: locationRoll.selectedHitLocationRoll,
    targetLocation: locationRoll.targetLocation,
  };
}

function buildCombatRoundCriticalRollResult(input: {
  attackResult: CombatRoundAttackRollResult;
  armorCriticalModifier?: number;
  armorCriticalModifierSource?: CombatRoundCriticalRollResult["armorCriticalModifierSource"];
  criticalDice?: [number, number];
  criticalGrade: string;
  rng?: () => number;
  rolledAt: string;
  rolledByParticipantId: string;
  rolledByUserId?: string;
  roundNumber: number;
  selectedHitLocation?: HitLocation;
}): CombatRoundCriticalRollResult {
  const rng = input.rng ?? Math.random;
  const dieA = input.criticalDice?.[0] ?? rollClosedCombatD8(rng);
  const dieB = input.criticalDice?.[1] ?? rollClosedCombatD8(rng);
  const criticalMetadata = lookupCombatCriticalModifier(input.criticalGrade);
  const armorCriticalModifier = input.armorCriticalModifier ?? 0;
  const criticalDiceTotal = dieA + dieB;

  return combatRoundCriticalRollResultSchema.parse({
    armorCriticalModifier,
    armorCriticalModifierSource: input.armorCriticalModifierSource,
    attackResultId: getCombatRoundAttackResultId({
      result: input.attackResult,
      roundNumber: input.roundNumber,
    }),
    attackerParticipantId: input.attackResult.attackerParticipantId,
    criticalDice: [dieA, dieB],
    criticalDiceTotal,
    criticalGrade: criticalMetadata.criticalGrade,
    criticalTypeModifier: criticalMetadata.criticalTypeModifier,
    defenderParticipantId: input.attackResult.defenderParticipantId,
    finalCriticalRoll:
      criticalDiceTotal + criticalMetadata.criticalTypeModifier - armorCriticalModifier,
    rolledAt: input.rolledAt,
    rolledByParticipantId: input.rolledByParticipantId,
    rolledByUserId: input.rolledByUserId,
    selectedHitLocation: input.selectedHitLocation,
    status: "rolled",
  });
}

export function getCombatRoundArmorCriticalModifierForDamageResult(
  damageResult: CombatRoundDamageResult,
): {
  armorCriticalModifier: number;
  source: CombatRoundCriticalRollResult["armorCriticalModifierSource"];
} {
  const effectiveDamage = getCombatRoundEffectiveDamageResult(damageResult);

  if (!effectiveDamage.effectiveSelectedHitLocation) {
    return {
      armorCriticalModifier: 0,
      source: {
        reason: "Hit location is missing; armor critical modifier is 0.",
        status: "not_applied",
      },
    };
  }

  const mapping = mapHitLocationAndDirectionToArmorRegion({
    direction: effectiveDamage.effectiveAttackDirection,
    hitLocation: effectiveDamage.effectiveSelectedHitLocation,
  });
  const coverage = damageResult.armorCoverage[mapping.armorRegion];

  if (coverage?.criticalModifier !== undefined) {
    return {
      armorCriticalModifier: coverage.criticalModifier,
      source: {
        reason: `${mapping.armorRegionLabel} armor critical modifier ${coverage.criticalModifier} applied.`,
        status: "applied",
      },
    };
  }

  return {
    armorCriticalModifier: 0,
    source: {
      reason: `${mapping.armorRegionLabel} armor critical modifier was not available; using 0.`,
      status: "not_applied",
    },
  };
}

function calculateCombatRoundDamageLookupTotal(input: {
  defenderDm: number;
  dmb: number;
  hitLookupTotal: number;
}): number {
  return input.hitLookupTotal + input.dmb + input.defenderDm;
}

function getCombatRoundDamageMetadataForLookup(damageLookupTotal: number) {
  const damageMetadata = lookupCombatToHitDamageMetadata(damageLookupTotal);
  if (!damageMetadata) {
    throw new RangeError(
      `Combat To Hit damage lookup total ${damageLookupTotal} does not produce damage.`,
    );
  }

  return damageMetadata;
}

export function getCombatRoundGrazeDamageRollContext(input: { defenderDm: number; dmb: number }) {
  const grazingReferenceHitLookupTotal = 12;
  const grazingReferenceDamageLookupTotal = calculateCombatRoundDamageLookupTotal({
    defenderDm: input.defenderDm,
    dmb: input.dmb,
    hitLookupTotal: grazingReferenceHitLookupTotal,
  });
  const grazingReferenceDamageMetadata = getCombatRoundDamageMetadataForLookup(
    grazingReferenceDamageLookupTotal,
  );
  const grazingReferenceDamage = grazingReferenceDamageMetadata.damage;
  const dieSides = Math.max(1, grazingReferenceDamage);

  return {
    diceExpression: `1d${dieSides}`,
    dieSides,
    grazingReferenceDamage,
    grazingReferenceDamageLookupTotal,
    grazingReferenceHitLookupTotal,
    minDamage: grazingReferenceDamageMetadata.minDamage,
  } as const;
}

function combatRoundReviewHasOwnField(
  review: CombatRoundDamageReview | undefined,
  field: keyof CombatRoundDamageReview,
): boolean {
  return Boolean(review && Object.prototype.hasOwnProperty.call(review, field));
}

function hasCombatRoundDamageReviewOverrides(review: CombatRoundDamageReview | undefined): boolean {
  return Boolean(
    review &&
    (review.armorModifierOverride !== undefined ||
      review.attackDirectionOverride !== undefined ||
      review.armorCriticalModifierOverride !== undefined ||
      (review.additionalEffects?.length ?? 0) > 0 ||
      review.criticalLocationOverride !== undefined ||
      review.criticalTypeModifierOverride !== undefined ||
      review.finalCriticalRollOverride !== undefined ||
      review.selectedHitLocationOverride !== undefined ||
      review.totalDamageOverride !== undefined ||
      combatRoundReviewHasOwnField(review, "criticalGradeOverride") ||
      Boolean(review.notes?.trim())),
  );
}

function getCombatRoundReviewedCriticalGrade(input: {
  computedCriticalGrade?: string;
  review?: CombatRoundDamageReview;
  tableCriticalGrade?: string;
}): string | undefined {
  if (combatRoundReviewHasOwnField(input.review, "criticalGradeOverride")) {
    return input.review?.criticalGradeOverride ?? undefined;
  }

  return input.tableCriticalGrade ?? input.computedCriticalGrade;
}

function getCombatRoundCriticalMinimumTotalDamage(review?: CombatRoundDamageReview): {
  minDamageReason?: string;
  minTotalDamage?: number;
} {
  let minTotalDamage = review?.criticalEffectProposal?.minTotalDamage;
  let minDamageReason = review?.criticalEffectProposal?.minDamageReason;

  for (const effect of review?.additionalEffects ?? []) {
    if (effect.minTotalDamage === undefined) {
      continue;
    }

    if (minTotalDamage === undefined || effect.minTotalDamage > minTotalDamage) {
      minTotalDamage = effect.minTotalDamage;
      minDamageReason = effect.minDamageReason;
    }
  }

  return {
    minDamageReason,
    minTotalDamage,
  };
}

function getCombatRoundMaxDamageCap(input: {
  attackerStrengthGm?: number;
  maxDamageNote?: string;
}): number | undefined {
  if (
    input.maxDamageNote !== COMBAT_ROUND_STRENGTH_GM_MAX_DAMAGE_NOTE ||
    input.attackerStrengthGm === undefined
  ) {
    return undefined;
  }

  return 17 + input.attackerStrengthGm;
}

function applyCombatRoundMaxDamageCap(input: { maxDamageCap?: number; rawTotalDamage: number }): {
  cappedTotalDamage?: number;
  maxDamageApplied: boolean;
  totalDamage: number;
} {
  if (input.maxDamageCap === undefined) {
    return {
      maxDamageApplied: false,
      totalDamage: input.rawTotalDamage,
    };
  }

  const cappedTotalDamage = Math.min(input.rawTotalDamage, input.maxDamageCap);

  return {
    cappedTotalDamage,
    maxDamageApplied: input.rawTotalDamage > input.maxDamageCap,
    totalDamage: cappedTotalDamage,
  };
}

export function mapHitLocationAndDirectionToArmorRegion(input: {
  direction: CombatRoundAttackDirection;
  hitLocation: HitLocation;
}): {
  armorRegion: CombatRoundArmorRegion;
  armorRegionLabel: string;
  note?: string;
} {
  const { direction, hitLocation } = input;

  switch (hitLocation) {
    case "head":
      return { armorRegion: "head", armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.head };
    case "chest":
      return { armorRegion: "chest", armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.chest };
    case "abdomen":
      return {
        armorRegion: "abdomen",
        armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.abdomen,
      };
    case "leftArm":
    case "rightArm":
      return direction === "front"
        ? {
            armorRegion: "frontArm",
            armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.frontArm,
          }
        : {
            armorRegion: "backArm",
            armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.backArm,
          };
    case "upperLeftLeg":
    case "upperRightLeg":
      return direction === "front"
        ? {
            armorRegion: "frontThigh",
            armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.frontThigh,
          }
        : {
            armorRegion: "backThigh",
            armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.backThigh,
          };
    case "lowerLeftLeg":
    case "lowerRightLeg":
      return direction === "front"
        ? {
            armorRegion: "frontFoot",
            armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.frontFoot,
          }
        : {
            armorRegion: "backFoot",
            armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.backFoot,
          };
    case "leftLeg":
    case "rightLeg":
      return direction === "front"
        ? {
            armorRegion: "frontThigh",
            armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.frontThigh,
            note: "Legacy whole-leg hit mapped to front thigh; review as upper or lower leg when critical or armor precision matters.",
          }
        : {
            armorRegion: "backThigh",
            armorRegionLabel: COMBAT_ROUND_ARMOR_REGION_LABELS.backThigh,
            note: "Legacy whole-leg hit mapped to back thigh; review as upper or lower leg when critical or armor precision matters.",
          };
  }
}

export function parseCombatRoundArmorCoverageLabel(value: string | undefined | null): {
  armorClass?: CombatArmorModifierClass;
  armorValue?: number;
} {
  if (!value) {
    return {};
  }

  const match = value.trim().match(/^(\d+)\s*([A-E])?$/i);
  if (!match) {
    return {};
  }

  const armorValue = Number(match[1]);
  const armorClass = normalizeCombatArmorModifierClass(match[2]);

  return {
    armorClass,
    armorValue: Number.isFinite(armorValue) ? armorValue : undefined,
  };
}

function formatCombatRoundArmorCoverageLabel(input: {
  armorClass?: CombatArmorModifierClass;
  armorValue?: number;
}): string | undefined {
  if (input.armorValue === undefined) {
    return undefined;
  }

  return `${input.armorValue}${input.armorClass ?? ""}`;
}

function resolveCombatRoundArmorContext(input: {
  armorCoverage?: CombatRoundDamageArmorCoverage;
  attackDirection: CombatRoundAttackDirection;
  selectedHitLocation?: HitLocation;
  weaponArmorClass?: CombatArmorModifierClass;
}): {
  armorClass?: CombatArmorModifierClass;
  armorCoverageLabel?: string;
  armorDamageModifier: number;
  armorModifierSource: CombatRoundDamageResult["armorModifierSource"];
  armorRegion?: CombatRoundArmorRegion;
  armorRegionLabel?: string;
  armorValue: number;
  armorWarnings: string[];
  weaponArmorClass?: CombatArmorModifierClass;
} {
  const armorCoverage = combatRoundDamageArmorCoverageSchema.parse(input.armorCoverage);
  const warnings: string[] = [];

  if (!input.selectedHitLocation) {
    warnings.push("Hit location is missing; armor was not applied.");
    return {
      armorDamageModifier: 0,
      armorModifierSource: {
        label: "Armor not applied",
        reason: "Hit location is missing.",
        status: "not_applied",
      },
      armorValue: 0,
      armorWarnings: warnings,
      weaponArmorClass: input.weaponArmorClass,
    };
  }

  const mapping = mapHitLocationAndDirectionToArmorRegion({
    direction: input.attackDirection,
    hitLocation: input.selectedHitLocation,
  });
  if (mapping.note) {
    warnings.push(mapping.note);
  }

  const coverage = armorCoverage[mapping.armorRegion];
  const parsedCoverage = parseCombatRoundArmorCoverageLabel(coverage?.coverageLabel);
  const armorValue = coverage?.value ?? parsedCoverage.armorValue ?? 0;
  const armorClass = coverage?.armorClass ?? parsedCoverage.armorClass ?? "A";
  const armorCoverageLabel =
    coverage?.coverageLabel ??
    formatCombatRoundArmorCoverageLabel({ armorClass, armorValue }) ??
    `${armorValue}${armorClass}`;

  if (!coverage) {
    warnings.push(`${mapping.armorRegionLabel} armor coverage was not available; using 0A.`);
  }

  if (!input.weaponArmorClass) {
    warnings.push("Weapon armor class was not available; armor table modifier is 0.");
  }

  const armorDamageModifier = input.weaponArmorClass
    ? lookupCombatArmorModifier({
        armorClass,
        weaponArmorClass: input.weaponArmorClass,
      })
    : 0;
  const label = `${mapping.armorRegionLabel.toLowerCase()}/${input.attackDirection} ${armorCoverageLabel}`;

  return {
    armorClass,
    armorCoverageLabel,
    armorDamageModifier,
    armorModifierSource: {
      armorClass,
      label,
      reason: coverage
        ? undefined
        : `${mapping.armorRegionLabel} armor coverage was not available; using 0A.`,
      status: coverage ? "applied" : "not_applied",
      weaponArmorClass: input.weaponArmorClass,
    },
    armorRegion: mapping.armorRegion,
    armorRegionLabel: mapping.armorRegionLabel,
    armorValue,
    armorWarnings: warnings,
    weaponArmorClass: input.weaponArmorClass,
  };
}

function calculateCombatRoundArmorAdjustedDamage(input: {
  armorDamageModifier: number;
  armorValue: number;
  tableDamage: number;
  tableMinDamage?: number;
}): {
  minimumDamageAfterArmor?: number;
  minimumDamageBeforeArmor?: number;
  provisionalDamageAfterArmor: number;
  rawTotalDamage: number;
} {
  const provisionalDamageAfterArmor =
    input.tableDamage - input.armorValue + input.armorDamageModifier;
  const minimumDamageAfterArmor =
    input.tableMinDamage === undefined
      ? undefined
      : Math.max(0, input.tableMinDamage + input.armorDamageModifier);
  const rawTotalDamage = Math.max(provisionalDamageAfterArmor, minimumDamageAfterArmor ?? 0, 0);

  return {
    minimumDamageAfterArmor,
    minimumDamageBeforeArmor: input.tableMinDamage,
    provisionalDamageAfterArmor,
    rawTotalDamage,
  };
}

export function getCombatRoundEffectiveDamageResult(
  damageResult: CombatRoundDamageResult,
): CombatRoundEffectiveDamageResult {
  const computedArmorModifier = damageResult.armorModifier ?? 0;
  const computedAttackDirection = damageResult.attackDirection;
  const effectiveAttackDirection =
    damageResult.review?.attackDirectionOverride ?? computedAttackDirection;
  const computedSelectedHitLocation = damageResult.selectedHitLocation;
  const effectiveSelectedHitLocation =
    damageResult.review?.selectedHitLocationOverride ?? computedSelectedHitLocation;
  const hitLookupTotal = damageResult.hitLookupTotal ?? damageResult.lookupTotal;
  const hasTotalDamageOverride = damageResult.review?.totalDamageOverride !== undefined;
  const computedDamageRoll = damageResult.damageRoll;
  const armorContext = resolveCombatRoundArmorContext({
    armorCoverage: damageResult.armorCoverage,
    attackDirection: effectiveAttackDirection,
    selectedHitLocation: effectiveSelectedHitLocation,
    weaponArmorClass: damageResult.weaponArmorClass,
  });
  const computedArmorContext = {
    armorDamageModifier: damageResult.armorDamageModifier ?? computedArmorModifier,
    armorValue: damageResult.armorValue ?? 0,
    minimumDamageAfterArmor: damageResult.minimumDamageAfterArmor,
    provisionalDamageAfterArmor: damageResult.provisionalDamageAfterArmor,
  };
  const effectiveArmorModifier =
    damageResult.review?.armorModifierOverride ?? armorContext.armorDamageModifier;
  let effectiveDamageLookupTotal = damageResult.damageLookupTotal;
  let effectiveTableDamage = damageResult.tableDamage ?? damageResult.tableDamageModifier;
  let effectiveCriticalGrade = getCombatRoundReviewedCriticalGrade({
    computedCriticalGrade: damageResult.criticalGrade,
    review: damageResult.review,
  });
  let effectiveMaxDamageNote = damageResult.maxDamageNote;
  let effectiveMinDamage = damageResult.minDamage;
  let effectiveMinimumDamageAfterArmor = damageResult.minimumDamageAfterArmor;
  let effectiveProvisionalDamageAfterArmor = damageResult.provisionalDamageAfterArmor;
  let effectiveDamageRoll: CombatRoundDamageResult["damageRoll"] = computedDamageRoll;
  let effectiveRawTotalDamage =
    damageResult.review?.totalDamageOverride ??
    damageResult.rawTotalDamage ??
    damageResult.totalDamage;
  let requiresTotalDamageOverride = false;
  const computedMaxDamageCap =
    damageResult.maxDamageCap ??
    getCombatRoundMaxDamageCap({
      attackerStrengthGm: damageResult.attackerStrengthGm,
      maxDamageNote: damageResult.maxDamageNote,
    });
  const computedCappedDamage = applyCombatRoundMaxDamageCap({
    maxDamageCap: computedMaxDamageCap,
    rawTotalDamage: damageResult.rawTotalDamage ?? damageResult.totalDamage,
  });

  if (hitLookupTotal !== undefined) {
    if (damageResult.grazing) {
      const grazingReferenceHitLookupTotal = 12;
      effectiveDamageLookupTotal = calculateCombatRoundDamageLookupTotal({
        defenderDm: damageResult.defenderDm,
        dmb: damageResult.dmb,
        hitLookupTotal: grazingReferenceHitLookupTotal,
      });
      const metadata = getCombatRoundDamageMetadataForLookup(effectiveDamageLookupTotal);
      effectiveTableDamage = metadata.damage;
      effectiveMaxDamageNote = metadata.maxDamageNote;
      effectiveMinDamage = metadata.minDamage;
      effectiveCriticalGrade = getCombatRoundReviewedCriticalGrade({
        computedCriticalGrade: damageResult.criticalGrade,
        review: damageResult.review,
        tableCriticalGrade: undefined,
      });

      const referenceTableDamage = metadata.damage;
      const dieSides = Math.max(1, referenceTableDamage);
      const existingRoll =
        computedDamageRoll.rolls?.[0] ?? computedDamageRoll.total ?? damageResult.totalDamage;
      const canKeepExistingRoll =
        Number.isInteger(existingRoll) && existingRoll >= 1 && existingRoll <= dieSides;
      requiresTotalDamageOverride = !hasTotalDamageOverride && !canKeepExistingRoll;
      const rawGrazingDamage =
        canKeepExistingRoll && !hasTotalDamageOverride ? existingRoll : computedDamageRoll.total;
      const adjustedGrazingDamage =
        rawGrazingDamage !== undefined
          ? calculateCombatRoundArmorAdjustedDamage({
              armorDamageModifier: effectiveArmorModifier,
              armorValue: armorContext.armorValue,
              tableDamage: rawGrazingDamage,
              tableMinDamage: metadata.minDamage,
            })
          : undefined;
      effectiveMinimumDamageAfterArmor = adjustedGrazingDamage?.minimumDamageAfterArmor;
      effectiveProvisionalDamageAfterArmor = adjustedGrazingDamage?.provisionalDamageAfterArmor;
      effectiveRawTotalDamage = hasTotalDamageOverride
        ? (damageResult.review?.totalDamageOverride ?? 0)
        : (adjustedGrazingDamage?.rawTotalDamage ?? damageResult.totalDamage);
      effectiveDamageRoll = {
        derivedFromLookupTotal: grazingReferenceHitLookupTotal,
        derivedNormalDamageTotal: referenceTableDamage,
        diceExpression: `1d${dieSides}`,
        grazingDieSides: dieSides,
        grazingReferenceDamage: referenceTableDamage,
        grazingReferenceDamageLookupTotal: effectiveDamageLookupTotal,
        grazingReferenceHitLookupTotal,
        grazingReferenceTableDamage: referenceTableDamage,
        rawGrazingDamage,
        required: true,
        rolls: canKeepExistingRoll && !hasTotalDamageOverride ? [existingRoll] : undefined,
        total: hasTotalDamageOverride ? rawGrazingDamage : existingRoll,
      };
    } else {
      effectiveDamageLookupTotal = calculateCombatRoundDamageLookupTotal({
        defenderDm: damageResult.defenderDm,
        dmb: damageResult.dmb,
        hitLookupTotal,
      });
      const metadata = getCombatRoundDamageMetadataForLookup(effectiveDamageLookupTotal);
      effectiveTableDamage = metadata.damage;
      effectiveMaxDamageNote = metadata.maxDamageNote;
      effectiveMinDamage = metadata.minDamage;
      effectiveCriticalGrade = getCombatRoundReviewedCriticalGrade({
        computedCriticalGrade: damageResult.criticalGrade,
        review: damageResult.review,
        tableCriticalGrade: metadata.criticalGrade,
      });
      const adjustedDamage = calculateCombatRoundArmorAdjustedDamage({
        armorDamageModifier: effectiveArmorModifier,
        armorValue: armorContext.armorValue,
        tableDamage: metadata.damage,
        tableMinDamage: metadata.minDamage,
      });
      effectiveMinimumDamageAfterArmor = adjustedDamage.minimumDamageAfterArmor;
      effectiveProvisionalDamageAfterArmor = adjustedDamage.provisionalDamageAfterArmor;
      effectiveRawTotalDamage =
        damageResult.review?.totalDamageOverride ?? adjustedDamage.rawTotalDamage;
      effectiveDamageRoll = {
        required: false,
      };
    }
  }

  const effectiveMaxDamageCap = getCombatRoundMaxDamageCap({
    attackerStrengthGm: damageResult.attackerStrengthGm,
    maxDamageNote: effectiveMaxDamageNote,
  });
  const effectiveCappedDamage = applyCombatRoundMaxDamageCap({
    maxDamageCap: effectiveMaxDamageCap,
    rawTotalDamage: effectiveRawTotalDamage,
  });
  const preCriticalEffectiveDamage = hasTotalDamageOverride
    ? effectiveRawTotalDamage
    : effectiveCappedDamage.totalDamage;
  const criticalMinimum = getCombatRoundCriticalMinimumTotalDamage(damageResult.review);
  const criticalMinTotalDamage = criticalMinimum.minTotalDamage;
  const criticalMinApplied =
    criticalMinTotalDamage !== undefined && criticalMinTotalDamage > preCriticalEffectiveDamage;
  const criticalMinExtra = criticalMinApplied
    ? criticalMinTotalDamage - preCriticalEffectiveDamage
    : undefined;
  const effectiveTotalDamage = criticalMinApplied
    ? criticalMinTotalDamage
    : preCriticalEffectiveDamage;
  const effectiveCappedTotalDamage = hasTotalDamageOverride
    ? undefined
    : effectiveCappedDamage.cappedTotalDamage;
  const effectiveMaxDamageApplied = hasTotalDamageOverride
    ? false
    : effectiveCappedDamage.maxDamageApplied;

  return {
    computedArmorModifier,
    computedAttackDirection,
    computedCriticalGrade: damageResult.criticalGrade,
    computedDamageLookupTotal: damageResult.damageLookupTotal,
    computedCappedTotalDamage: computedCappedDamage.cappedTotalDamage,
    computedMaxDamageApplied: computedCappedDamage.maxDamageApplied,
    computedMaxDamageCap,
    computedMaxDamageNote: damageResult.maxDamageNote,
    computedMinDamage: damageResult.minDamage,
    computedMinimumDamageAfterArmor: computedArmorContext.minimumDamageAfterArmor,
    computedProvisionalDamageAfterArmor: computedArmorContext.provisionalDamageAfterArmor,
    computedSelectedHitLocation,
    computedTableDamage: damageResult.tableDamage ?? damageResult.tableDamageModifier,
    computedTotalDamage: damageResult.totalDamage,
    preCriticalEffectiveDamage,
    criticalMinTotalDamage,
    criticalMinApplied,
    criticalMinExtra,
    finalCommittedDamage: effectiveTotalDamage,
    effectiveArmorClass: armorContext.armorClass,
    effectiveArmorCoverageLabel: armorContext.armorCoverageLabel,
    effectiveArmorModifier,
    effectiveArmorRegion: armorContext.armorRegion,
    effectiveArmorRegionLabel: armorContext.armorRegionLabel,
    effectiveArmorValue: armorContext.armorValue,
    effectiveArmorWarnings: armorContext.armorWarnings,
    effectiveAttackDirection,
    effectiveCriticalGrade,
    effectiveDamageLookupTotal,
    effectiveDamageRoll,
    effectiveCappedTotalDamage,
    effectiveMaxDamageApplied,
    effectiveMaxDamageCap,
    effectiveMaxDamageNote,
    effectiveMinDamage,
    effectiveMinimumDamageAfterArmor,
    effectiveProvisionalDamageAfterArmor,
    effectiveRawTotalDamage,
    effectiveSelectedHitLocation,
    effectiveTableDamage,
    effectiveTotalDamage,
    effectiveWeaponArmorClass: armorContext.weaponArmorClass,
    hasReviewOverrides: hasCombatRoundDamageReviewOverrides(damageResult.review),
    requiresTotalDamageOverride,
    review: damageResult.review,
  };
}

export function getCombatRoundEffectiveCriticalRoll(input: {
  criticalRoll?: CombatRoundCriticalRollResult;
  review?: CombatRoundDamageReview;
}): {
  armorCriticalModifier?: number;
  criticalLocation?: HitLocation;
  criticalTypeModifier?: number;
  finalCriticalRoll?: number;
  hasReviewOverrides: boolean;
} {
  const criticalRoll = input.criticalRoll;
  const review = input.review;

  return {
    armorCriticalModifier:
      review?.armorCriticalModifierOverride ?? criticalRoll?.armorCriticalModifier,
    criticalLocation: review?.criticalLocationOverride ?? criticalRoll?.selectedHitLocation,
    criticalTypeModifier:
      review?.criticalTypeModifierOverride ?? criticalRoll?.criticalTypeModifier,
    finalCriticalRoll: review?.finalCriticalRollOverride ?? criticalRoll?.finalCriticalRoll,
    hasReviewOverrides: Boolean(
      review?.armorCriticalModifierOverride !== undefined ||
      review?.criticalLocationOverride !== undefined ||
      review?.criticalTypeModifierOverride !== undefined ||
      review?.finalCriticalRollOverride !== undefined,
    ),
  };
}

export function getCombatRoundDamageSubstate(
  resolution?: CombatRoundPhaseResolutionResult,
): CombatRoundDamageSubstate {
  if (!resolution) {
    return "location_pending";
  }

  if (resolution.damageProposal.status === "committed") {
    return "committed";
  }

  if (resolution.hitLocationRoll.status !== "rolled") {
    return "location_pending";
  }

  if (!resolution.damageResult) {
    return "location_rolled";
  }

  if (resolution.criticalRoll.status === "pending") {
    return "critical_pending";
  }

  if (resolution.criticalRoll.status === "rolled") {
    return "critical_rolled";
  }

  if (resolution.damageProposal.status === "drafted") {
    return "review_ready";
  }

  return "damage_proposal_ready";
}

export function buildCombatRoundDamageResult(input: {
  armorCoverage?: CombatRoundDamageArmorCoverage;
  armorModifier?: number;
  armorModifierSource?: CombatRoundDamageResult["armorModifierSource"];
  attackDirection?: CombatRoundAttackDirection;
  attackerStrengthGm?: number;
  attackResult: CombatRoundAttackRollResult;
  createdAt: string;
  createdByUserId?: string;
  defenderDm: number;
  dmb: number;
  hitLocationSelection: HitLocationSelection;
  rng?: () => number;
  roundNumber: number;
  weaponArmorClass?: CombatArmorModifierClass;
}): CombatRoundDamageResult {
  if (!input.attackResult.hit) {
    throw new RangeError("Damage cannot be resolved for a missed attack.");
  }

  const hitLookupTotal = input.attackResult.lookupTotal;
  const rng = input.rng ?? Math.random;
  const hitLocationSelection = input.hitLocationSelection;
  const attackDirection = input.attackDirection ?? "front";
  const armorContext = resolveCombatRoundArmorContext({
    armorCoverage: input.armorCoverage,
    attackDirection,
    selectedHitLocation: hitLocationSelection.selectedHitLocation,
    weaponArmorClass: input.weaponArmorClass,
  });
  const armorModifier = input.armorModifier ?? armorContext.armorDamageModifier;
  const armorModifierSource =
    input.armorModifierSource ??
    (input.armorModifier !== undefined
      ? {
          ...armorContext.armorModifierSource,
          label: armorContext.armorModifierSource.label ?? "Manual armor modifier",
        }
      : armorContext.armorModifierSource);
  const normalDamageLookupTotal = calculateCombatRoundDamageLookupTotal({
    defenderDm: input.defenderDm,
    dmb: input.dmb,
    hitLookupTotal,
  });
  let damageRoll: CombatRoundDamageResult["damageRoll"] = {
    required: false,
  };
  let damageRollTotal = 0;
  let damageLookupTotal = normalDamageLookupTotal;
  let tableDamage: number;
  let criticalGrade: string | undefined;
  let maxDamageNote: string | undefined;
  let minDamage: number | undefined;

  if (input.attackResult.grazing) {
    const grazingContext = getCombatRoundGrazeDamageRollContext({
      defenderDm: input.defenderDm,
      dmb: input.dmb,
    });

    damageRollTotal = rollCombatDamageDie({
      rng,
      sides: grazingContext.dieSides,
    });
    damageLookupTotal = grazingContext.grazingReferenceDamageLookupTotal;
    tableDamage = grazingContext.grazingReferenceDamage;
    minDamage = grazingContext.minDamage;
    damageRoll = {
      derivedFromLookupTotal: grazingContext.grazingReferenceHitLookupTotal,
      derivedNormalDamageTotal: grazingContext.grazingReferenceDamage,
      diceExpression: grazingContext.diceExpression,
      grazingDieSides: grazingContext.dieSides,
      grazingReferenceDamage: grazingContext.grazingReferenceDamage,
      grazingReferenceDamageLookupTotal: grazingContext.grazingReferenceDamageLookupTotal,
      grazingReferenceHitLookupTotal: grazingContext.grazingReferenceHitLookupTotal,
      grazingReferenceTableDamage: grazingContext.grazingReferenceDamage,
      rawGrazingDamage: damageRollTotal,
      required: true,
      rolls: [damageRollTotal],
      total: damageRollTotal,
    };
  } else {
    const damageMetadata = getCombatRoundDamageMetadataForLookup(normalDamageLookupTotal);
    tableDamage = damageMetadata.damage;
    criticalGrade = damageMetadata.criticalGrade;
    maxDamageNote = damageMetadata.maxDamageNote;
    minDamage = damageMetadata.minDamage;
  }

  const adjustedDamage = input.attackResult.grazing
    ? calculateCombatRoundArmorAdjustedDamage({
        armorDamageModifier: armorModifier,
        armorValue: armorContext.armorValue,
        tableDamage: damageRollTotal,
        tableMinDamage: minDamage,
      })
    : calculateCombatRoundArmorAdjustedDamage({
        armorDamageModifier: armorModifier,
        armorValue: armorContext.armorValue,
        tableDamage,
        tableMinDamage: minDamage,
      });
  const totalDamage = adjustedDamage.rawTotalDamage;
  const maxDamageCap = getCombatRoundMaxDamageCap({
    attackerStrengthGm: input.attackerStrengthGm,
    maxDamageNote,
  });
  const cappedDamage = applyCombatRoundMaxDamageCap({
    maxDamageCap,
    rawTotalDamage: totalDamage,
  });
  const attackResultId = getCombatRoundAttackResultId({
    result: input.attackResult,
    roundNumber: input.roundNumber,
  });

  return combatRoundDamageResultSchema.parse({
    armorAppliesToDamage: true,
    armorAppliesToMinimumDamage: true,
    armorClass: armorContext.armorClass,
    armorCoverage: input.armorCoverage,
    armorCoverageLabel: armorContext.armorCoverageLabel,
    armorDamageModifier: armorModifier,
    armorModifier,
    armorModifierSource,
    armorRegion: armorContext.armorRegion,
    armorRegionLabel: armorContext.armorRegionLabel,
    armorValue: armorContext.armorValue,
    armorWarnings: armorContext.armorWarnings,
    attackDirection,
    attackResultId,
    attackerParticipantId: input.attackResult.attackerParticipantId,
    attackerStrengthGm: input.attackerStrengthGm,
    cappedTotalDamage: cappedDamage.cappedTotalDamage,
    createdAt: input.createdAt,
    createdByUserId: input.createdByUserId,
    criticalGrade,
    damageRoll,
    damageLookupTotal,
    defenderDm: input.defenderDm,
    defenderParticipantId: input.attackResult.defenderParticipantId,
    dmb: input.dmb,
    grazing: input.attackResult.grazing,
    hitLocationRolls: hitLocationSelection.hitLocationRolls,
    hitLocationSelectionReason: hitLocationSelection.hitLocationSelectionReason,
    hitLookupTotal,
    kind: "damage_result",
    maxDamageApplied: cappedDamage.maxDamageApplied,
    maxDamageCap,
    maxDamageNote,
    minDamage,
    parryResultId: `${attackResultId}:parry`,
    phase: input.attackResult.phase,
    selectedHitLocation: hitLocationSelection.selectedHitLocation,
    selectedHitLocationRoll: hitLocationSelection.selectedHitLocationRoll,
    minimumDamageAfterArmor: adjustedDamage.minimumDamageAfterArmor,
    minimumDamageBeforeArmor: adjustedDamage.minimumDamageBeforeArmor,
    provisionalDamageAfterArmor: adjustedDamage.provisionalDamageAfterArmor,
    rawTableDamage: tableDamage,
    tableDamage,
    targetLocation: hitLocationSelection.targetLocation,
    rawTotalDamage: totalDamage,
    totalDamage,
    weaponArmorClass: input.weaponArmorClass,
    weaponName: input.attackResult.weaponName,
  });
}

function recordCombatRoundDamageResolution(input: {
  attackResult: CombatRoundAttackRollResult;
  damageResult: CombatRoundDamageResult;
  state: CombatRoundState;
  updatedAt: string;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const existing =
    getCombatRoundPhaseResolutionResultForAttack({
      attackResult: input.attackResult,
      state: normalized,
    }) ??
    buildCombatRoundPhaseResolutionResult({
      attackResult: input.attackResult,
      roundNumber: normalized.roundNumber,
      state: normalized,
      updatedAt: input.updatedAt,
    });
  const nextResult = combatRoundPhaseResolutionResultSchema.parse({
    ...existing,
    criticalRoll: input.damageResult.criticalGrade
      ? {
          status: "pending",
        }
      : {
          status: "not_required",
        },
    damageProposal: {
      committedCombatEffectIds: [],
      proposedEffects: [],
      status: "drafted",
    },
    damageResult: input.damageResult,
    damageRoll: {
      notes: "Damage resolved. Combat Effects are not created yet.",
      status: "rolled",
      total: input.damageResult.totalDamage,
    },
    updatedAt: input.updatedAt,
  });

  return refreshCombatRoundReactiveAttackPhase2InitiativeModifiers(
    upsertCombatRoundPhaseResolutionResults({
      results: [nextResult],
      state: normalized,
    }),
  );
}

function recordCombatRoundResolveDamageCommand(input: {
  attackResult: CombatRoundAttackRollResult;
  command: {
    commandId?: string;
    createdAt: string;
    createdByUserId?: string;
  };
  damageResult: CombatRoundDamageResult;
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const beforeCursor = combatRoundCursorSchema.parse({
    participantId: input.attackResult.defenderParticipantId,
    roundNumber: normalized.roundNumber,
    step: getCombatRoundDamageCursorStepForPhase(input.attackResult.phase),
  });
  const afterCursor = beforeCursor;
  const commandType = "resolve_damage" satisfies CombatRoundCommandType;
  const command = combatRoundCommandSchema.parse({
    afterCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      attackResultId: input.damageResult.attackResultId,
      attackerParticipantId: input.attackResult.attackerParticipantId,
      criticalGrade: input.damageResult.criticalGrade,
      damageResultId: getCombatRoundDamageResultId({
        attackResultId: input.damageResult.attackResultId,
      }),
      defenderParticipantId: input.attackResult.defenderParticipantId,
      hitLocationRolls: input.damageResult.hitLocationRolls,
      hitLocationSelectionReason: input.damageResult.hitLocationSelectionReason,
      selectedHitLocation: input.damageResult.selectedHitLocation,
      selectedHitLocationRoll: input.damageResult.selectedHitLocationRoll,
      targetLocation: input.damageResult.targetLocation,
      armorClass: input.damageResult.armorClass,
      armorCoverageLabel: input.damageResult.armorCoverageLabel,
      armorDamageModifier: input.damageResult.armorDamageModifier,
      armorModifier: input.damageResult.armorModifier,
      armorModifierSource: input.damageResult.armorModifierSource,
      armorRegion: input.damageResult.armorRegion,
      armorRegionLabel: input.damageResult.armorRegionLabel,
      armorValue: input.damageResult.armorValue,
      attackDirection: input.damageResult.attackDirection,
      minimumDamageAfterArmor: input.damageResult.minimumDamageAfterArmor,
      provisionalDamageAfterArmor: input.damageResult.provisionalDamageAfterArmor,
      status: "resolved",
      totalDamage: input.damageResult.totalDamage,
      weaponArmorClass: input.damageResult.weaponArmorClass,
      ...(afterCursor.participantId
        ? {
            nextStepOpened: {
              participantId: afterCursor.participantId,
              step: afterCursor.step,
            },
          }
        : {}),
    },
    id:
      input.command.commandId ??
      buildCombatRoundCommandId({
        createdAt: input.command.createdAt,
        participantId: input.attackResult.defenderParticipantId,
        state: normalized,
        type: commandType,
      }),
    participantId: input.attackResult.defenderParticipantId,
    phase: input.attackResult.phase,
    roundNumber: normalized.roundNumber,
    step: beforeCursor.step,
    type: commandType,
  });
  const selectedStep = getCombatRoundStepForCursorStep(command.afterCursor.step);

  const stateWithCommand = {
    ...normalized,
    commands: [...normalized.commands, command],
    currentCursor: command.afterCursor,
    currentStep: selectedStep,
    selectedParticipantId: command.afterCursor.participantId ?? normalized.selectedParticipantId,
    selectedStep,
  };

  const damageResultId = getCombatRoundDamageResultId({
    attackResultId: input.damageResult.attackResultId,
  });

  return appendCombatRoundEventForCommand({
    command,
    draft: {
      actorParticipantId: input.attackResult.attackerParticipantId,
      attackResultId: input.damageResult.attackResultId,
      attackerParticipantId: input.attackResult.attackerParticipantId,
      damageResultId,
      defenderParticipantId: input.attackResult.defenderParticipantId,
      facts: {
        gmReview: input.damageResult.review ?? {},
        involvedOutcome: {
          attackResultId: input.damageResult.attackResultId,
          criticalGrade: input.damageResult.criticalGrade,
          ...(input.damageResult.grazing
            ? {
                damageRollExpression: input.damageResult.damageRoll.diceExpression,
                grazing: true,
                rawGrazingDamage: input.damageResult.damageRoll.rawGrazingDamage,
              }
            : {}),
          selectedHitLocation: input.damageResult.selectedHitLocation,
          totalDamage: input.damageResult.totalDamage,
        },
        rollerPrivate: {
          armorModifier: input.damageResult.armorModifier,
          damageLookupTotal: input.damageResult.damageLookupTotal,
          damageRoll: input.damageResult.damageRoll,
          defenderDm: input.damageResult.defenderDm,
          dmb: input.damageResult.dmb,
          hitLookupTotal: input.damageResult.hitLookupTotal,
        },
      },
      ownerParticipantId: input.attackResult.defenderParticipantId,
      phase: input.attackResult.phase,
      rollerParticipantId: input.attackResult.attackerParticipantId,
      sourceIds: [input.damageResult.attackResultId, damageResultId],
      status: "proposed",
      step: getCombatStepEventPhaseStep({ kind: "damage", phase: input.attackResult.phase }),
      targetParticipantId: input.attackResult.defenderParticipantId,
      type: "damage_proposed",
    },
    state: stateWithCommand,
  });
}

