function undoCombatRoundOffensiveParryBrawlingCommandAtIndex(input: {
  commandIndex: number;
  state: CombatRoundState;
}): CombatRoundState | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const command = normalized.commands[input.commandIndex];
  if (!command || command.type !== "roll_offensive_parry_brawling") return undefined;

  const previousContest = offensiveParryContestSchema.safeParse(command.facts.previousContest);
  if (!previousContest.success) return undefined;
  const previousCurrentCursor = combatRoundCursorSchema.safeParse(
    command.facts.previousCurrentCursor,
  );
  const previousPhaseResolutionCursor = combatRoundPhaseResolutionCursorSchema.safeParse(
    command.facts.previousPhaseResolutionCursor,
  );
  const previousPhaseResolutionStatuses = combatRoundPhaseResolutionStatusesSchema.safeParse(
    command.facts.previousPhaseResolutionStatuses,
  );
  const previousCurrentStep = combatRoundStepSchema.safeParse(command.facts.previousCurrentStep);
  const previousSelectedStep = combatRoundStepSchema.safeParse(command.facts.previousSelectedStep);
  const createdContinuedContactId =
    typeof command.facts.createdContinuedContactId === "string"
      ? command.facts.createdContinuedContactId
      : undefined;
  const createdUnbalancedConditionId =
    typeof command.facts.createdUnbalancedConditionId === "string"
      ? command.facts.createdUnbalancedConditionId
      : undefined;
  const previousSelectedParticipantId =
    typeof command.facts.previousSelectedParticipantId === "string"
      ? command.facts.previousSelectedParticipantId
      : undefined;

  return combatRoundStateSchema.parse({
    ...normalized,
    commands: normalized.commands.filter((_, index) => index !== input.commandIndex),
    continuedContacts: normalized.continuedContacts.filter(
      (contact) => contact.id !== createdContinuedContactId,
    ),
    currentCursor: previousCurrentCursor.success ? previousCurrentCursor.data : undefined,
    currentStep: previousCurrentStep.success
      ? previousCurrentStep.data
      : getCombatRoundStepForCursorStep(command.beforeCursor.step),
    offensiveParryContests: normalized.offensiveParryContests.map((contest) =>
      contest.id === previousContest.data.id ? previousContest.data : contest,
    ),
    phaseResolutionCursor: previousPhaseResolutionCursor.success
      ? previousPhaseResolutionCursor.data
      : undefined,
    phaseResolutionStatuses: previousPhaseResolutionStatuses.success
      ? previousPhaseResolutionStatuses.data
      : normalized.phaseResolutionStatuses,
    selectedParticipantId: previousSelectedParticipantId,
    selectedStep: previousSelectedStep.success ? previousSelectedStep.data : undefined,
    unbalancedConditions: normalized.unbalancedConditions.filter(
      (condition) => condition.id !== createdUnbalancedConditionId,
    ),
  });
}

function undoContinuedContactMaintenanceCommandAtIndex(input: {
  commandIndex: number;
  state: CombatRoundState;
}): CombatRoundState | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const command = normalized.commands[input.commandIndex];
  if (!command || command.type !== "roll_continued_contact_maintenance") return undefined;
  const previousContest = continuedContactMaintenanceContestSchema.safeParse(
    command.facts.previousContest,
  );
  const previousContact = continuedContactSchema.safeParse(command.facts.previousContinuedContact);
  const previousCondition = unbalancedCombatConditionSchema.safeParse(
    command.facts.previousUnbalancedCondition,
  );
  const previousDistanceProposals = Array.isArray(command.facts.previousDistanceProposals)
    ? command.facts.previousDistanceProposals.flatMap((proposal) => {
        const parsed = combatRoundEndDistanceProposalSchema.safeParse(proposal);
        return parsed.success ? [parsed.data] : [];
      })
    : undefined;
  const review = normalized.roundEndReview;
  if (
    !previousContest.success ||
    !previousContact.success ||
    !previousCondition.success ||
    !review
  ) {
    return undefined;
  }
  return combatRoundStateSchema.parse({
    ...normalized,
    commands: normalized.commands.filter((_, index) => index !== input.commandIndex),
    continuedContacts: normalized.continuedContacts.map((contact) =>
      contact.id === previousContact.data.id ? previousContact.data : contact,
    ),
    currentCursor: command.beforeCursor,
    currentStep: "round_summary",
    roundEndReview: {
      ...review,
      continuedContactMaintenanceContests: review.continuedContactMaintenanceContests.map(
        (contest) => (contest.id === previousContest.data.id ? previousContest.data : contest),
      ),
      proposedDistances: previousDistanceProposals ?? review.proposedDistances,
    },
    selectedParticipantId: command.beforeCursor.participantId,
    selectedStep: "round_summary",
    unbalancedConditions: normalized.unbalancedConditions.map((condition) =>
      condition.id === previousCondition.data.id ? previousCondition.data : condition,
    ),
  });
}

function undoCombatObservationCommandAtIndex(input: {
  commandIndex: number;
  state: CombatRoundState;
}): CombatRoundState | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const command = normalized.commands[input.commandIndex];
  if (!command || command.type !== "roll_observation") return undefined;
  const relationshipId =
    typeof command.facts.relationshipId === "string" ? command.facts.relationshipId : undefined;
  const attemptId =
    typeof command.facts.observationAttemptId === "string"
      ? command.facts.observationAttemptId
      : undefined;
  if (!relationshipId || !attemptId) return undefined;
  const previousRelationship = combatObservationRelationshipSchema.safeParse(
    command.facts.previousRelationship,
  );
  const relationships = previousRelationship.success
    ? normalized.observationRelationships.map((relationship) =>
        relationship.id === relationshipId ? previousRelationship.data : relationship,
      )
    : normalized.observationRelationships.filter(
        (relationship) => relationship.id !== relationshipId,
      );
  const participantReviewEventId =
    typeof command.facts.participantReviewEventId === "string"
      ? command.facts.participantReviewEventId
      : undefined;
  const participantReviewEventPreviousIndex =
    typeof command.facts.participantReviewEventPreviousIndex === "number" &&
    Number.isInteger(command.facts.participantReviewEventPreviousIndex)
      ? command.facts.participantReviewEventPreviousIndex
      : undefined;
  const participantReviewEventPreviousStatus =
    command.facts.participantReviewEventPreviousStatus === "proposed" ||
    command.facts.participantReviewEventPreviousStatus === "committed"
      ? command.facts.participantReviewEventPreviousStatus
      : undefined;
  const stateWithoutRollEvents = removeCombatRoundEventsForCommand({
    commandId: command.id,
    state: normalized,
  });
  let restoredEvents = [...stateWithoutRollEvents.events].sort(
    (left, right) => left.sequence - right.sequence || left.id.localeCompare(right.id),
  );
  if (participantReviewEventId && participantReviewEventPreviousIndex !== undefined) {
    const participantReviewEvent = restoredEvents.find(
      (event) => event.id === participantReviewEventId,
    );
    if (participantReviewEvent) {
      restoredEvents = restoredEvents.filter((event) => event.id !== participantReviewEventId);
      restoredEvents.splice(
        Math.min(participantReviewEventPreviousIndex, restoredEvents.length),
        0,
        participantReviewEventPreviousStatus
          ? { ...participantReviewEvent, status: participantReviewEventPreviousStatus }
          : participantReviewEvent,
      );
    }
  }
  return combatRoundStateSchema.parse({
    ...stateWithoutRollEvents,
    commands: normalized.commands.filter((_, index) => index !== input.commandIndex),
    currentCursor: command.beforeCursor,
    currentStep: "round_summary",
    events: restoredEvents.map((event, sequence) => ({ ...event, sequence })),
    observationAttempts: normalized.observationAttempts.filter(
      (attempt) => attempt.id !== attemptId,
    ),
    observationRelationships: relationships,
    selectedParticipantId: command.beforeCursor.participantId,
    selectedStep: "round_summary",
  });
}

function undoCombatProgressionBoundaryAdvanceCommandAtIndex(input: {
  commandIndex: number;
  state: CombatRoundState;
}): CombatRoundState | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const command = normalized.commands[input.commandIndex];
  if (!command || command.type !== "advance_combat_boundary") return undefined;

  const previousStepSnapshots = Array.isArray(command.facts.previousStepSnapshots)
    ? command.facts.previousStepSnapshots.flatMap((snapshot) => {
        const parsed = combatRoundStepSnapshotSchema.safeParse(snapshot);
        return parsed.success ? [parsed.data] : [];
      })
    : normalized.stepSnapshots;
  const selectedStep = getCombatRoundStepForCursorStep(command.beforeCursor.step);
  const previousGmBacktrackHold = combatRoundGmBacktrackHoldSchema.safeParse(
    command.facts.previousGmBacktrackHold,
  );

  return combatRoundStateSchema.parse({
    ...normalized,
    commands: normalized.commands.filter((_, index) => index !== input.commandIndex),
    currentCursor: command.beforeCursor,
    currentStep: selectedStep,
    gmBacktrackHold: previousGmBacktrackHold.success ? previousGmBacktrackHold.data : undefined,
    phaseResolutionCursor: undefined,
    selectedParticipantId: command.beforeCursor.participantId ?? normalized.selectedParticipantId,
    selectedStep,
    stepSnapshots: previousStepSnapshots,
  });
}

function undoCombatRoundCommandAtIndex(input: {
  commandIndex: number;
  state: CombatRoundState;
}): CombatRoundState | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const command = normalized.commands[input.commandIndex];

  if (!command) {
    return undefined;
  }

  if (command.type === "advance_combat_boundary") {
    return undoCombatProgressionBoundaryAdvanceCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "roll_attack") {
    return undoCombatRoundAttackCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "progress_missile_readiness") {
    return undoCombatRoundMissileReadinessCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "interrupt_missile_readiness") {
    return undoCombatRoundMissileReadinessInterruptionCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "roll_offensive_parry_brawling") {
    return undoCombatRoundOffensiveParryBrawlingCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "roll_continued_contact_maintenance") {
    return undoContinuedContactMaintenanceCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "roll_observation") {
    return undoCombatObservationCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (
    command.type === "review_feint_feasibility" ||
    command.type === "roll_feint" ||
    command.type === "commit_feint_result"
  ) {
    return undoCombatRoundFeintCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (
    command.type === "respond_adjust_distance" ||
    command.type === "review_adjust_distance_roll_adjustment" ||
    command.type === "roll_adjust_distance" ||
    command.type === "commit_adjust_distance"
  ) {
    return undoCombatRoundAdjustDistanceCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (
    command.type === "review_break_off" ||
    command.type === "roll_break_off" ||
    command.type === "commit_break_off"
  ) {
    return undoCombatRoundBreakOffCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (
    command.type === "open_disarm" ||
    command.type === "roll_disarm" ||
    command.type === "commit_disarm"
  ) {
    return undoCombatRoundDisarmCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "decide_double_attack_phase2") {
    return undoCombatRoundDoubleAttackPhase2DecisionCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (
    command.type === "review_combat_task" ||
    command.type === "advance_combat_task" ||
    command.type === "roll_combat_task" ||
    command.type === "resolve_combat_task" ||
    command.type === "interrupt_combat_task" ||
    command.type === "cancel_combat_task"
  ) {
    return undoCombatTaskCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "skip_phase_action") {
    return undoCombatRoundPhaseActionSkipCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "back_out_phase_attack") {
    return undoCombatRoundBackOutPhaseAttackCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "submit_phase_initiative_choice") {
    return undoCombatRoundPhaseInitiativeChoiceCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "commit_phase_initiative_resolution") {
    return undoCombatRoundPhaseInitiativeResolutionCommitCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "complete_remaining_step") {
    return undoCombatRoundBulkStepCompletionCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "roll_combat_experience") {
    return undoCombatRoundCombatExperienceCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "set_pair_distance") {
    return undoCombatRoundPairDistanceCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "commit_defense_review") {
    return undoCombatRoundDefenseReviewCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "roll_parry") {
    return undoCombatRoundParryCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (
    command.type === "complete_damage_review_phase1" ||
    command.type === "complete_damage_review_phase2"
  ) {
    return undoCombatRoundDamageReviewCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "roll_hit_location") {
    return undoCombatRoundHitLocationRollCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "roll_critical") {
    return undoCombatRoundCriticalRollCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "commit_phase_damage") {
    return undoCombatRoundCommittedDamageCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "transition_critical_bleed") {
    const selectedStep = getCombatRoundStepForCursorStep(command.beforeCursor.step);
    return combatRoundStateSchema.parse({
      ...normalized,
      commands: normalized.commands.filter((_, index) => index !== input.commandIndex),
      currentCursor: command.beforeCursor,
      currentStep: selectedStep,
      selectedParticipantId: command.beforeCursor.participantId ?? normalized.selectedParticipantId,
      selectedStep,
    });
  }

  if (command.type === "roll_round_end_health_check") {
    return undoCombatRoundEndHealthCheckCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "roll_round_end_distance_control") {
    return undoCombatRoundEndDistanceControlCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "commit_round_end_distance_control") {
    return undoCombatRoundEndDistanceControlCommitCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "commit_round_end_participant_review") {
    return undoCombatRoundEndParticipantReviewCommitCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "prepare_round_end_review") {
    return undoCombatRoundEndReviewPrepareCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  if (command.type === "resolve_damage") {
    return undoCombatRoundResolvedDamageCommandAtIndex({
      commandIndex: input.commandIndex,
      state: normalized,
    });
  }

  return undoCombatRoundGlobalCommandAtIndex({
    commandIndex: input.commandIndex,
    state: normalized,
  });
}

export function undoLatestCombatRoundCommand(input: {
  state: CombatRoundState;
}): CombatRoundState | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const commandIndex = getLatestCombatRoundUndoableCommandIndex({
    roundNumber: normalized.roundNumber,
    state: normalized,
  });

  const command = normalized.commands[commandIndex];
  const undone = undoCombatRoundCommandAtIndex({
    commandIndex,
    state: normalized,
  });

  return undone && command
    ? removeCombatRoundEventsForCommand({ commandId: command.id, state: undone })
    : undone;
}

function combatRoundSelectedStepHasClearableState(input: {
  state: CombatRoundState;
  step: CombatRoundStep;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  const selectedParticipant = normalized.participants.find(
    (participant) => participant.participantId === normalized.selectedParticipantId,
  );

  if (!selectedParticipant) {
    return false;
  }

  const status = selectedParticipant.stepStatuses[input.step] ?? "pending";
  const hasNonPendingStatus = status !== "pending";
  const phase =
    getCombatRoundAttackPhaseForStep(input.step) ??
    getCombatRoundResolutionPhaseForStep(input.step);

  if (!phase) {
    if (input.step === "select_actions") {
      return Boolean(selectedParticipant.declaration) || hasNonPendingStatus;
    }

    if (input.step === "initiative_phase_1") {
      return Boolean(selectedParticipant.initiatives.phase1) || hasNonPendingStatus;
    }

    if (input.step === "initiative_phase_2") {
      return Boolean(selectedParticipant.initiatives.phase2) || hasNonPendingStatus;
    }

    return hasNonPendingStatus;
  }

  const actionStep = getCombatRoundPhaseActionStepForPhase(phase);

  if (input.step === actionStep) {
    return (
      Boolean(
        getCombatRoundOutgoingAttackResultForParticipantPhase({
          participantId: selectedParticipant.participantId,
          phase,
          state: normalized,
        }),
      ) ||
      Boolean(
        getCombatRoundDisplayIncomingAttackResultForParticipantPhase({
          participantId: selectedParticipant.participantId,
          phase,
          state: normalized,
        }),
      ) ||
      hasNonPendingStatus
    );
  }

  return (
    Boolean(
      getCombatRoundDisplayIncomingAttackResultForParticipantPhase({
        participantId: selectedParticipant.participantId,
        phase,
        state: normalized,
      }),
    ) || hasNonPendingStatus
  );
}

export function canClearCombatRoundStep(input: {
  state: CombatRoundState;
  step: CombatRoundStep;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  const commandIndex = getLatestCombatRoundUndoableCommandIndex({
    roundNumber: normalized.roundNumber,
    state: normalized,
  });

  return (
    commandIndex >= 0 ||
    combatRoundSelectedStepHasClearableState({
      state: normalized,
      step: input.step,
    })
  );
}

export function clearCombatRoundStep(input: {
  state: CombatRoundState;
  step: CombatRoundStep;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const commandUndoneState = undoLatestCombatRoundCommand({ state: normalized });

  if (commandUndoneState) {
    return commandUndoneState;
  }

  if (combatRoundSelectedStepHasClearableState({ state: normalized, step: input.step })) {
    return clearCombatRoundStepLegacy({ state: normalized, step: input.step });
  }

  return normalized;
}

export function holdCombatRoundForGmBacktrack(input: {
  participantId?: string;
  state: CombatRoundState;
  step?: CombatRoundStep;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const step = input.step ?? normalized.currentStep;
  const participantId =
    input.participantId ??
    normalized.currentCursor?.participantId ??
    normalized.selectedParticipantId ??
    normalized.participants[0]?.participantId;

  if (
    participantId &&
    !normalized.participants.some((participant) => participant.participantId === participantId)
  ) {
    throw new RangeError("The GM backtrack participant is not in the active combat round.");
  }

  return combatRoundStateSchema.parse({
    ...normalized,
    gmBacktrackHold: {
      participantId,
      roundNumber: normalized.roundNumber,
      step,
    },
  });
}

export function clearCurrentCombatRoundStepAndRewind(state: CombatRoundState): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(state);
  const commandIndex = getLatestCombatRoundUndoableCommandIndex({
    roundNumber: normalized.roundNumber,
    state: normalized,
  });
  const clearedState = clearCombatRoundStep({
    state: normalized,
    step: normalized.currentStep,
  });

  if (commandIndex >= 0) {
    return clearedState;
  }

  const previousStep = getPreviousCombatRoundStep(normalized.currentStep);
  const nextStep = previousStep ?? normalized.currentStep;

  return {
    ...clearedState,
    currentStep: nextStep,
    selectedStep: nextStep,
  };
}

export function canPlayerSubmitCombatDeclaration(input: {
  participantId: string;
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const declarationStatus = participant?.stepStatuses.select_actions ?? "pending";
  const existingDeclarationIsIncomplete = participant?.declaration
    ? !validateCombatDeclarationTargets({
        actingParticipantId: participant.participantId,
        actionId: participant.declaration.actionId,
        movementKind: participant.declaration.movementIntent?.mode,
        phaseContexts: participant.declaration.phaseContexts,
        secondaryActionContext: participant.declaration.secondaryActionContext,
        selectedOpponentId: participant.declaration.combatContext?.selectedOpponentId,
        secondaryActionId: participant.declaration.secondaryActionId,
      }).valid
    : false;
  const declarationStatusIsHardClosed =
    declarationStatus === "locked" ||
    declarationStatus === "complete" ||
    declarationStatus === "skipped";
  const combatExperienceRequired = isCombatStartExperienceRollRequired({
    participantId: input.participantId,
    state: normalized,
  });

  return (
    normalized.currentStep === "select_actions" &&
    !combatExperienceRequired &&
    !declarationStatusIsHardClosed &&
    (declarationStatus === "pending" || existingDeclarationIsIncomplete)
  );
}

export function canPlayerRollCombatInitiative(input: {
  participantId: string;
  phase: "phase1" | "phase2";
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  const requiredStep = input.phase === "phase1" ? "initiative_phase_1" : "initiative_phase_2";
  const participant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const initiativeValue = participant?.initiatives[input.phase];
  const stepStatus = participant?.stepStatuses[requiredStep] ?? "pending";

  return (
    normalized.currentStep === requiredStep &&
    initiativeValue === undefined &&
    stepStatus === "pending"
  );
}

export function isCombatRoundPhaseInitiativeComplete(input: {
  phase: "phase1" | "phase2";
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  const requiredStep = input.phase === "phase1" ? "initiative_phase_1" : "initiative_phase_2";

  return normalized.participants.every((participant) => {
    if (participant.initiatives[input.phase] !== undefined) {
      return true;
    }

    const stepStatus = participant.stepStatuses[requiredStep] ?? "pending";

    return (
      stepStatus === "complete" ||
      stepStatus === "gmEdited" ||
      stepStatus === "locked" ||
      stepStatus === "skipped" ||
      stepStatus === "submitted"
    );
  });
}

export function isCombatRoundPhaseInitiativeCommitted(input: {
  phase: "phase1" | "phase2";
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);

  return normalized.commands.some(
    (command) =>
      command.roundNumber === normalized.roundNumber &&
      command.type === "commit_phase_initiative_resolution" &&
      command.phase === input.phase,
  );
}

export function canPlayerRollCombatAttack(input: {
  participantId: string;
  phase: "phase1" | "phase2";
  state: CombatRoundState;
}): boolean {
  const normalized = combatRoundStateSchema.parse(input.state);
  const requiredStep = input.phase === "phase1" ? "phase_1_actions" : "phase_2_actions";
  const requiredCursorStep = input.phase === "phase1" ? "A1" : "A2";
  const existingAttackResult = getCombatRoundOutgoingAttackResultForParticipantPhase({
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });

  return (
    normalized.currentStep === requiredStep &&
    normalized.currentCursor?.participantId === input.participantId &&
    normalized.currentCursor.step === requiredCursorStep &&
    normalized.phaseResolutionCursor?.participantId === input.participantId &&
    normalized.phaseResolutionCursor.phase === input.phase &&
    normalized.phaseResolutionCursor.substep === "attack" &&
    combatRoundParticipantHasExecutablePhaseAttack(input) &&
    existingAttackResult === undefined
  );
}

export type PlayerCombatCurrentRollAction =
  | {
      kind: "attack";
      participantId: string;
      phase: CombatRoundPhase;
      step: "A1" | "A2";
    }
  | {
      attackResultId: string;
      attackerParticipantId: string;
      defenderParticipantId: string;
      kind: "parry";
      participantId: string;
      phase: CombatRoundPhase;
      step: "P1" | "P2";
    }
  | {
      attackResultId: string;
      attackerParticipantId: string;
      defenderParticipantId: string;
      kind: "hit_location";
      participantId: string;
      phase: CombatRoundPhase;
      step: "D1" | "D2";
    }
  | {
      attackResultId: string;
      attackerParticipantId: string;
      defenderParticipantId: string;
      kind: "critical";
      participantId: string;
      phase: CombatRoundPhase;
      step: "D1" | "D2";
    };

function getCombatRoundAttackPhaseForCursorStep(
  step: CombatRoundCursorStep,
): CombatRoundPhase | undefined {
  if (step === "A1") {
    return "phase1";
  }

  if (step === "A2") {
    return "phase2";
  }

  return undefined;
}

function getCombatRoundParryPhaseForCursorStep(
  step: CombatRoundCursorStep,
): CombatRoundPhase | undefined {
  if (step === "P1") {
    return "phase1";
  }

  if (step === "P2") {
    return "phase2";
  }

  return undefined;
}

function getCombatRoundDamagePhaseForCursorStep(
  step: CombatRoundCursorStep,
): CombatRoundPhase | undefined {
  if (step === "D1") {
    return "phase1";
  }

  if (step === "D2") {
    return "phase2";
  }

  return undefined;
}

function getCurrentCursorIncomingAttackContext(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}):
  | {
      attackResult: CombatRoundAttackRollResult;
      attackResultId: string;
      resolution: CombatRoundPhaseResolutionResult;
    }
  | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const participantId = normalized.currentCursor?.participantId;

  if (!participantId) {
    return undefined;
  }

  const attackResult = getCombatRoundDisplayIncomingAttackResultForParticipantPhase({
    participantId,
    phase: input.phase,
    state: normalized,
  });

  if (!attackResult) {
    return undefined;
  }

  return {
    attackResult,
    attackResultId: getCombatRoundAttackResultId({
      result: attackResult,
      roundNumber: normalized.roundNumber,
    }),
    resolution:
      getCombatRoundPhaseResolutionResultForAttack({
        attackResult,
        state: normalized,
      }) ??
      buildCombatRoundPhaseResolutionResult({
        attackResult,
        roundNumber: normalized.roundNumber,
        state: normalized,
        updatedAt: attackResult.rolledAt,
      }),
  };
}

export function getPlayerCombatCurrentRollAction(input: {
  participantId: string;
  state: CombatRoundState;
}): PlayerCombatCurrentRollAction | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const cursor = normalized.currentCursor;

  if (!cursor || cursor.roundNumber !== normalized.roundNumber) {
    return undefined;
  }

  const attackPhase = getCombatRoundAttackPhaseForCursorStep(cursor.step);

  if (
    attackPhase &&
    (cursor.step === "A1" || cursor.step === "A2") &&
    cursor.participantId === input.participantId
  ) {
    return canPlayerRollCombatAttack({
      participantId: input.participantId,
      phase: attackPhase,
      state: normalized,
    })
      ? {
          kind: "attack",
          participantId: input.participantId,
          phase: attackPhase,
          step: cursor.step,
        }
      : undefined;
  }

  const parryPhase = getCombatRoundParryPhaseForCursorStep(cursor.step);

  if (
    parryPhase &&
    (cursor.step === "P1" || cursor.step === "P2") &&
    cursor.participantId === input.participantId
  ) {
    const context = getCurrentCursorIncomingAttackContext({
      phase: parryPhase,
      state: normalized,
    });

    return context?.attackResult.hit &&
      context.attackResult.defenderParticipantId === input.participantId &&
      context.resolution.parryResolution.status === "pending"
      ? {
          attackResultId: context.attackResultId,
          attackerParticipantId: context.attackResult.attackerParticipantId,
          defenderParticipantId: context.attackResult.defenderParticipantId,
          kind: "parry",
          participantId: input.participantId,
          phase: parryPhase,
          step: cursor.step,
        }
      : undefined;
  }

  const damagePhase = getCombatRoundDamagePhaseForCursorStep(cursor.step);

  if (!damagePhase || (cursor.step !== "D1" && cursor.step !== "D2")) {
    return undefined;
  }

  const context = getCurrentCursorIncomingAttackContext({
    phase: damagePhase,
    state: normalized,
  });

  if (
    !context ||
    context.attackResult.attackerParticipantId !== input.participantId ||
    context.attackResult.defenderParticipantId !== cursor.participantId
  ) {
    return undefined;
  }

  const damageSubstate = getCombatRoundDamageSubstate(context.resolution);

  if (damageSubstate === "location_pending") {
    return {
      attackResultId: context.attackResultId,
      attackerParticipantId: context.attackResult.attackerParticipantId,
      defenderParticipantId: context.attackResult.defenderParticipantId,
      kind: "hit_location",
      participantId: input.participantId,
      phase: damagePhase,
      step: cursor.step,
    };
  }

  if (damageSubstate === "critical_pending") {
    return {
      attackResultId: context.attackResultId,
      attackerParticipantId: context.attackResult.attackerParticipantId,
      defenderParticipantId: context.attackResult.defenderParticipantId,
      kind: "critical",
      participantId: input.participantId,
      phase: damagePhase,
      step: cursor.step,
    };
  }

  return undefined;
}

export function setCombatRoundActiveParticipant(
  state: CombatRoundState,
  participantId?: string,
): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(state);
  const hasParticipant = normalized.participants.some(
    (participant) => participant.participantId === participantId,
  );

  return {
    ...normalized,
    activeParticipantId: hasParticipant ? participantId : undefined,
    selectedParticipantId: hasParticipant ? participantId : normalized.selectedParticipantId,
  };
}

export function setCombatRoundSelection(input: {
  participantId?: string;
  state: CombatRoundState;
  step?: CombatRoundStep;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const hasParticipant = normalized.participants.some(
    (participant) => participant.participantId === input.participantId,
  );

  return {
    ...normalized,
    selectedParticipantId: hasParticipant ? input.participantId : normalized.selectedParticipantId,
    selectedStep: input.step ?? normalized.selectedStep,
  };
}

export function setCombatRoundParticipantInitiative(input: {
  initiative?: CombatRoundInitiativeResult | number;
  participantId: string;
  phase: "phase1" | "phase2";
  state: CombatRoundState;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);
  const initiative = normalizeCombatRoundInitiativeResult(input.initiative);

  return {
    ...normalized,
    participants: normalized.participants.map((participant) =>
      participant.participantId === input.participantId
        ? {
            ...participant,
            initiatives: {
              ...participant.initiatives,
              [input.phase]: initiative,
            },
          }
        : participant,
    ),
  };
}

export function setCombatRoundParticipantStepStatus(input: {
  participantId: string;
  state: CombatRoundState;
  status: CombatRoundStepStatus;
  step: CombatRoundStep;
}): CombatRoundState {
  const normalized = combatRoundStateSchema.parse(input.state);

  return {
    ...normalized,
    participants: normalized.participants.map((participant) =>
      participant.participantId === input.participantId
        ? {
            ...participant,
            stepStatuses: {
              ...participant.stepStatuses,
              [input.step]: input.status,
            },
          }
        : participant,
    ),
  };
}

export function sortCombatRoundParticipantsByInitiative(input: {
  phase: "phase1" | "phase2";
  state: CombatRoundState;
}): CombatRoundParticipantState[] {
  const normalized = combatRoundStateSchema.parse(input.state);
  const originalIndexByParticipantId = new Map(
    normalized.participants.map((participant, index) => [participant.participantId, index]),
  );

  return [...normalized.participants].sort((left, right) => {
    const leftInitiative = getCombatRoundInitiativeTotal(left.initiatives[input.phase]);
    const rightInitiative = getCombatRoundInitiativeTotal(right.initiatives[input.phase]);

    if (leftInitiative !== undefined && rightInitiative !== undefined) {
      return (
        rightInitiative - leftInitiative ||
        (originalIndexByParticipantId.get(left.participantId) ?? 0) -
          (originalIndexByParticipantId.get(right.participantId) ?? 0)
      );
    }

    if (leftInitiative !== undefined) {
      return -1;
    }

    if (rightInitiative !== undefined) {
      return 1;
    }

    return (
      (originalIndexByParticipantId.get(left.participantId) ?? 0) -
      (originalIndexByParticipantId.get(right.participantId) ?? 0)
    );
  });
}

export function getCombatRoundInitiativePositions(input: {
  phase: "phase1" | "phase2";
  state: CombatRoundState;
}): Record<string, number> {
  const ranks = getCombatRoundInitiativeRanks(input);

  return Object.fromEntries(
    Object.entries(ranks).map(([participantId, rank]) => [participantId, rank.rank]),
  );
}

export function getCombatRoundInitiativeRanks(input: {
  phase: "phase1" | "phase2";
  state: CombatRoundState;
}): Record<string, CombatRoundInitiativeRank> {
  const sortedParticipants = sortCombatRoundParticipantsByInitiative(input);
  const rolledParticipants = sortedParticipants
    .map((participant) => ({
      participant,
      total: getCombatRoundInitiativeTotal(participant.initiatives[input.phase]),
    }))
    .filter(
      (entry): entry is { participant: CombatRoundParticipantState; total: number } =>
        entry.total !== undefined,
    );
  const tiedCountsByTotal = rolledParticipants.reduce((counts, entry) => {
    counts.set(entry.total, (counts.get(entry.total) ?? 0) + 1);

    return counts;
  }, new Map<number, number>());
  const ranks: Record<string, CombatRoundInitiativeRank> = {};
  let currentRank = 0;
  let previousTotal: number | undefined;

  rolledParticipants.forEach((entry, index) => {
    if (entry.total !== previousTotal) {
      currentRank = index + 1;
      previousTotal = entry.total;
    }

    ranks[entry.participant.participantId] = {
      rank: currentRank,
      rankTotal: rolledParticipants.length,
      tiedCount: tiedCountsByTotal.get(entry.total) ?? 1,
    };
  });

  return ranks;
}

export interface CombatRoundInitiativeExecutionGroup {
  id: string;
  initiativeValue: number;
  opportunityIds: string[];
  participantIds: string[];
  phase: CombatRoundPhase;
  roundNumber: number;
  status: "complete" | "current" | "waiting";
}

export function getCombatRoundInitiativeExecutionGroupId(input: {
  initiativeValue: number;
  phase: CombatRoundPhase;
  roundNumber: number;
}): string {
  return `round:${input.roundNumber}:phase:${input.phase}:initiative:${input.initiativeValue}`;
}

/**
 * Projects the committed initiative order as simultaneous initiative-value groups. Completion
 * is owned by the participant phase-resolution status, which does not become done until the
 * source opportunity and all of its canonical child work have closed.
 */
export function getCombatRoundInitiativeExecutionGroups(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundInitiativeExecutionGroup[] {
  const normalized = combatRoundStateSchema.parse(input.state);
  const candidates = getCombatRoundPhaseAttackCandidates({
    phase: input.phase,
    state: normalized,
  });
  const grouped = new Map<
    number,
    { opportunityIds: string[]; participantIds: string[]; complete: boolean }
  >();

  for (const participant of sortCombatRoundParticipantsByInitiative(input)) {
    const initiativeValue = getCombatRoundInitiativeTotal(participant.initiatives[input.phase]);
    if (
      initiativeValue === undefined ||
      !combatRoundParticipantHasExecutablePhaseAction({
        participantId: participant.participantId,
        phase: input.phase,
        state: normalized,
      })
    ) {
      continue;
    }
    const status = getEffectiveCombatRoundPhaseResolutionStatus({
      participantId: participant.participantId,
      phase: input.phase,
      state: normalized,
    });
    const existing = grouped.get(initiativeValue) ?? {
      complete: true,
      opportunityIds: [],
      participantIds: [],
    };
    existing.participantIds.push(participant.participantId);
    existing.opportunityIds.push(
      ...candidates
        .filter((candidate) => candidate.participantId === participant.participantId)
        .map((candidate) => candidate.id),
    );
    existing.complete &&= status.substep === "done";
    grouped.set(initiativeValue, existing);
  }

  const ordered = [...grouped.entries()].sort(([left], [right]) => right - left);
  const firstIncompleteIndex = ordered.findIndex(([, group]) => !group.complete);
  return ordered.map(([initiativeValue, group], index) => ({
    id: getCombatRoundInitiativeExecutionGroupId({
      initiativeValue,
      phase: input.phase,
      roundNumber: normalized.roundNumber,
    }),
    initiativeValue,
    opportunityIds: [...new Set(group.opportunityIds)],
    participantIds: [...new Set(group.participantIds)],
    phase: input.phase,
    roundNumber: normalized.roundNumber,
    status: group.complete ? "complete" : index === firstIncompleteIndex ? "current" : "waiting",
  }));
}

export function getCombatRoundCurrentInitiativeExecutionGroup(input: {
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatRoundInitiativeExecutionGroup | undefined {
  return getCombatRoundInitiativeExecutionGroups(input).find((group) => group.status === "current");
}

export function buildCombatRoundInspector(input: {
  participantId?: string;
  state: CombatRoundState;
  step?: CombatRoundStep;
}): {
  participant?: CombatRoundParticipantState;
  snapshot?: CombatRoundStepSnapshot;
  status?: CombatRoundStepStatus;
  step: CombatRoundStep;
} {
  const normalized = combatRoundStateSchema.parse(input.state);
  const step = input.step ?? normalized.selectedStep ?? normalized.currentStep;
  const participant = input.participantId
    ? normalized.participants.find((entry) => entry.participantId === input.participantId)
    : undefined;

  return {
    participant,
    snapshot: participant
      ? getCombatRoundStepSnapshot({
          participantId: participant.participantId,
          roundNumber: normalized.roundNumber,
          state: normalized,
          step,
        })
      : undefined,
    status: participant?.stepStatuses[step],
    step,
  };
}

export interface CombatRoundLatestEventSummary {
  commandId?: string;
  details?: string;
  phase?: CombatRoundPhase;
  resultId?: string;
  roundNumber: number;
  shortTitle: string;
  step?: CombatRoundCursorStep;
  summaryText: string;
}

export interface CombatRoundCommandCurrentTask {
  cursorStep: CombatRoundCursorStep;
  participantId?: string;
  roundNumber: number;
  step: CombatRoundStep;
}

export interface CombatRoundCommandEnvelopeResult {
  attackResultId?: string;
  attackerParticipantId?: string;
  defenderParticipantId?: string;
  kind: "attack" | "parry" | "phase_initiative_commit";
  parryResultId?: string;
  phase?: CombatRoundPhase;
}

export interface CombatRoundCommandEnvelope {
  currentCursor?: CombatRoundCursor;
  currentStep: CombatRoundStep;
  currentTask?: CombatRoundCommandCurrentTask;
  latestEvent?: CombatRoundLatestEventSummary;
  latestResult?: CombatRoundCommandEnvelopeResult;
  warnings: string[];
}

type CombatRoundLatestEventParticipantLabel = {
  label: string;
  participantId: string;
};

function getCombatRoundLatestEventFactRecord(value: unknown): Record<string, unknown> | undefined {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : undefined;
}

function getCombatRoundLatestEventFactString(
  facts: Record<string, unknown>,
  key: string,
): string | undefined {
  const value = facts[key];

  return typeof value === "string" ? value : undefined;
}

function getCombatRoundLatestEventFactNumber(
  facts: Record<string, unknown>,
  key: string,
): number | undefined {
  const value = facts[key];

  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function getCombatRoundLatestEventFactBoolean(
  facts: Record<string, unknown>,
  key: string,
): boolean | undefined {
  const value = facts[key];

  return typeof value === "boolean" ? value : undefined;
}

function getCombatRoundLatestEventFactArray(
  facts: Record<string, unknown>,
  key: string,
): unknown[] {
  const value = facts[key];

  return Array.isArray(value) ? value : [];
}

function getCombatRoundLatestEventPhaseLabel(phase?: CombatRoundPhase): string {
  return phase === "phase1" ? "Phase 1" : phase === "phase2" ? "Phase 2" : "Round";
}

function getCombatRoundLatestEventHitLocationLabel(location?: string): string | undefined {
  const parsed = hitLocationSchema.safeParse(location);

  return parsed.success ? getHitLocationFullLabel(parsed.data).toLowerCase() : undefined;
}

function getCombatRoundLatestEventDamageLocationSuffix(location?: string): string {
  const label = getCombatRoundLatestEventHitLocationLabel(location);

  return label ? ` to ${label}` : "";
}

function getCombatRoundLatestEventCriticalEffectCount(effects: readonly unknown[]): number {
  return effects.filter((effect) => {
    const record = getCombatRoundLatestEventFactRecord(effect);

    return Boolean(
      record &&
      (record.sourceKind === "critical_table" ||
        typeof record.sourceCritKey === "string" ||
        typeof record.sourceEffectKey === "string"),
    );
  }).length;
}

function getCombatRoundLatestEventCriticalProposalDetails(damageResult?: CombatRoundDamageResult): {
  proposedCriticalEffects: number;
  proposalStatus?: string;
  warnings: string[];
} {
  const proposal = damageResult?.review?.criticalEffectProposal;
  const proposedCriticalEffects = getCombatRoundLatestEventCriticalEffectCount(
    damageResult?.review?.additionalEffects ?? [],
  );

  if (!proposal) {
    return {
      proposedCriticalEffects,
      warnings: [],
    };
  }

  if (proposal.warnings.length > 0) {
    return {
      proposedCriticalEffects,
      proposalStatus: `Critical effects unavailable: ${proposal.warnings.join(" ")}`,
      warnings: proposal.warnings,
    };
  }

  return {
    proposedCriticalEffects,
    proposalStatus: `Critical-derived rows: ${proposedCriticalEffects} row${
      proposedCriticalEffects === 1 ? "" : "s"
    }.`,
    warnings: [],
  };
}

function getCombatRoundLatestEventLabel(input: {
  labelByParticipantId: Map<string, string>;
  participantId?: string;
}): string {
  return input.participantId
    ? (input.labelByParticipantId.get(input.participantId) ?? input.participantId)
    : "Unknown participant";
}

function findCombatRoundLatestEventResolution(input: {
  command: CombatRoundCommand;
  state: CombatRoundState;
}): CombatRoundPhaseResolutionResult | undefined {
  const attackResultId = getCombatRoundLatestEventFactString(input.command.facts, "attackResultId");

  if (attackResultId) {
    return input.state.phaseResolutionResults.find(
      (result) => result.attackResultId === attackResultId,
    );
  }

  return input.state.phaseResolutionResults.find(
    (result) =>
      result.roundNumber === input.command.roundNumber &&
      result.phase === input.command.phase &&
      (result.attackerParticipantId === input.command.participantId ||
        result.defenderParticipantId === input.command.participantId),
  );
}

function findCombatRoundLatestEventAttackResult(input: {
  command: CombatRoundCommand;
  state: CombatRoundState;
}): CombatRoundAttackRollResult | undefined {
  if (!input.command.phase) {
    return undefined;
  }

  return getCombatRoundOutgoingAttackResultForParticipantPhase({
    participantId: input.command.participantId,
    phase: input.command.phase,
    state: input.state,
  });
}

function getCombatRoundLatestEventForCommand(input: {
  command: CombatRoundCommand;
  labelByParticipantId: Map<string, string>;
  state: CombatRoundState;
}): CombatRoundLatestEventSummary | undefined {
  const { command, labelByParticipantId, state } = input;
  const facts = command.facts;
  const actorLabel = getCombatRoundLatestEventLabel({
    labelByParticipantId,
    participantId: command.participantId,
  });
  const phaseLabel = getCombatRoundLatestEventPhaseLabel(command.phase);

  if (command.type === "advance_combat_boundary") {
    const currentBoundary = getCombatRoundLatestEventFactString(facts, "currentBoundary");
    const targetBoundary = getCombatRoundLatestEventFactString(facts, "targetBoundary");

    return {
      commandId: command.id,
      roundNumber: command.roundNumber,
      shortTitle: "Combat boundary opened",
      step: command.afterCursor.step,
      summaryText: `Round ${command.roundNumber}: ${targetBoundary ?? "next combat boundary"} opened${
        currentBoundary ? ` after ${currentBoundary}` : ""
      }.`,
    };
  }

  if (command.type === "complete_round") {
    const nextRoundNumber =
      getCombatRoundLatestEventFactNumber(facts, "nextRoundNumber") ??
      command.afterCursor.roundNumber;

    return {
      commandId: command.id,
      roundNumber: nextRoundNumber,
      shortTitle: "New round started",
      step: command.afterCursor.step,
      summaryText: `Round ${nextRoundNumber}: New round started.`,
    };
  }

  if (command.type === "complete_remaining_step") {
    const resolutionType = getCombatRoundLatestEventFactString(facts, "resolutionType");
    const completedLabel = resolutionType === "bulk_skipped" ? "initiative" : "modifier review";

    return {
      commandId: command.id,
      phase: command.phase,
      roundNumber: command.roundNumber,
      shortTitle: `Remaining ${completedLabel} completed`,
      step: command.step,
      summaryText: `Round ${command.roundNumber}, ${phaseLabel}: GM completed remaining ${completedLabel}.`,
    };
  }

  if (command.type === "roll_combat_experience") {
    const skillTotal = getCombatRoundLatestEventFactNumber(facts, "skillTotal") ?? 0;
    const rollTotal = getCombatRoundLatestEventFactNumber(facts, "rollTotal");
    const finalTotal = getCombatRoundLatestEventFactNumber(facts, "finalTotal");
    const noRollRequired = getCombatRoundLatestEventFactBoolean(facts, "noRollRequired") ?? false;
    const difficulty =
      getCombatRoundLatestEventFactNumber(facts, "difficulty") ??
      COMBAT_EXPERIENCE_DEFAULT_DIFFICULTY;
    const resultLabel = getCombatRoundLatestEventFactString(facts, "resultLabel") ?? "Active";
    const modifierValue = getCombatRoundLatestEventFactNumber(facts, "modifierValue") ?? 0;
    const durationRounds = getCombatRoundLatestEventFactNumber(facts, "durationRounds") ?? 0;
    const phaseAttackCancelled =
      getCombatRoundLatestEventFactBoolean(facts, "phaseAttackCancelled") ?? false;
    const isPhaseCombatExperience = command.step === "A1" || command.step === "A2";
    const effectText = phaseAttackCancelled
      ? " No attack made."
      : isPhaseCombatExperience && modifierValue < 0
        ? ` Phase attack OB ${modifierValue}.`
        : modifierValue !== 0 && durationRounds > 0
          ? ` General ${modifierValue} for ${durationRounds} round${durationRounds === 1 ? "" : "s"}.`
          : " No modifier.";
    const stepLabel = command.step ?? "DE";

    return {
      commandId: command.id,
      roundNumber: command.roundNumber,
      shortTitle: "Combat Experience",
      step: command.step,
      summaryText: noRollRequired
        ? `Round ${command.roundNumber}, ${stepLabel}: ${actorLabel} Combat Experience ${skillTotal} vs ${difficulty}. Result: ${resultLabel}, no roll required.${effectText}`
        : `Round ${command.roundNumber}, ${stepLabel}: ${actorLabel} Combat Experience ${skillTotal} + roll ${
            rollTotal ?? "?"
          } = ${finalTotal ?? "?"} vs ${difficulty}. Result: ${resultLabel}.${effectText}`,
    };
  }

  if (command.type === "submit_phase_initiative_choice") {
    const choice = getCombatRoundLatestEventFactString(facts, "choice");

    if (choice === "roll_ce_result") {
      const skillTotal = getCombatRoundLatestEventFactNumber(facts, "skillTotal") ?? 0;
      const rollTotal = getCombatRoundLatestEventFactNumber(facts, "rollTotal");
      const finalTotal = getCombatRoundLatestEventFactNumber(facts, "finalTotal");
      const noRollRequired = getCombatRoundLatestEventFactBoolean(facts, "noRollRequired") ?? false;
      const difficulty =
        getCombatRoundLatestEventFactNumber(facts, "difficulty") ??
        COMBAT_EXPERIENCE_DEFAULT_DIFFICULTY;
      const modifierValue = getCombatRoundLatestEventFactNumber(facts, "modifierValue") ?? 0;
      const effectiveTableTotal = getCombatRoundLatestEventFactNumber(facts, "effectiveTableTotal");
      const resultText =
        effectiveTableTotal !== undefined && effectiveTableTotal <= 5
          ? "Result: attack cancelled."
          : modifierValue < 0
            ? `Result: OB ${modifierValue}.`
            : "Result: Active, no modifier.";

      return {
        commandId: command.id,
        phase: command.phase,
        roundNumber: command.roundNumber,
        shortTitle: "Combat Experience",
        step: command.step,
        summaryText: noRollRequired
          ? `Round ${command.roundNumber}, ${phaseLabel}: ${actorLabel} Combat Experience ${skillTotal} vs ${difficulty}. ${resultText}`
          : `Round ${command.roundNumber}, ${phaseLabel}: ${actorLabel} Combat Experience ${skillTotal} + roll ${
              rollTotal ?? "?"
            } = ${finalTotal ?? "?"} vs ${difficulty}. ${resultText}`,
      };
    }

    if (choice === "back_out") {
      return {
        commandId: command.id,
        phase: command.phase,
        roundNumber: command.roundNumber,
        shortTitle: "Backed out of attack",
        step: command.step,
        summaryText: `Round ${command.roundNumber}, ${phaseLabel}: ${actorLabel} backed out of attack. Result: attack cancelled/backed out.`,
      };
    }

    if (choice === "continue_without_ce") {
      return {
        commandId: command.id,
        phase: command.phase,
        roundNumber: command.roundNumber,
        shortTitle: "Phase choice submitted",
        step: command.step,
        summaryText: `Round ${command.roundNumber}, ${phaseLabel}: ${actorLabel} continued attack. Result: no CE roll required.`,
      };
    }
  }

  if (command.type === "commit_phase_initiative_resolution") {
    const attackStep = getCombatRoundLatestEventFactString(facts, "attackStep") ?? "A";

    return {
      commandId: command.id,
      roundNumber: command.roundNumber,
      shortTitle: "Phase initiative committed",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, ${phaseLabel}: Phase initiative resolution committed; ${attackStep} opened.`,
    };
  }

  if (command.type === "back_out_phase_attack") {
    const softenedModifierIds = getCombatRoundLatestEventFactArray(facts, "softenedModifierIds");
    const warning = getCombatRoundLatestEventFactString(facts, "modifierSofteningWarning");
    const modifierText =
      softenedModifierIds.length > 0
        ? " DB/Parry attack penalty reduced from -4 to -2 for this phase."
        : " No generated DB/Parry -4 modifier was found to soften.";

    return {
      commandId: command.id,
      details: warning,
      roundNumber: command.roundNumber,
      shortTitle: "Backed out of attack",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, ${phaseLabel}: ${actorLabel} backed out of attack; attack skipped.${modifierText}`,
    };
  }

  if (command.type === "roll_round_end_health_check") {
    const finalTotal = getCombatRoundLatestEventFactNumber(facts, "finalTotal");
    const difficulty = getCombatRoundLatestEventFactNumber(facts, "difficulty");
    const success = getCombatRoundLatestEventFactBoolean(facts, "success");
    const bleedType = getCombatRoundLatestEventFactString(facts, "bleedType");
    const previousBleedRate = getCombatRoundLatestEventFactNumber(facts, "previousBleedRate");
    const nextBleedRate = getCombatRoundLatestEventFactNumber(facts, "nextBleedRate");
    const bleedLabel = bleedType === "internal" ? "internal bleed" : "bleed";
    const bleedResult =
      success && previousBleedRate !== undefined && nextBleedRate !== undefined
        ? `; ${bleedLabel} reduced from ${previousBleedRate} to ${nextBleedRate}.`
        : success === false && previousBleedRate !== undefined
          ? `; ${bleedLabel} remains ${previousBleedRate}.`
          : ".";

    return {
      commandId: command.id,
      roundNumber: command.roundNumber,
      shortTitle: success ? "Health roll succeeded" : "Health roll failed",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, SU: ${actorLabel} health roll ${
        finalTotal ?? "?"
      }${difficulty !== undefined ? ` vs ${difficulty}` : ""}${
        success === undefined ? "." : success ? ` succeeded${bleedResult}` : ` failed${bleedResult}`
      }`,
    };
  }

  if (command.type === "roll_round_end_distance_control") {
    const participantAId = getCombatRoundLatestEventFactString(facts, "participantAId");
    const participantBId = getCombatRoundLatestEventFactString(facts, "participantBId");
    const participantALabel = getCombatRoundLatestEventLabel({
      labelByParticipantId,
      participantId: participantAId,
    });
    const participantBLabel = getCombatRoundLatestEventLabel({
      labelByParticipantId,
      participantId: participantBId,
    });
    const finalTotal = getCombatRoundLatestEventFactNumber(facts, "rolledParticipantFinalTotal");
    const proposedDistance = getCombatRoundLatestEventFactNumber(facts, "proposedDistance");

    return {
      commandId: command.id,
      details:
        proposedDistance !== undefined
          ? `Proposed distance ${proposedDistance} next round.`
          : "Waiting for the opposing distance-control roll.",
      roundNumber: command.roundNumber,
      shortTitle: "Distance control rolled",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, SU: ${actorLabel} rolled distance control${
        finalTotal !== undefined ? ` ${finalTotal}` : ""
      } for ${participantALabel} ↔ ${participantBLabel}.`,
    };
  }

  if (command.type === "commit_round_end_distance_control") {
    const participantAId = getCombatRoundLatestEventFactString(facts, "participantAId");
    const participantBId = getCombatRoundLatestEventFactString(facts, "participantBId");
    const participantALabel = getCombatRoundLatestEventLabel({
      labelByParticipantId,
      participantId: participantAId,
    });
    const participantBLabel = getCombatRoundLatestEventLabel({
      labelByParticipantId,
      participantId: participantBId,
    });
    const appliedDistance = getCombatRoundLatestEventFactNumber(facts, "appliedDistance");

    return {
      commandId: command.id,
      roundNumber: command.roundNumber,
      shortTitle: "Distance control applied",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, SU: Distance control applied for ${participantALabel} ↔ ${participantBLabel}: distance ${
        appliedDistance ?? "?"
      } next round.`,
    };
  }

  if (command.type === "commit_round_end_participant_review") {
    const damageIds = getCombatRoundLatestEventFactArray(facts, "acceptedDamageProposalIds");
    const healthIds = getCombatRoundLatestEventFactArray(facts, "acceptedHealthRollIds");

    return {
      commandId: command.id,
      details:
        healthIds.length > 0
          ? `${healthIds.length} health roll${healthIds.length === 1 ? "" : "s"} pending.`
          : undefined,
      roundNumber: command.roundNumber,
      shortTitle: "Round-end review committed",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, SU: ${actorLabel} round-end review committed${
        damageIds.length > 0
          ? ` with ${damageIds.length} bleed damage proposal${
              damageIds.length === 1 ? "" : "s"
            } applied`
          : ""
      }.`,
    };
  }

  if (command.type === "prepare_round_end_review") {
    return {
      commandId: command.id,
      roundNumber: command.roundNumber,
      shortTitle: "Round-end review ready",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, SU: Round-end review proposals prepared.`,
    };
  }

  if (command.type === "commit_phase_damage") {
    const attackerLabel = getCombatRoundLatestEventLabel({
      labelByParticipantId,
      participantId: getCombatRoundLatestEventFactString(facts, "attackerParticipantId"),
    });
    const defenderLabel = getCombatRoundLatestEventLabel({
      labelByParticipantId,
      participantId: getCombatRoundLatestEventFactString(facts, "defenderParticipantId"),
    });
    const totalDamage = getCombatRoundLatestEventFactNumber(facts, "totalDamage") ?? 0;
    const location = getCombatRoundLatestEventFactString(facts, "effectiveHitLocation");
    const criticalGrade = getCombatRoundLatestEventFactString(facts, "criticalGrade");
    const criticalRollRecord = getCombatRoundLatestEventFactRecord(facts.criticalRoll);
    const finalCriticalRoll =
      criticalRollRecord && typeof criticalRollRecord.finalCriticalRoll === "number"
        ? criticalRollRecord.finalCriticalRoll
        : undefined;
    const criticalLocation =
      criticalRollRecord && typeof criticalRollRecord.selectedHitLocation === "string"
        ? criticalRollRecord.selectedHitLocation
        : location;
    const additionalEffects = getCombatRoundLatestEventFactArray(facts, "additionalEffects");
    const criticalEffectsCommitted =
      getCombatRoundLatestEventCriticalEffectCount(additionalEffects);
    const critical =
      criticalGrade || finalCriticalRoll !== undefined
        ? ` Critical${criticalGrade ? ` ${criticalGrade.toUpperCase()} pending` : ""}${
            finalCriticalRoll !== undefined
              ? `${criticalGrade ? "," : ""} critical roll ${finalCriticalRoll}${getCombatRoundLatestEventDamageLocationSuffix(
                  criticalLocation,
                )}`
              : ""
          }.`
        : "";
    const cap =
      getCombatRoundLatestEventFactBoolean(facts, "maxDamageApplied") === true
        ? ` Raw damage ${
            getCombatRoundLatestEventFactNumber(facts, "rawTotalDamage") ?? totalDamage
          } was capped to ${totalDamage}.`
        : "";

    return {
      commandId: command.id,
      details: `${cap} Critical effects committed: ${criticalEffectsCommitted} row${
        criticalEffectsCommitted === 1 ? "" : "s"
      }.`.trim(),
      phase: command.phase,
      resultId: getCombatRoundLatestEventFactString(facts, "damageResultId"),
      roundNumber: command.roundNumber,
      shortTitle: "Phase damage committed",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, ${phaseLabel}: ${attackerLabel} hit ${defenderLabel} for ${totalDamage} damage${getCombatRoundLatestEventDamageLocationSuffix(
        location,
      )}.${critical}`,
    };
  }

  if (command.type === "roll_critical") {
    const resolution = findCombatRoundLatestEventResolution({ command, state });
    const criticalRoll = resolution?.criticalRoll;
    const proposalDetails = getCombatRoundLatestEventCriticalProposalDetails(
      resolution?.damageResult,
    );
    const finalCriticalRoll =
      criticalRoll?.finalCriticalRoll ??
      getCombatRoundLatestEventFactNumber(facts, "finalCriticalRoll");
    const location =
      criticalRoll?.selectedHitLocation ??
      getCombatRoundLatestEventFactString(facts, "selectedHitLocation");

    return {
      commandId: command.id,
      details: proposalDetails.proposalStatus,
      phase: command.phase,
      resultId: getCombatRoundLatestEventFactString(facts, "attackResultId"),
      roundNumber: command.roundNumber,
      shortTitle: "Critical rolled",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, ${phaseLabel}: ${actorLabel} rolled critical ${
        finalCriticalRoll ?? "?"
      }${getCombatRoundLatestEventDamageLocationSuffix(location)}.`,
    };
  }

  if (command.type === "resolve_damage") {
    const totalDamage = getCombatRoundLatestEventFactNumber(facts, "totalDamage") ?? 0;
    const defenderLabel = getCombatRoundLatestEventLabel({
      labelByParticipantId,
      participantId:
        getCombatRoundLatestEventFactString(facts, "defenderParticipantId") ??
        command.participantId,
    });
    const location = getCombatRoundLatestEventFactString(facts, "selectedHitLocation");
    const criticalGrade = getCombatRoundLatestEventFactString(facts, "criticalGrade");

    return {
      commandId: command.id,
      phase: command.phase,
      resultId: getCombatRoundLatestEventFactString(facts, "damageResultId"),
      roundNumber: command.roundNumber,
      shortTitle: "Damage proposal ready",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, ${phaseLabel}: Damage proposal for ${defenderLabel}: ${totalDamage} damage${getCombatRoundLatestEventDamageLocationSuffix(
        location,
      )}${criticalGrade ? `, Critical ${criticalGrade.toUpperCase()} pending` : ""}.`,
    };
  }

  if (command.type === "roll_hit_location") {
    const location = getCombatRoundLatestEventFactString(facts, "selectedHitLocation");
    const rolls = getCombatRoundLatestEventFactArray(facts, "hitLocationRolls").filter(
      (roll): roll is number => typeof roll === "number",
    );

    return {
      commandId: command.id,
      phase: command.phase,
      resultId: getCombatRoundLatestEventFactString(facts, "attackResultId"),
      roundNumber: command.roundNumber,
      shortTitle: "Hit location rolled",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, ${phaseLabel}: ${actorLabel} hit location ${
        rolls.length > 0 ? `roll ${rolls.join(", ")} ` : ""
      }selected ${getCombatRoundLatestEventHitLocationLabel(location) ?? "unknown location"}.`,
    };
  }

  if (command.type === "roll_parry") {
    const defenderLabel = getCombatRoundLatestEventLabel({
      labelByParticipantId,
      participantId:
        getCombatRoundLatestEventFactString(facts, "defenderParticipantId") ??
        command.participantId,
    });
    const attackerLabel = getCombatRoundLatestEventLabel({
      labelByParticipantId,
      participantId: getCombatRoundLatestEventFactString(facts, "attackerParticipantId"),
    });
    const success = getCombatRoundLatestEventFactBoolean(facts, "success");

    return {
      commandId: command.id,
      phase: command.phase,
      resultId: getCombatRoundLatestEventFactString(facts, "attackResultId"),
      roundNumber: command.roundNumber,
      shortTitle: success ? "Parry succeeded" : "Parry failed",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, ${phaseLabel}: ${defenderLabel} ${
        success ? "parried" : "failed to parry"
      } ${attackerLabel}'s attack.`,
    };
  }

  if (command.type === "roll_attack") {
    const pendingMissileAttack = combatMissileIncomingAttackSchema.safeParse(
      facts.pendingMissileAttack,
    );
    if (pendingMissileAttack.success) {
      const pending = pendingMissileAttack.data;
      const defenderLabel = getCombatRoundLatestEventLabel({
        labelByParticipantId,
        participantId: pending.defenderParticipantId,
      });
      return {
        commandId: command.id,
        details:
          [
            pending.weaponModeRange ? `Range ${pending.weaponModeRange}` : undefined,
            pending.weaponModeSourceMetadata
              ? `${pending.weaponModeSourceMetadata.sheet} row ${pending.weaponModeSourceMetadata.row}`
              : undefined,
          ]
            .filter((value): value is string => Boolean(value))
            .join(" · ") || undefined,
        phase: command.phase,
        resultId: pending.id,
        roundNumber: command.roundNumber,
        shortTitle: "Missile shot committed",
        step: command.step,
        summaryText: `Round ${command.roundNumber}, ${phaseLabel}: ${actorLabel} fired at ${defenderLabel}; awaiting defense review.`,
      };
    }
    const attackResult = findCombatRoundLatestEventAttackResult({ command, state });
    const defenderLabel = getCombatRoundLatestEventLabel({
      labelByParticipantId,
      participantId:
        attackResult?.defenderParticipantId ??
        getCombatRoundLatestEventFactString(facts, "defenderParticipantId"),
    });
    const hit = attackResult?.hit ?? getCombatRoundLatestEventFactBoolean(facts, "hit");
    const grazing = attackResult?.grazing ?? getCombatRoundLatestEventFactBoolean(facts, "grazing");
    const resultLabel = grazing ? "grazed" : hit ? "hit" : "missed";

    return {
      commandId: command.id,
      phase: command.phase,
      resultId:
        getCombatRoundLatestEventFactString(facts, "attackResultId") ??
        (attackResult
          ? getCombatRoundAttackResultId({
              result: attackResult,
              roundNumber: command.roundNumber,
            })
          : undefined),
      roundNumber: command.roundNumber,
      shortTitle: "Attack rolled",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, ${phaseLabel}: ${actorLabel} ${resultLabel} ${defenderLabel}.`,
    };
  }

  if (command.type === "roll_initiative_phase1" || command.type === "roll_initiative_phase2") {
    const phase = command.type === "roll_initiative_phase1" ? "phase1" : "phase2";
    const participant = state.participants.find(
      (entry) => entry.participantId === command.participantId,
    );
    const total = getCombatRoundInitiativeTotal(participant?.initiatives[phase]);

    return {
      commandId: command.id,
      phase,
      roundNumber: command.roundNumber,
      shortTitle: "Initiative recorded",
      step: command.step,
      summaryText: `Round ${command.roundNumber}, ${getCombatRoundLatestEventPhaseLabel(
        phase,
      )}: Initiative recorded for ${actorLabel}${total !== undefined ? ` (${total})` : ""}.`,
    };
  }

  return undefined;
}

export function getLatestCombatEventSummary(
  state: CombatRoundState,
  participants: readonly CombatRoundLatestEventParticipantLabel[] = [],
): CombatRoundLatestEventSummary | undefined {
  const normalized = combatRoundStateSchema.parse(state);
  const timelineStates = getCombatRoundTimelineRoundStates(normalized);
  const labelByParticipantId = new Map<string, string>();

  for (const participant of participants) {
    labelByParticipantId.set(participant.participantId, participant.label);
  }

  for (const timelineState of timelineStates) {
    for (const participant of timelineState.participants) {
      labelByParticipantId.set(participant.participantId, participant.label);
    }
  }

  for (let stateIndex = timelineStates.length - 1; stateIndex >= 0; stateIndex -= 1) {
    const timelineState = timelineStates[stateIndex];

    for (
      let commandIndex = timelineState.commands.length - 1;
      commandIndex >= 0;
      commandIndex -= 1
    ) {
      const command = timelineState.commands[commandIndex];
      const summary = getCombatRoundLatestEventForCommand({
        command,
        labelByParticipantId,
        state: timelineState,
      });

      if (summary) {
        return summary;
      }
    }
  }

  return undefined;
}

export function buildCombatRoundCommandEnvelope(input: {
  latestResult?: CombatRoundCommandEnvelopeResult;
  state: CombatRoundState;
  warnings?: string[];
}): CombatRoundCommandEnvelope {
  const normalized = combatRoundStateSchema.parse(input.state);
  const currentCursor = normalized.currentCursor;

  return {
    currentCursor,
    currentStep: normalized.currentStep,
    currentTask: currentCursor
      ? {
          cursorStep: currentCursor.step,
          participantId: currentCursor.participantId,
          roundNumber: currentCursor.roundNumber,
          step: getCombatRoundStepForCursorStep(currentCursor.step),
        }
      : undefined,
    latestEvent: getLatestCombatEventSummary(normalized),
    latestResult: input.latestResult,
    warnings: input.warnings ?? [],
  };
}

export function getCombatRoundTimelineRoundStates(state: CombatRoundState): CombatRoundState[] {
  const normalized = combatRoundStateSchema.parse(state);
  const completedRounds = normalized.rounds
    .filter((round) => round.roundNumber !== normalized.roundNumber)
    .sort((left, right) => left.roundNumber - right.roundNumber)
    .map((round) =>
      combatRoundStateSchema.parse({
        adjustDistanceProposals: round.adjustDistanceProposals,
        activeParticipantId: round.activeParticipantId,
        breakOffProposals: round.breakOffProposals,
        commands: round.commands,
        continuedContacts: round.continuedContacts,
        currentCursor: round.currentCursor,
        currentStep: round.currentStep,
        defenseSnapshots: round.defenseSnapshots,
        encounterId: round.encounterId ?? normalized.encounterId,
        engagements: round.engagements,
        events: round.events,
        feintProposals: round.feintProposals,
        genericActions: round.genericActions,
        missileReadiness: round.missileReadiness,
        offensiveParryContests: round.offensiveParryContests,
        observationAttempts: round.observationAttempts,
        observationRelationships: round.observationRelationships,
        phaseResolutionCursor: round.phaseResolutionCursor,
        phaseResolutionResults: round.phaseResolutionResults,
        phaseResolutionStatuses: round.phaseResolutionStatuses,
        participants: round.participants,
        roundEndReview: round.roundEndReview,
        roundNumber: round.roundNumber,
        rounds: [],
        selectedParticipantId: round.selectedParticipantId,
        selectedStep: round.selectedStep,
        stepSnapshots: round.stepSnapshots,
        unbalancedConditions: round.unbalancedConditions,
      }),
    );

  return [
    ...completedRounds,
    combatRoundStateSchema.parse({
      ...normalized,
      rounds: [],
    }),
  ];
}

/**
 * Compact, strictly versioned inverse facts for one canonical Perform Task lifecycle command.
 * Only the fields the command actually touched are recorded. Full `CombatRoundState` snapshots are
 * forbidden for new commits by the combat task integration matrix.
 */
export const combatTaskCommandUndoFactsSchema = z
  .object({
    actionId: idSchema,
    commandId: idSchema,
    kind: z.enum(["review", "advance", "roll", "resolve", "interrupt", "cancel"]),
    phase: combatRoundPhaseSchema,
    previousAwarenessContext: z.object({ kind: z.literal("survey") }).optional(),
    previousDuration: combatGenericActionDurationSchema,
    previousLastUpdatedAt: z.string().datetime(),
    previousPhaseResolutionStatus: combatRoundPhaseResolutionParticipantStatusSchema.optional(),
    previousPreset: combatGenericActionPresetSchema.optional(),
    previousProgress: combatGenericActionProgressSchema,
    previousReference: combatGenericActionReferenceSchema.optional(),
    previousResolution: combatGenericActionResolutionSchema.optional(),
    previousRollRequest: combatGenericActionRollRequestSchema.optional(),
    previousRollResult: combatGenericActionRollResultSchema.optional(),
    previousStatus: combatGenericActionStatusSchema,
    previousStepStatus: combatRoundStepStatusSchema.optional(),
    roundNumber: z.number().int().positive(),
    version: z.literal(1),
  })
  .strict();
export type CombatTaskCommandUndoFacts = z.infer<typeof combatTaskCommandUndoFactsSchema>;

export type CombatTaskCommandKind = CombatTaskCommandUndoFacts["kind"];

const COMBAT_TASK_COMMAND_TYPES = {
  advance: "advance_combat_task",
  cancel: "cancel_combat_task",
  interrupt: "interrupt_combat_task",
  resolve: "resolve_combat_task",
  review: "review_combat_task",
  roll: "roll_combat_task",
} as const satisfies Record<CombatTaskCommandKind, CombatRoundCommandType>;

export interface CombatTaskCommandOutcome {
  action: CombatGenericAction;
  command: CombatRoundCommand;
  state: CombatRoundState;
}

function requireCombatRoundOpenPerformTask(input: {
  actionId: string;
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
}): CombatGenericAction {
  if (input.phase !== "phase1") {
    throw new RangeError("Perform Task uses the actor's Phase 1 primary-action opportunity.");
  }
  const action = getCombatRoundOpenPerformTaskForParticipant({
    participantId: input.participantId,
    state: input.state,
  });
  if (!action || action.id !== input.actionId) {
    throw new RangeError("This Combat Task no longer holds the actor's action opportunity.");
  }
  const cursor = input.state.phaseResolutionCursor;
  if (
    cursor?.phase !== input.phase ||
    cursor.participantId !== input.participantId ||
    cursor.substep !== "perform_task"
  ) {
    throw new RangeError("The Combat Task is not the current action opportunity.");
  }
  return action;
}

function applyCombatTaskCommand(input: {
  buildEvent?: (context: { commandId: string; state: CombatRoundState }) => CombatStepEvent;
  command: { commandId?: string; createdAt: string; createdByUserId?: string };
  consumesOpportunity: boolean;
  extraFacts?: Record<string, unknown>;
  kind: CombatTaskCommandKind;
  nextActions: readonly CombatGenericAction[];
  participantId: string;
  phase: CombatRoundPhase;
  previousAction: CombatGenericAction;
  state: CombatRoundState;
  submittedBy: "gm" | "player";
  updatedAt: string;
}): CombatTaskCommandOutcome {
  const normalized = combatRoundStateSchema.parse(input.state);
  const actionStep = getCombatRoundPhaseActionStepForPhase(input.phase);
  const previousAction = combatGenericActionSchema.parse(input.previousAction);
  const previousParticipant = normalized.participants.find(
    (entry) => entry.participantId === input.participantId,
  );
  const beforeCursor = combatRoundCursorSchema.parse({
    participantId: input.participantId,
    roundNumber: normalized.roundNumber,
    step: getCombatRoundAttackCursorStepForPhase(input.phase),
  });
  const commandType = COMBAT_TASK_COMMAND_TYPES[input.kind];
  const commandId =
    input.command.commandId ??
    buildCombatRoundCommandId({
      createdAt: input.command.createdAt,
      participantId: input.participantId,
      state: normalized,
      type: commandType,
    });
  const undoFacts = combatTaskCommandUndoFactsSchema.parse({
    actionId: previousAction.id,
    commandId,
    kind: input.kind,
    phase: input.phase,
    previousAwarenessContext: previousAction.awarenessContext,
    previousDuration: previousAction.duration,
    previousLastUpdatedAt: previousAction.lastUpdatedAt,
    previousPhaseResolutionStatus:
      normalized.phaseResolutionStatuses[input.participantId]?.[input.phase],
    previousPreset: previousAction.preset,
    previousProgress: previousAction.progress,
    previousReference: previousAction.reference,
    previousResolution: previousAction.resolution,
    previousRollRequest: previousAction.rollRequest,
    previousRollResult: previousAction.rollResult,
    previousStatus: previousAction.status,
    previousStepStatus: previousParticipant?.stepStatuses[actionStep],
    roundNumber: normalized.roundNumber,
    version: 1,
  });

  const withActions = combatRoundStateSchema.parse({
    ...normalized,
    genericActions: input.nextActions,
  });
  const advanced = input.consumesOpportunity
    ? moveCombatRoundPhaseResolutionCursorToNextParticipant({
        phase: input.phase,
        state: setCombatRoundParticipantStepStatus({
          participantId: input.participantId,
          state: setCombatRoundPhaseResolutionStatus({
            participantId: input.participantId,
            phase: input.phase,
            state: withActions,
            status: { substep: "done", updatedAt: input.updatedAt },
          }),
          status: input.submittedBy === "gm" ? "gmEdited" : "submitted",
          step: actionStep,
        }),
        updatedAt: input.updatedAt,
      })
    : withActions;
  const afterCursor = advanced.currentCursor ?? beforeCursor;
  const command = combatRoundCommandSchema.parse({
    afterCursor,
    beforeCursor,
    createdAt: input.command.createdAt,
    createdByUserId: input.command.createdByUserId,
    facts: {
      ...(input.extraFacts ?? {}),
      taskId: previousAction.id,
      taskUndo: undoFacts,
    },
    id: commandId,
    participantId: input.participantId,
    phase: input.phase,
    roundNumber: normalized.roundNumber,
    step: beforeCursor.step,
    type: commandType,
  });
  const event = input.buildEvent?.({ commandId, state: advanced });
  const selectedStep = getCombatRoundStepForCursorStep(afterCursor.step);
  const nextAction = combatGenericActionSchema.parse(
    input.nextActions.find((candidate) => candidate.id === previousAction.id),
  );

  return {
    action: nextAction,
    command,
    state: combatRoundStateSchema.parse({
      ...advanced,
      commands: [...advanced.commands, command],
      currentCursor: afterCursor,
      currentStep: selectedStep,
      ...(event ? { events: [...advanced.events, event] } : {}),
      selectedParticipantId: afterCursor.participantId ?? input.participantId,
      selectedStep,
    }),
  };
}

/**
 * Canonical GM review command. It carries every rule input the task needs — duration, roll basis,
 * Skill/Stat, Difficulty, reference and the `look_around` preset — and activates the reviewed task
 * in the same revision so the actor's opportunity is immediately executable.
 */
export function reviewCombatTaskAtOpportunity(input: {
  actionId: string;
  command: { commandId?: string; createdAt: string; createdByUserId?: string };
  duration: CombatGenericActionDuration;
  participantId: string;
  phase: CombatRoundPhase;
  preset?: CombatGenericActionPreset;
  reference?: CombatGenericActionReference;
  rollRequest?: CombatGenericActionRollRequest;
  state: CombatRoundState;
  updatedAt: string;
}): CombatTaskCommandOutcome {
  const normalized = combatRoundStateSchema.parse(input.state);
  const previousAction = requireCombatRoundOpenPerformTask({
    actionId: input.actionId,
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });
  const reviewed = reviewCombatGenericAction({
    actionId: input.actionId,
    actions: normalized.genericActions,
    duration: input.duration,
    preset: input.preset,
    reference: input.reference,
    reviewedAt: input.updatedAt,
    rollRequest: input.rollRequest,
  });
  const activated = activateCombatGenericAction({
    actionId: input.actionId,
    activatedAt: input.updatedAt,
    actions: reviewed,
    roundNumber: normalized.roundNumber,
    step: normalized.currentStep,
  });

  return applyCombatTaskCommand({
    command: input.command,
    consumesOpportunity: false,
    extraFacts: {
      duration: input.duration,
      preset: input.preset,
      requiredAdvances: getCombatGenericActionOpportunityAdvances(input.duration) ?? null,
    },
    kind: "review",
    nextActions: activated,
    participantId: input.participantId,
    phase: input.phase,
    previousAction,
    state: normalized,
    submittedBy: "gm",
    updatedAt: input.updatedAt,
  });
}

/** Records the canonical task roll. The roll does not consume the action opportunity. */
export function rollCombatTaskAtOpportunity(input: {
  actionId: string;
  command: { commandId?: string; createdAt: string; createdByUserId?: string };
  participantId: string;
  phase: CombatRoundPhase;
  result: CombatGenericActionRollResult;
  state: CombatRoundState;
  updatedAt: string;
}): CombatTaskCommandOutcome {
  const normalized = combatRoundStateSchema.parse(input.state);
  const previousAction = requireCombatRoundOpenPerformTask({
    actionId: input.actionId,
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });
  if (previousAction.rollResult) {
    throw new RangeError("This Combat Task roll has already been recorded.");
  }
  const rolled = recordCombatGenericActionRoll({
    actionId: input.actionId,
    actions: normalized.genericActions,
    result: input.result,
  });

  return applyCombatTaskCommand({
    command: input.command,
    consumesOpportunity: false,
    extraFacts: { success: input.result.success },
    kind: "roll",
    nextActions: rolled,
    participantId: input.participantId,
    phase: input.phase,
    previousAction,
    state: normalized,
    submittedBy: "player",
    updatedAt: input.updatedAt,
  });
}

/**
 * Consumes one primary-action opportunity for a multi-round task without resolving it. Refused at
 * the task's final opportunity, which belongs to the resolve command.
 */
export function advanceCombatTaskAtOpportunity(input: {
  actionId: string;
  command: { commandId?: string; createdAt: string; createdByUserId?: string };
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  submittedBy: "gm" | "player";
  updatedAt: string;
}): CombatTaskCommandOutcome {
  const normalized = combatRoundStateSchema.parse(input.state);
  const previousAction = requireCombatRoundOpenPerformTask({
    actionId: input.actionId,
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });
  if (
    previousAction.duration.kind !== "gm_decided" &&
    isCombatGenericActionFinalOpportunity(previousAction)
  ) {
    throw new RangeError("This Combat Task completes at this opportunity and must be resolved.");
  }
  const advancedActions = advanceCombatGenericActionAtOpportunity({
    actionId: input.actionId,
    actions: normalized.genericActions,
    advancedAt: input.updatedAt,
    roundNumber: normalized.roundNumber,
  });

  return applyCombatTaskCommand({
    command: input.command,
    consumesOpportunity: true,
    extraFacts: { status: "advanced" },
    kind: "advance",
    nextActions: advancedActions,
    participantId: input.participantId,
    phase: input.phase,
    previousAction,
    state: normalized,
    submittedBy: input.submittedBy,
    updatedAt: input.updatedAt,
  });
}

/**
 * Consumes the task's final primary-action opportunity, resolves it with the GM-authored
 * player-safe result text and its audience, and emits the canonical `task_resolved` event.
 */
export function resolveCombatTaskAtOpportunity(input: {
  actionId: string;
  command: { commandId?: string; createdAt: string; createdByUserId?: string };
  participantId: string;
  phase: CombatRoundPhase;
  resultText: string;
  state: CombatRoundState;
  updatedAt: string;
  visibleToParticipantIds: readonly string[];
}): CombatTaskCommandOutcome {
  const normalized = combatRoundStateSchema.parse(input.state);
  const previousAction = requireCombatRoundOpenPerformTask({
    actionId: input.actionId,
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });
  const known = new Set(normalized.participants.map((entry) => entry.participantId));
  for (const participantId of input.visibleToParticipantIds) {
    if (!known.has(participantId)) {
      throw new RangeError("Choose active participants for the result audience.");
    }
  }
  // Evaluated before the advance, exactly as `advanceCombatTaskAtOpportunity` evaluates it.
  // `isCombatGenericActionFinalOpportunity` is a pre-advance predicate
  // (`completedRounds + 1 >= required`), so checking it on the already-advanced action would
  // permit resolution one opportunity early for every duration of two advances or more.
  if (!isCombatGenericActionFinalOpportunity(previousAction)) {
    throw new RangeError("This Combat Task cannot resolve before its reviewed timing completes.");
  }
  const advancedActions = advanceCombatGenericActionAtOpportunity({
    actionId: input.actionId,
    actions: normalized.genericActions,
    advancedAt: input.updatedAt,
    roundNumber: normalized.roundNumber,
  });
  const audience = [...new Set([input.participantId, ...input.visibleToParticipantIds])];
  const resolvedActions = finishCombatGenericAction({
    actionId: input.actionId,
    actions: advancedActions,
    at: input.updatedAt,
    resolution: {
      resolvedAt: input.updatedAt,
      resolvedByUserId: input.command.createdByUserId,
      text: input.resultText,
      visibleToParticipantIds: audience,
    },
    status: "completed",
    timing: "primary_action_opportunity",
  });
  const rollResult = previousAction.rollResult;

  return applyCombatTaskCommand({
    buildEvent: ({ commandId, state }) =>
      combatStepEventSchema.parse({
        actorParticipantId: input.participantId,
        commandId,
        completeness: "complete",
        encounterId: normalized.encounterId,
        facts: {
          gmReview: {
            actorUserId: input.command.createdByUserId,
            audienceParticipantIds: audience,
            taskId: input.actionId,
          },
          involvedOutcome: {
            audienceParticipantIds: audience,
            resultText: input.resultText,
            rollOutcome: rollResult ? (rollResult.success ? "succeeded" : "failed") : undefined,
            taskId: input.actionId,
          },
          publicOutcome: { status: "committed", taskId: input.actionId },
        },
        id: `${commandId}:event`,
        missingFacts: [],
        occurredAt: input.updatedAt,
        ownerParticipantId: input.participantId,
        phase: input.phase,
        roundNumber: normalized.roundNumber,
        schemaVersion: 1,
        sequence: getCombatRoundNextEventSequence(state),
        source: {
          commandType: "resolve_combat_task",
          kind: "canonical",
          sourceIds: [commandId, input.actionId],
        },
        status: "committed",
        step: getCombatRoundPhaseActionStepForPhase(input.phase),
        type: "task_resolved",
        visibility: {
          identityRefs: [{ participantId: input.participantId, role: "actor" }],
          involvedParticipantIds: audience,
          outcomeScope: "involved",
        },
      }),
    command: input.command,
    consumesOpportunity: true,
    extraFacts: { audienceParticipantIds: audience, status: "completed" },
    kind: "resolve",
    nextActions: resolvedActions,
    participantId: input.participantId,
    phase: input.phase,
    previousAction,
    state: normalized,
    submittedBy: "gm",
    updatedAt: input.updatedAt,
  });
}

/** GM adjudication that ends the task without a result. Consumes the action opportunity. */
export function finishCombatTaskAtOpportunity(input: {
  actionId: string;
  command: { commandId?: string; createdAt: string; createdByUserId?: string };
  kind: "cancel" | "interrupt";
  participantId: string;
  phase: CombatRoundPhase;
  state: CombatRoundState;
  updatedAt: string;
}): CombatTaskCommandOutcome {
  const normalized = combatRoundStateSchema.parse(input.state);
  const previousAction = requireCombatRoundOpenPerformTask({
    actionId: input.actionId,
    participantId: input.participantId,
    phase: input.phase,
    state: normalized,
  });
  if (input.kind === "interrupt" && previousAction.status !== "active") {
    throw new RangeError("Only an active Combat Task can be interrupted.");
  }
  const finished = finishCombatGenericAction({
    actionId: input.actionId,
    actions: normalized.genericActions,
    at: input.updatedAt,
    status: input.kind === "interrupt" ? "interrupted" : "cancelled",
  });

  return applyCombatTaskCommand({
    command: input.command,
    consumesOpportunity: true,
    extraFacts: { status: input.kind === "interrupt" ? "interrupted" : "cancelled" },
    kind: input.kind,
    nextActions: finished,
    participantId: input.participantId,
    phase: input.phase,
    previousAction,
    state: normalized,
    submittedBy: "gm",
    updatedAt: input.updatedAt,
  });
}

function undoCombatTaskCommandAtIndex(input: {
  commandIndex: number;
  state: CombatRoundState;
}): CombatRoundState | undefined {
  const normalized = combatRoundStateSchema.parse(input.state);
  const command = normalized.commands[input.commandIndex];
  if (!command || command.roundNumber !== normalized.roundNumber) return undefined;

  const parsed = combatTaskCommandUndoFactsSchema.safeParse(command.facts.taskUndo);
  if (!parsed.success) return undefined;
  const undo = parsed.data;
  if (
    undo.commandId !== command.id ||
    undo.roundNumber !== command.roundNumber ||
    undo.phase !== command.phase
  ) {
    return undefined;
  }

  const actionStep = getCombatRoundPhaseActionStepForPhase(undo.phase);
  const genericActions = normalized.genericActions.map((candidate) =>
    candidate.id === undo.actionId
      ? combatGenericActionSchema.parse({
          ...candidate,
          awarenessContext: undo.previousAwarenessContext,
          duration: undo.previousDuration,
          lastUpdatedAt: undo.previousLastUpdatedAt,
          preset: undo.previousPreset,
          progress: undo.previousProgress,
          reference: undo.previousReference,
          resolution: undo.previousResolution,
          rollRequest: undo.previousRollRequest,
          rollResult: undo.previousRollResult,
          status: undo.previousStatus,
        })
      : candidate,
  );
  const participantStatuses = {
    ...normalized.phaseResolutionStatuses[command.participantId],
    [undo.phase]: undo.previousPhaseResolutionStatus,
  };
  const selectedStep = getCombatRoundStepForCursorStep(command.beforeCursor.step);

  return combatRoundStateSchema.parse({
    ...normalized,
    commands: normalized.commands.filter((_, index) => index !== input.commandIndex),
    currentCursor: command.beforeCursor,
    currentStep: selectedStep,
    genericActions,
    participants: normalized.participants.map((participant) =>
      participant.participantId === command.participantId
        ? {
            ...participant,
            stepStatuses:
              undo.previousStepStatus === undefined
                ? Object.fromEntries(
                    Object.entries(participant.stepStatuses).filter(
                      ([step]) => step !== actionStep,
                    ),
                  )
                : { ...participant.stepStatuses, [actionStep]: undo.previousStepStatus },
          }
        : participant,
    ),
    phaseResolutionCursor: {
      participantId: command.participantId,
      phase: undo.phase,
      substep: "perform_task",
    },
    phaseResolutionStatuses: {
      ...normalized.phaseResolutionStatuses,
      [command.participantId]: participantStatuses,
    },
    selectedParticipantId: command.beforeCursor.participantId ?? command.participantId,
    selectedStep,
  });
}
